BEGIN;
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '92b52fb4-1496-5fcb-a776-fce642fd4b78','ADR ambience bed','A continuous background ambience track — room tone or environmental sound — laid underneath a replaced ADR line so the dry studio recording blends seamlessly with the surrounding production soundscape.','ADR means automated dialogue replacement. New studio lines sound too clean. Editors add a steady background sound beneath them. That helps the new lines blend into the scene.','It masks the acoustic gap between clean studio ADR and the noisier production location, giving the re-recorded line a believable sense of place. It exists because ADR is captured dry, without the scene''s own background.','A dialogue editor lays a matching room-tone or ambience loop beneath each ADR cue, then sets its level so cuts into and out of the line are inaudible.','ADR matching',ARRAY['Room tone','ADR match','ADR room mismatch','Ambience','Production dialogue']::text[],ARRAY['Using a generic ambience instead of the scene''s actual recorded room tone, so the bed does not match','Setting the bed too loud, which draws attention rather than hiding the edit','Not extending the ambience bed through the whole line, leaving a silent gap around the ADR']::text[],ARRAY['Blending a studio-recorded ADR line into an exterior street scene','Filling the acoustic hole left when noisy production dialogue is replaced','Smoothing the transition between production dialogue and an ADR insert in the same scene']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='92b52fb4-1496-5fcb-a776-fce642fd4b78' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR ambience bed'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '92b52fb4-1496-5fcb-a776-fce642fd4b78','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='92b52fb4-1496-5fcb-a776-fce642fd4b78' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '895901fa-6c94-5a02-ab0e-acf063fce68d','ADR comp','A composite ADR performance assembled by selecting and combining the best portions of several recorded takes of the same cue into one continuous, sync-accurate line.','ADR means automated dialogue replacement. Actors record a line many times. The editor picks the best bits from each take. Those bits are joined into one final line.','It lets the editor build the strongest reading — best sync, tone, and emotion — from many attempts instead of relying on one perfect take. It exists because no single take is usually ideal across the whole line.','Using playlists or a take list, the editor auditions each loop-recorded take and comps chosen words or phrases into a final composite that matches picture.','ADR editing',ARRAY['Take','Loop recording','Playlist','ADR edit','ADR fit','ADR cue']::text[],ARRAY['Comping for performance while ignoring sync, so the joined pieces no longer line up with picture','Switching between takes with different mic distance or tone, creating audible jumps within one line','Not crossfading comp edit points, leaving clicks or pops at the joins']::text[],ARRAY['Combining the best half of one take with the best half of another for a single line','Building a clean composite from many loop-recorded passes of a shouted line','Fixing one mispronounced word by comping it from an alternate take']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='895901fa-6c94-5a02-ab0e-acf063fce68d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR comp'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '895901fa-6c94-5a02-ab0e-acf063fce68d','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='895901fa-6c94-5a02-ab0e-acf063fce68d' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a1cf2052-dc5d-5f28-8cab-88bb2164e1a2','ADR cue','A single line or passage of dialogue marked for re-recording, defined by its timeline In and Out points, character, and text, and identified by a unique cue number.','ADR means automated dialogue replacement. A cue is one line that must be re-recorded. It has a start point, an end point, and the words. Each cue gets its own number.','It breaks a reel''s replacement work into discrete, trackable units so the actor, mixer, and editor all know exactly which line is being recorded. It exists to organize the ADR session line by line.','The supervisor spots the film and creates one cue per problem line; during the session each cue is loaded, played to the actor, and recorded in turn.','ADR workflow',ARRAY['ADR cue number','ADR cueing','ADR guide','Spotting session','ADR pre-roll','ADR post-roll']::text[],ARRAY['Setting cue In and Out points too tightly, cutting off breaths or word tails needed for a natural read','Confusing a cue (one line) with a whole scene, recording far more than the marked passage','Leaving cue text blank, so the actor and mixer cannot confirm the exact wording']::text[],ARRAY['Spotting a reel and marking every unusable production line as a separate cue','Loading the next cue in a Pro Tools ADR session to record it','Exporting a cue list to a spreadsheet for the ADR stage']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a1cf2052-dc5d-5f28-8cab-88bb2164e1a2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR cue'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a1cf2052-dc5d-5f28-8cab-88bb2164e1a2','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a1cf2052-dc5d-5f28-8cab-88bb2164e1a2' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fa7decfe-1638-5240-91ce-bec85e5cd702','ADR cue number','The unique identifier assigned to each ADR cue, typically encoding reel and sequential order, used to track a line consistently across the cue sheet, recording session, and final mix.','ADR means automated dialogue replacement. Every ADR line to be re-recorded gets its own number. The number stays with that line everywhere. It keeps takes and paperwork organized.','It gives every replacement line a stable label so takes, notes, and edits can be matched to the correct line without confusion. It exists to keep large ADR sessions traceable.','The editor names recorded takes and files by cue number so that, months later, any line can be located and its takes retrieved instantly.','ADR workflow',ARRAY['ADR cue','ADR cueing','Take','Reel','ADR guide']::text[],ARRAY['Renumbering cues midway through a project, so takes no longer match the paperwork','Reusing the same cue number across different reels, causing files to be confused','Labeling take files by content instead of cue number, making later retrieval slow']::text[],ARRAY['Naming every recorded take with its cue number during the session','Cross-referencing a mixer''s note to the exact line by its cue number','Sorting the ADR cue sheet by reel and cue number before a session']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fa7decfe-1638-5240-91ce-bec85e5cd702' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR cue number'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fa7decfe-1638-5240-91ce-bec85e5cd702','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fa7decfe-1638-5240-91ce-bec85e5cd702' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4efcc492-9ed4-56e8-b967-44d8da8d5138','ADR cueing','The process of preparing and delivering timing cues — visual streamers and audio beeps, commonly a three-beep countdown at one-second intervals with the actor beginning on the silent fourth beep as the streamer reaches the sync point — that lead an actor precisely to the start of each ADR line.','ADR means automated dialogue replacement. Cueing gives the actor a countdown. They hear beeps and see moving lines on screen. This tells them exactly when to speak.','It gives the performer a consistent, predictable countdown so the replacement line starts in sync with picture. It exists because actors need an accurate cue to hit lip-sync without a click track.','The ADR system plays a pre-roll with three beeps while a streamer converges at the In point; the actor speaks as the final beep hits, keeping the take in sync.','ADR workflow',ARRAY['Streamer','Beep','ADR pre-roll','ADR post-roll','ADR cue','Lip sync']::text[],ARRAY['Setting the pre-roll too short, so the actor cannot settle into rhythm before the line','Changing beep spacing from the studio standard, throwing off an experienced actor''s timing','Relying only on beeps with no visual streamer, making precise sync harder for the performer']::text[],ARRAY['Setting up beeps and streamers before an ADR recording session','Adjusting pre-roll length so an actor can prepare for a fast line','Guiding an actor to hit lip-sync on a close-up without a visible click']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4efcc492-9ed4-56e8-b967-44d8da8d5138' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR cueing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4efcc492-9ed4-56e8-b967-44d8da8d5138','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4efcc492-9ed4-56e8-b967-44d8da8d5138' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0931b27f-841e-5713-8415-d4da5e540bce','ADR edit','The editorial work of cutting recorded ADR into the timeline — trimming, sliding for sync, comping takes, and adding fades — so the re-recorded line sits seamlessly against picture and surrounding production dialogue.','ADR means automated dialogue replacement. Editing means cutting the new line to fit. The editor lines it up with the actor''s lips. They also match the pace of the old dialogue.','It turns raw ADR takes into a finished, in-sync line the re-recording mixer can blend into the scene. It exists because recorded takes rarely line up with picture perfectly on their own.','After recording, the ADR editor slides each take word by word to lip-sync, comps the best readings, and adds fades before handing tracks to the mix.','ADR editing',ARRAY['ADR fit','ADR comp','Lip sync','ADR cue','Dialogue editing','ADR match']::text[],ARRAY['Matching the first word to picture but letting later words drift out of sync','Editing for tight sync while ignoring the natural rhythm and breaths of the read','Leaving hard cuts without fades, so edits click against the room tone']::text[],ARRAY['Syncing a re-recorded line to a close-up of the actor''s mouth','Cutting ADR to replace dialogue ruined by location noise','Preparing edited ADR tracks for the final dialogue premix']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0931b27f-841e-5713-8415-d4da5e540bce' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR edit'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0931b27f-841e-5713-8415-d4da5e540bce','f3b91616-66f6-414b-a35a-23a86671f275',true
