INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5f33045a-bd9b-5b20-a705-04e3466bf918','ADR fit','The craft of adjusting a recorded ADR take to conform to the picture and the original performance — stretching, compressing, and sliding words and syllables to achieve lip-sync and match the production line''s rhythm.','ADR means automated dialogue replacement. Fitting means reshaping the new line to match. The editor moves and stretches words. The goal is matching the actor''s lips and timing.','It brings a take that is close but not exact into precise lip-sync and pacing with the original delivery. It exists because even a good ADR take needs micro-adjustment to match picture.','The editor uses time-warp or manual cuts to fit each syllable to the lip movements, sometimes aided by alignment tools like VocALign that lock the take to the guide.','ADR editing',ARRAY['ADR edit','Lip sync','VocALign','ADR guide','ADR comp','Time compression']::text[],ARRAY['Over-stretching audio to force sync, creating audible artifacts in the voice','Fitting only the mouth open and close while ignoring consonant timing','Trusting an automatic alignment tool without checking the result against picture']::text[],ARRAY['Nudging syllables so a replacement line matches a visible lip movement','Using VocALign to align an ADR take to the production guide track','Time-fitting a slightly long take into the exact length of the original line']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5f33045a-bd9b-5b20-a705-04e3466bf918' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR fit'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5f33045a-bd9b-5b20-a705-04e3466bf918','f3b91616-66f6-414b-a35a-23a86671f275',true
