INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cc0d3613-de77-5f7a-9363-241dcc83ab1c','ADR futzing','Processing an ADR line so it sounds as though heard through a limited-bandwidth device — telephone, radio, television, or intercom — typically via band-limiting EQ, distortion, and added noise, to match how the source is heard in the scene.','Futzing makes a clean recording sound like it comes through a device. ADR means automated dialogue replacement. A line might need to sound like a phone call. Editors cut the highs and lows and add grit.','It makes a studio-clean ADR line believable as sound coming from a phone, speaker, or radio in the story. It exists because clean dialogue would break the illusion of a device source.','The editor applies a band-pass EQ and light distortion, often with a dedicated futz plugin, to an ADR line meant to be heard over a character''s phone.','Dialogue processing',ARRAY['Futz','Band-pass filter','Worldizing','EQ','ADR match','Distortion']::text[],ARRAY['Futzing so heavily the dialogue becomes hard to understand','Applying a phone futz without deciding whether the audience hears the caller directly or through the phone','Forgetting to remove the futz on a reverse angle when the perspective changes']::text[],ARRAY['Making an ADR line sound like it comes through a character''s cell phone','Processing a public-address announcement recorded clean in the studio','Turning a clean line into a radio broadcast heard inside a car']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cc0d3613-de77-5f7a-9363-241dcc83ab1c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR futzing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cc0d3613-de77-5f7a-9363-241dcc83ab1c','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cc0d3613-de77-5f7a-9363-241dcc83ab1c' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '24d3fbf5-be0a-5ea9-8d0a-249aac2fe30b','ADR guide','The original production recording of a line, played to the actor and editor during ADR as a reference for timing, rhythm, and delivery of the replacement performance; also called the guide track.','ADR means automated dialogue replacement. The guide is the original recording of the line. The actor listens to it to copy the timing. The editor uses it to match sync.','It gives the actor a model to match and the editor a sync reference, even when the original is too noisy to use in the final mix. It exists so the replacement matches the original performance.','The actor wears headphones and listens to the guide track a few times, then performs to match its rhythm while watching picture.','ADR workflow',ARRAY['Guide track','Production dialogue','ADR cue','Lip sync','ADR fit','ADR cueing']::text[],ARRAY['Discarding the guide track too early, losing the sync and performance reference','Copying the guide so literally that the new read sounds flat and imitative','Confusing the noisy guide with a usable final take']::text[],ARRAY['Playing the original noisy line to the actor before recording ADR','Aligning an ADR take against the guide track for sync','Comparing a replacement read to the guide to preserve the original emotion']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='24d3fbf5-be0a-5ea9-8d0a-249aac2fe30b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR guide'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '24d3fbf5-be0a-5ea9-8d0a-249aac2fe30b','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='24d3fbf5-be0a-5ea9-8d0a-249aac2fe30b' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '06332b88-6dc9-5caf-b765-848a1105c470','ADR match','The goal and process of making a re-recorded ADR line match the production dialogue it replaces in tone, level, perspective, room acoustics, and background ambience, so it is indistinguishable in the mix.','ADR means automated dialogue replacement. Matching makes the new line sound like the old one. Editors match its tone, loudness, and room sound. Done well, no one notices the swap.','It ensures the audience cannot tell which lines were replaced, preserving the seamless illusion of the scene. It exists because dry studio ADR sounds nothing like on-set production audio by default.','Using EQ, reverb, and ambience, the editor and mixer match an ADR line to the neighboring production lines in the same scene.','ADR matching',ARRAY['ADR perspective match','ADR room mismatch','ADR ambience bed','EQ','Reverb','Production dialogue']::text[],ARRAY['Matching EQ tone but ignoring room reverb, so the line still sounds too dry','Setting the ADR level louder than the production lines around it','Matching only the first replaced line and leaving others in the scene inconsistent']::text[],ARRAY['Blending one replaced line among several production lines in a dialogue scene','Matching ADR to production dialogue with EQ and reverb tools','Making an ADR-heavy scene sound like it was all captured on location']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='06332b88-6dc9-5caf-b765-848a1105c470' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR match'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '06332b88-6dc9-5caf-b765-848a1105c470','f3b91616-66f6-414b-a35a-23a86671f275',true
