INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '19c5c411-a64b-5757-a6c2-b55b4ac44951','ADR perspective match','Matching the apparent mic distance and room character of an ADR line to the production shot — closer and drier for a close-up, more distant and roomier for a wide — so the replaced line''s perspective agrees with the image.','ADR means automated dialogue replacement. Perspective is how near or far a voice sounds. A close-up needs a close sound. A wide shot needs a more distant sound. Editors match this.','It keeps the sonic distance of a voice consistent with the camera framing, so a wide shot does not sound like a close-up. It exists because studio ADR is recorded close and must be repositioned to fit the shot.','For a wide shot the mixer adds room and eases off the close-mic weight so the ADR sits back; for a close-up the line stays present and dry.','ADR matching',ARRAY['ADR match','Perspective','ADR proximity mismatch','Reverb','ADR room mismatch','Mic distance']::text[],ARRAY['Leaving every ADR line close and dry regardless of shot size','Adding so much room for a wide shot that dialogue clarity is lost','Ignoring perspective changes between cuts within the same scene']::text[],ARRAY['Matching an ADR line to a wide establishing shot of a room','Keeping ADR present and close on a tight close-up','Adjusting perspective as the edit cuts between wide and close shots']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='19c5c411-a64b-5757-a6c2-b55b4ac44951' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR perspective match'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '19c5c411-a64b-5757-a6c2-b55b4ac44951','f3b91616-66f6-414b-a35a-23a86671f275',true
