INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '55866546-ca0f-5713-8691-7347fd55a73c','ADR post-roll','The stretch of picture and sound played after a cue''s Out point during ADR, so the actor can carry the line to a natural finish and the editor keeps handle beyond the cue.','ADR means automated dialogue replacement. Post-roll is the part that keeps playing after the line ends. It lets the actor finish naturally. It also gives the editor extra room.','It prevents the recording from stopping abruptly at the Out point, giving a natural tail and edit handles. It exists so the take does not feel cut off and the editor has material to work with.','The ADR system is set to roll a couple of seconds past the Out point so the actor completes the thought and breath before playback stops.','ADR workflow',ARRAY['ADR pre-roll','ADR cueing','ADR cue','Handle','Take']::text[],ARRAY['Setting no post-roll, so the recording stops before the line''s tail and breath','Making post-roll so long it wastes session time on every take','Trimming away the post-roll handle in editing, then needing it later']::text[],ARRAY['Letting an actor finish a sentence naturally after the cue Out point','Capturing the breath and tail after a shouted line','Keeping edit handles past the line for later fades']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='55866546-ca0f-5713-8691-7347fd55a73c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR post-roll'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
