INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cb20eead-7f9d-566b-90e3-e002cd606410','ADR pre-roll','The lead-in of picture, guide audio, and cueing signals (beeps and streamer) played before a cue''s In point, so the actor can prepare and arrive in sync at the line''s start.','ADR means automated dialogue replacement. Pre-roll is the run-up before the line. The actor hears the guide and beeps. This helps them start right on time.','It gives the performer time to hear context, settle into rhythm, and hit the In point precisely with the countdown. It exists because a cold start would make accurate lip-sync nearly impossible.','The system rolls a couple of seconds of lead-in with three beeps and a converging streamer so the actor speaks exactly as the final beep lands.','ADR workflow',ARRAY['ADR post-roll','ADR cueing','Streamer','Beep','ADR cue','ADR guide']::text[],ARRAY['Setting pre-roll too short for the actor to prepare, hurting sync','Making pre-roll inconsistent between cues, disrupting the actor''s rhythm','Starting the guide track only at the In point, giving no run-up context']::text[],ARRAY['Giving an actor a lead-in before a fast line of dialogue','Playing three beeps during pre-roll to count the actor in','Setting a standard pre-roll length for a whole ADR session']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cb20eead-7f9d-566b-90e3-e002cd606410' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR pre-roll'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cb20eead-7f9d-566b-90e3-e002cd606410','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cb20eead-7f9d-566b-90e3-e002cd606410' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '48879b16-c1bd-5c3e-bdf2-4d4cc230ac15','ADR proximity mismatch','A perspective error in which an ADR line''s mic distance does not match the production dialogue — commonly excess low-frequency proximity effect from close-miking in the studio — making the replacement sound closer or bassier than the shot warrants.','ADR means automated dialogue replacement. Proximity is how close the mic was. Studio mics are often very close. That adds extra bass. Then the new line sounds nearer than the scene.','Naming this error helps editors diagnose why an ADR line sounds too close or bassy and correct the mic distance or EQ. It exists as a checkpoint in matching ADR perspective to picture.','Hearing an over-bassy, too-close ADR line, the editor rolls off proximity-effect low end with EQ or backs the mic off in a re-record to match the shot.','ADR matching',ARRAY['Proximity effect','ADR perspective match','ADR match','ADR room mismatch','Mic distance','EQ']::text[],ARRAY['Fixing tone with EQ alone when the mic distance itself is wrong','Close-miking every ADR line regardless of the shot''s perspective','Not comparing the ADR line''s proximity to the production dialogue in the same scene']::text[],ARRAY['An ADR line sounding bassy and intimate over a wide shot','Comparing a too-close ADR take to distant production dialogue','Rolling off proximity-effect bass to match a replacement line to the scene']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='48879b16-c1bd-5c3e-bdf2-4d4cc230ac15' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR proximity mismatch'),'[^a-z0-9]','','g'));
