SELECT '48879b16-c1bd-5c3e-bdf2-4d4cc230ac15','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='48879b16-c1bd-5c3e-bdf2-4d4cc230ac15' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ec242e9b-72ce-5784-b2c9-c504d2b740db','ADR room mismatch','An acoustic error in which an ADR line''s studio room sound — reverb, tone, and background — fails to match the production location, so the replacement stands out as recorded elsewhere.','ADR means automated dialogue replacement. A room mismatch means the sound of the space is wrong. Studio lines sound dry and clean. The scene''s room sounds different. The swap becomes obvious.','Naming this error helps editors spot when an ADR line''s acoustic space does not fit the scene and fix it with reverb or ambience. It exists as a checkpoint in room and ambience matching.','When a dry ADR line clashes with a reverberant location, the editor adds matching reverb and a room-tone bed to place it in the same space.','ADR matching',ARRAY['Room tone','ADR ambience bed','ADR match','Reverb','ADR perspective match']::text[],ARRAY['Adding reverb without matching the scene''s real room tone underneath','Using a preset room sound instead of the location''s actual acoustic character','Fixing one line''s room but leaving other ADR in the scene mismatched']::text[],ARRAY['A dry studio line dropped into a tiled bathroom scene','Matching ADR reverb to a large echoing warehouse location','Adding room tone so a replaced line shares the scene''s background']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ec242e9b-72ce-5784-b2c9-c504d2b740db' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR room mismatch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ec242e9b-72ce-5784-b2c9-c504d2b740db','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ec242e9b-72ce-5784-b2c9-c504d2b740db' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fffebe3f-7a0f-5de9-b170-75eb0279fd1a','ADR spotting','The process, usually conducted in a spotting session, in which the supervising sound editor, dialogue editor, director and/or picture editor review the locked picture and identify every line of production dialogue that must be re-recorded or newly recorded via ADR, logging each cue''s timecode in and out, character, line, and reason for replacement.','ADR stands for automatic dialogue replacement. Spotting is the step where the team watches the finished edit and marks every line that must be re-recorded. They note the exact time and reason for each one.','It creates the master ADR cue list that drives scheduling, talent booking, and studio time, ensuring no problem line is missed and every replacement is justified before costly recording sessions begin.','A dialogue editor sits with the director, plays the cut, and enters each flagged line into ADR cueing software, generating cue sheets and reports for the recording stage and talent.','ADR workflow',ARRAY['Automatic dialogue replacement','Additional dialogue recording','ADR wipe','ADR target','Booth tone']::text[],ARRAY['Confusing spotting with the actual ADR recording session; spotting only identifies and logs cues, it does not record them.','Failing to note the reason for each cue (noise, off-mic, performance, script change), which leaves the mixer and talent without context.','Spotting before picture lock, so cues shift and timings become invalid when the edit changes.']::text[],ARRAY['A supervising sound editor and director hold a spotting session on a feature to list every line lost to on-set traffic noise.','A television dialogue editor spots an episode for network-mandated language changes, logging each swap as an ADR cue.','A post facility exports ADR cue sheets from a spotting pass so a studio can schedule the lead actor''s booking.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fffebe3f-7a0f-5de9-b170-75eb0279fd1a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR spotting'),'[^a-z0-9]','','g'));
