INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f1e9109a-4eb8-553b-9b7b-9930486f1b30','ADR squeeze','The time-compression of a recorded ADR take so a slightly long performance fits the shorter on-screen duration of the original line, shortening the clip without raising its pitch by means of a time-compression/expansion (TCE) or elastic-audio algorithm.','Sometimes a re-recorded line runs a little too long for the picture. A squeeze shrinks the take in time so it fits, without making the voice sound higher. It is like gently speeding up speech while keeping the same pitch.','It lets an editor lock replaced dialogue to the actor''s lip movements when a new take drifts long, preserving sync and natural pitch instead of forcing the actor to re-perform.','In Pro Tools an editor selects a long ADR take and applies Time Compression/Expansion, or uses an alignment tool such as VocALign or Revoice Pro to tighten it onto the guide and sync points.','ADR editing',ARRAY['ADR stretch','ADR target','Automatic dialogue replacement','Bilabial sync point','Cadence match']::text[],ARRAY['Squeezing too aggressively, which introduces audible artifacts and an unnatural, clipped delivery.','Compressing the whole clip evenly instead of only the section that drifts, throwing off internal sync points.','Assuming a squeeze can fix a take that is grossly out of sync rather than re-recording it.']::text[],ARRAY['An editor trims a wordy ADR take by a few frames so the final consonant lands on the actor''s lip closure.','A mixer squeezes a replacement line that ran long because the actor paused mid-sentence.','A dialogue editor uses elastic audio to squeeze an ADR take onto a fast-paced original delivery.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f1e9109a-4eb8-553b-9b7b-9930486f1b30' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR squeeze'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f1e9109a-4eb8-553b-9b7b-9930486f1b30','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f1e9109a-4eb8-553b-9b7b-9930486f1b30' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '99694224-638d-5b45-8e2e-5a34c7362669','ADR stretch','The time-expansion of a recorded ADR take so a slightly short performance fills the longer on-screen duration of the original line, lengthening the clip without lowering its pitch via a time-compression/expansion (TCE) or elastic-audio algorithm.','Sometimes a re-recorded line is a little too short for the picture. A stretch lengthens the take in time so it fits, without making the voice sound lower. It is like slowing speech a bit while keeping the same pitch.','It aligns replaced dialogue to the actor''s lip movements when a new take falls short, keeping sync and natural pitch without a re-take.','An editor applies Time Compression/Expansion or an alignment tool to stretch a short ADR take across the original line''s duration, matching its sync points.','ADR editing',ARRAY['ADR squeeze','ADR target','Automatic dialogue replacement','Bilabial sync point','Cadence match']::text[],ARRAY['Stretching too far, which produces a smeared, warbly artifact and slows the delivery unnaturally.','Expanding the entire clip instead of the drifting portion, misaligning the rest of the line.','Relying on stretch to salvage a take that is far too short rather than recording another pass.']::text[],ARRAY['An editor lengthens a clipped ADR take so the actor''s final word covers the on-screen mouth movement.','A dialogue editor stretches a rushed replacement line to match a slower original delivery.','A mixer uses elastic audio to expand a short ADR take onto the guide track''s timing.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='99694224-638d-5b45-8e2e-5a34c7362669' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR stretch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '99694224-638d-5b45-8e2e-5a34c7362669','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='99694224-638d-5b45-8e2e-5a34c7362669' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9f413852-f757-5be0-8553-25b088218a13','ADR take lane','A playlist lane on an ADR track that holds one recorded take of a cue, so that multiple takes of the same line are stacked as alternate lanes beneath the main track for auditioning, rating, and comping into a final performance.','During ADR the actor records a line many times. Each take is stored on its own lane, stacked under the track. The editor can then compare lanes and pick the best parts to build one final version.','It organizes the many takes captured for a single cue so the editor can quickly review, rate, and combine them, rather than losing alternates or overwriting good performances.','In Pro Tools an engineer records ADR using loop record or playlists; each pass lands on a new take lane, and the editor later comps selections up to the main playlist.','ADR editing',ARRAY['Automatic dialogue replacement','ADR target','ADR squeeze','ADR stretch','Cadence match']::text[],ARRAY['Recording over a previous take instead of creating a new lane, destroying a usable performance.','Forgetting to name or rate lanes, making it hard to find the chosen take later.','Comping across lanes without matching level and tone, so the assembled line jumps in quality.']::text[],ARRAY['An engineer loop-records six passes of a difficult line, each stacked as its own take lane.','A dialogue editor comps a final read from the best words across several take lanes.','A supervisor reviews rated take lanes with the director to approve the keeper for the mix.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9f413852-f757-5be0-8553-25b088218a13' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR take lane'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9f413852-f757-5be0-8553-25b088218a13','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9f413852-f757-5be0-8553-25b088218a13' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '65bf5c51-a259-500f-8bad-2054bece843d','ADR target','The reference an actor aims to match during ADR, typically the original production (guide) recording of the line together with its corresponding on-screen lip movements, against which each new take''s sync, timing, and delivery are judged.','The target is what the new recording must match. It is the original line and the actor''s mouth movements on screen. Every take is compared against this goal for timing and delivery.','It gives the actor, editor, and director a fixed reference so replaced dialogue lands in sync and matches the original intent, rather than drifting into a different reading.','An engineer plays the guide track and picture in the actor''s headphones as the target, then records passes and checks each against that reference for sync and performance.','ADR sync',ARRAY['Automatic dialogue replacement','Bilabial sync point','Cadence match','ADR squeeze','ADR wipe']::text[],ARRAY['Treating a rough guide track as an optional reference and drifting off the original timing.','Matching only the words while ignoring the target''s lip-closure sync points.','Chasing an unusable, noisy guide so closely that the new take copies its flaws instead of its timing.']::text[],ARRAY['An actor watches the on-screen lip movements as the sync target while looping a line.','An editor checks each take against the guide-track target to confirm timing.','A director asks the actor to match the emotional target of the original take, not just the words.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='65bf5c51-a259-500f-8bad-2054bece843d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR target'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '65bf5c51-a259-500f-8bad-2054bece843d','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='65bf5c51-a259-500f-8bad-2054bece843d' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'acdb3627-5a1d-55cb-b99f-eb97815d3669','ADR tonal match','The processing of an ADR recording, through equalization, reverberation, and ambience matching, so its timbre and spatial character match the surrounding production dialogue, which was captured in a different acoustic space and microphone perspective.','A studio-recorded line sounds cleaner and closer than the location sound around it. Tonal matching shapes the new line so it sits in the same space. Engineers add matching tone and room echo so the swap is not obvious.','It makes replaced dialogue blend seamlessly with retained production lines so the audience never hears the edit, preserving the illusion of a single continuous performance in one place.','A dialogue editor or re-recording mixer applies EQ and matching reverb, or a spectral tool such as iZotope RX Dialogue Match, to align the ADR''s tone with the scene''s production sound.','ADR processing',ARRAY['Automatic dialogue replacement','Booth tone','Booth-mode coloration','ADR target','Cadence match']::text[],ARRAY['Matching level but not tone, so the ADR sounds too clean and forward against the location sound.','Adding reverb without matching the microphone perspective, leaving the line sounding pasted on.','Baking tone-matching into the booth recording instead of the mix, then being unable to undo it later.']::text[],ARRAY['A mixer equalizes a booth-recorded line to match the muffled tone of an exterior scene.','An editor uses spectral matching to blend ADR into surrounding production dialogue.','A re-recording mixer adds room reverb so a replaced line matches a reverberant hallway.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='acdb3627-5a1d-55cb-b99f-eb97815d3669' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR tonal match'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'acdb3627-5a1d-55cb-b99f-eb97815d3669','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='acdb3627-5a1d-55cb-b99f-eb97815d3669' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd1e94640-70c2-5832-baca-ec5102df0ac2','ADR wipe','A streamer-style visual cue in which a vertical line sweeps across the picture and reaches the frame edge exactly on the cue''s sync point, giving the performer a moving lead-in that shows precisely when to begin speaking.','A wipe is a moving line that slides across the screen during ADR. When it reaches the edge, the actor should start the line. It works like a visual countdown that hits zero right on cue.','It provides a reliable, glanceable start signal so the actor begins on time without watching a clock, complementing or replacing the audible three-beep countdown.','ADR cueing software or a re-recording mixer generates a wipe and beeps for each cue; the actor watches the line travel across the picture and speaks as it reaches the end.','ADR cueing',ARRAY['Automatic dialogue replacement','Bande rythmo','ADR spotting','ADR target','Bilabial sync point']::text[],ARRAY['Confusing the ADR wipe (a visual timing cue) with a scene-transition wipe used in picture editing.','Relying only on beeps and ignoring the visual wipe, causing late entrances on fast cues.','Setting the wipe to end after the sync point, so the actor consistently comes in late.']::text[],ARRAY['An actor watches a wipe travel across the screen and starts the line as it reaches the edge.','A mixer enables wipes and beeps in the cueing system for a run of short ADR lines.','A supervisor uses wipes instead of beeps for a music-heavy ADR session where beeps would be masked.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d1e94640-70c2-5832-baca-ec5102df0ac2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ADR wipe'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd1e94640-70c2-5832-baca-ec5102df0ac2','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d1e94640-70c2-5832-baca-ec5102df0ac2' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cb36fb0a-942b-5f31-bc5b-7eddc0a0255c','Additional dialogue recording','One expansion of the acronym ADR, used for the studio re-recording of dialogue in sync to picture; some practitioners reserve ''additional'' for newly written or added lines (such as off-screen or revised dialogue) as distinct from straight replacement of existing production lines.','Additional dialogue recording is one name for ADR. It means recording speech in a studio to match the picture. Some people use the word additional for brand-new lines that were not in the original shoot.','The label captures ADR''s wider use beyond fixing bad lines, covering added narration, off-screen lines, revised story dialogue, or crowd voices that were never recorded on set.','A studio may book an actor for additional dialogue recording to voice a new off-screen line the editor added, or to record lines for a scene reshaped after the shoot.','ADR fundamentals',ARRAY['Automatic dialogue replacement','ADR spotting','Background principal','Booth tone','ADR target']::text[],ARRAY['Assuming ''additional'' always means new lines; it is widely used as a plain synonym for ADR.','Confusing added story dialogue with pickup shots, which involve re-filming, not just re-recording.','UNSAFE: Driving actor headphone (foldback) levels too high during long sessions, risking noise-induced hearing loss; keep monitoring within recognized exposure limits.']::text[],ARRAY['An editor schedules additional dialogue recording to add an off-screen radio voice.','A director records new expository lines in post to clarify a re-cut scene.','A loop-group session records added crowd lines the location microphones never captured.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cb36fb0a-942b-5f31-bc5b-7eddc0a0255c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Additional dialogue recording'),'[^a-z0-9]','','g'));
