INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ff5b9115-7e9a-5ade-9ad0-2713ceab6a37','Automatic dialogue replacement','A post-production process in which an actor re-records lines of dialogue in a studio, performing in sync to the picture, to replace production dialogue that is unusable because of noise, microphone problems, performance issues, or script changes; historically called looping.','Automatic dialogue replacement, or ADR, means re-recording an actor''s lines in a studio. The actor watches the scene and matches the words to their mouth on screen. It replaces speech that was too noisy or wrong to use.','It rescues scenes whose location dialogue cannot be salvaged, and lets filmmakers change performances or lines after shooting, so the final track is clean and intelligible.','A mixer plays the scene and guide track to the actor over headphones, cues each line with beeps or a wipe, and records repeated takes until sync and performance match.','ADR fundamentals',ARRAY['Additional dialogue recording','ADR spotting','Bande rythmo','Booth tone','Bilabial sync point']::text[],ARRAY['Believing ADR is truly ''automatic''; the name is historical, and it takes skilled, take-by-take performance and editing.','Expecting ADR to perfectly recreate the energy of an on-set take, which often needs many passes.','UNSAFE: Setting headphone or booth monitor levels too loud across a long session, risking hearing damage; keep exposure within recognized limits.']::text[],ARRAY['A lead actor loops dialogue lost to wind and traffic on a location shoot.','A studio changes a line for legal or story reasons by replacing it in ADR.','A director tightens a mumbled performance by re-recording the line in an ADR session.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ff5b9115-7e9a-5ade-9ad0-2713ceab6a37' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Automatic dialogue replacement'),'[^a-z0-9]','','g'));
