INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '28548cdd-cab7-5b5e-bdff-309c55cf4396','Background principal','A background (atmosphere) performer whose contribution rises to principal-performer status, for example by being individually directed to speak a scripted line other than indistinct crowd ''omnies'', which changes their contractual category and can require identifiable, on-mic dialogue in looping or ADR.','Extras normally fill the background without clear lines. If one is directed to say a real scripted line, they become a principal performer. That upgrade changes their pay and may need the line recorded clearly.','The distinction protects performers'' pay and credit, and tells the sound team which background voices are indistinct crowd (walla) versus identifiable lines that must be recorded and synced like principal dialogue.','A loop-group supervisor flags a scripted, identifiable background line as a principal upgrade so it is cast, recorded on-mic, and cleared, not left as general crowd walla.','Casting and performers',ARRAY['Automatic dialogue replacement','Additional dialogue recording','Booth tone','ADR spotting','Cadence match']::text[],ARRAY['Assuming any background actor with a line is still an extra; a scripted, directed line triggers a principal upgrade under SAG-AFTRA rules.','Confusing indistinct crowd ''omnies'' or walla with an identifiable principal line.','Recording an upgraded background line as vague walla, losing the clarity the scene needs.']::text[],ARRAY['A background waiter is directed to say a scripted line, upgrading them to principal.','A loop-group session separates identifiable background principal lines from general walla.','A production logs a background upgrade so the performer is paid and credited correctly.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='28548cdd-cab7-5b5e-bdff-309c55cf4396' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Background principal'),'[^a-z0-9]','','g'));
