INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'aec6277e-69e6-539b-b647-96d86a2bb2d2','Bande rythmo','A dubbing and ADR cueing technique, originating in France, in which the translated or replacement dialogue is written on a horizontal band that scrolls across the bottom of the picture in exact synchronization, so the performer reads the text as it passes a fixed vertical line and achieves precise lip-sync; also called the rythmo band.','Bande rythmo is French for rhythm band. The lines to be spoken scroll across the bottom of the screen in time with the film. The actor reads each word as it passes a marker, so the voice stays in sync.','It lets performers deliver lines in sync on the first read without memorizing timing, greatly speeding dubbing and ADR while keeping lip-sync tight.','Modern software displays a digital rythmo band under the picture in the booth; the actor follows the scrolling text while recording, instead of relying only on beeps.','ADR cueing',ARRAY['Automatic dialogue replacement','ADR wipe','Bilabial sync point','Cadence match','ADR target']::text[],ARRAY['Thinking the rythmo band is only for foreign-language dubbing; it is also used for same-language ADR.','Writing the band out of sync with lip movements, which defeats its whole purpose.','Assuming the scrolling text removes the need to match the actor''s original cadence and stresses.']::text[],ARRAY['A dubbing studio uses a digital rythmo band so an actor reads translated lines in lip-sync.','An ADR stage displays a scrolling band to help a performer hit fast dialogue.','A supervisor prepares a rythmo band from the script to speed a heavy looping day.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='aec6277e-69e6-539b-b647-96d86a2bb2d2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bande rythmo'),'[^a-z0-9]','','g'));
