SELECT 'aec6277e-69e6-539b-b647-96d86a2bb2d2','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='aec6277e-69e6-539b-b647-96d86a2bb2d2' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2eb83bd6-aec6-573c-86ab-27e35b6fe0c2','Bilabial sync point','A sync landmark in ADR and dubbing formed by a bilabial consonant (/p/, /b/, or /m/), which requires a full closure of both lips that is clearly visible on screen, giving the editor a precise, unambiguous frame at which to align replaced dialogue to the picture.','The sounds p, b, and m are made by pressing both lips together. On screen that lip closure is easy to see. Editors use these clear moments as exact points to line up new dialogue with the picture.','Because lip closures are the most visible mouth shapes, matching them anchors the replaced line''s timing where the audience would most notice any error, making sync feel correct.','A dialogue editor nudges an ADR take so the actor''s spoken ''b'' or ''p'' lands on the exact frame where the lips close on screen, then checks that the surrounding words follow.','ADR sync',ARRAY['ADR target','Cadence match','ADR squeeze','ADR stretch','Automatic dialogue replacement','Bande rythmo']::text[],ARRAY['Aligning to vowels or open sounds, whose mouth shapes are vague, instead of the crisp bilabial closures.','Getting the words right but letting a visible ''p'' or ''b'' land a frame off, which reads as out of sync.','Assuming sync is fine after matching one bilabial without checking the rest of the line.']::text[],ARRAY['An editor locks an ADR line by matching the actor''s ''m'' to the on-screen lip closure.','A dubbing mixer chooses word timing so bilabials fall on the character''s mouth-closed frames.','A supervisor rejects a take whose ''p'' sounds land off the visible lip closures.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2eb83bd6-aec6-573c-86ab-27e35b6fe0c2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bilabial sync point'),'[^a-z0-9]','','g'));
