INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7d571ab5-fc89-5186-9db4-b95ddf5494b6','Booth tone','A recording of the ambient noise floor of the ADR booth captured with the same microphone and signal chain used for the takes, analogous to production room tone, used to fill pauses and gaps so edited ADR has a continuous, matching background rather than pockets of dead silence.','Booth tone is the quiet background sound of the recording room, taped with the actor''s microphone. Editors lay it under gaps between lines. It stops edits from dropping into unnatural, total silence.','It gives the editor matching ''silence'' to bridge cuts and fill spaces, so replaced dialogue does not jump between the booth''s background and the scene''s, keeping the track seamless.','At the end of a cue the engineer records several seconds of booth tone; the dialogue editor uses it to smooth edits and match handles between ADR clips.','ADR recording',ARRAY['ADR tonal match','Booth-mode coloration','Automatic dialogue replacement','Additional dialogue recording','ADR spotting']::text[],ARRAY['Forgetting to record booth tone, leaving the editor with no matching fill for gaps.','Using booth tone to match a location scene; it matches the booth, not the set, so it rarely blends outdoors.','UNSAFE: Cranking booth headphone or monitor levels during quiet tone recording to hear detail, risking hearing damage; keep levels within recognized limits.']::text[],ARRAY['An engineer records ten seconds of booth tone after a cue for the editor''s use.','A dialogue editor fills a pause between ADR lines with booth tone to avoid dead air.','An editor matches the handles between two ADR clips using booth tone.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7d571ab5-fc89-5186-9db4-b95ddf5494b6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Booth tone'),'[^a-z0-9]','','g'));
