INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1bc8ace2-d9fc-51f0-af39-a5ddc435742b','Booth-mode coloration','Timbral coloration imparted to an ADR recording by the resonant room modes (standing waves) of a small recording booth, whose low-frequency modal peaks and nulls give the voice a boxy, uneven tonal signature unlike the acoustic of the original production location.','A small booth has resonant notes, called room modes, that make some frequencies louder and others weaker. This gives a boxy tone to the voice. That coloring can make studio lines hard to match to location sound.','Naming this effect reminds the team that even a treated booth colors the sound, so booths are acoustically damped and ADR is tonally matched to avoid an obvious studio ''box'' on replaced dialogue.','An engineer treats and damps the booth to reduce modal resonances, and a mixer later applies EQ or spectral matching to counter any remaining boxy coloration in the takes.','Booth acoustics',ARRAY['ADR tonal match','Booth tone','Automatic dialogue replacement','Bilabial sync point','ADR target']::text[],ARRAY['Assuming a small booth is acoustically neutral, then wondering why ADR sounds boxy against location sound.','Trying to fully fix modal coloration with EQ alone instead of treating the booth acoustically.','Recording too close or too far, so the boxy modes and proximity effect worsen the mismatch.']::text[],ARRAY['A mixer notices a boxy resonance on ADR caused by the booth''s room modes.','A studio adds bass trapping to a small ADR booth to reduce modal coloration.','An editor struggles to match colored booth takes to an open exterior scene.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1bc8ace2-d9fc-51f0-af39-a5ddc435742b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Booth-mode coloration'),'[^a-z0-9]','','g'));
