INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fb00a995-1921-5370-b500-ee895dbb197e','Cadence match','The matching of the rhythm, pacing, stress, and pauses (the cadence) of an ADR performance to the actor''s original production delivery, so the replaced line not only lands on sync points but flows with the same natural speech rhythm.','Cadence is the rhythm and pace of how someone speaks. A cadence match makes the new take flow with the same beats and pauses as the first. Without it, a line can hit sync yet still feel wrong.','It preserves the believability of the performance, because audiences notice unnatural rhythm even when word timing is technically in sync, so matching cadence keeps the delivery convincing.','A director coaches the actor to breathe and stress words like the original, and the editor fine-tunes timing so the take''s rhythm matches the guide, not just the lip closures.','ADR performance',ARRAY['ADR target','Bilabial sync point','Automatic dialogue replacement','ADR squeeze','ADR stretch']::text[],ARRAY['Hitting the sync points but ignoring rhythm, so the line feels stiff or rushed.','Copying the words without the original pauses and breaths, breaking the natural flow.','Fixing cadence only by time-stretching instead of guiding a better performance in the booth.']::text[],ARRAY['A director has the actor match the pauses and stresses of the original take while looping.','An editor tunes ADR timing so the delivery''s rhythm matches the guide, not just sync points.','A supervisor rejects a take that is in sync but whose cadence feels unnatural.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fb00a995-1921-5370-b500-ee895dbb197e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cadence match'),'[^a-z0-9]','','g'));
