INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '98b9292b-2996-545f-8575-12f927524474','Call-and-response walla','A loop-group (walla) technique in which a caller or lead voice delivers a line and the rest of the group answers in unison or overlapping response, building layered crowd dialogue such as chants, cheers, drill responses, or congregational replies. It gives group ADR a structured, rhythmic pattern rather than an undifferentiated murmur.','One voice calls out a line, and the group shouts back an answer. Loop actors use this to build crowd sounds like chants or cheers.','It lets a loop group create organized, believable crowd exchanges, such as protests, sports chants, or roll calls, that a single layer of random murmur cannot convey.','In a group ADR session the recordist captures the caller and the response on separate passes or mics, then the editor layers them under the scene to match the on-screen crowd.','Walla / group ADR',ARRAY['General walla','Group ADR','Crossing voices','Energy match','Cue streamer']::text[],ARRAY['Having the whole group speak identical words in perfect unison, which sounds unnatural and turns to mush.','Recording the call and the response at the same level so neither reads clearly in the mix.']::text[],ARRAY['Recording a protest crowd chanting a slogan led by one demonstrator.','Building a military drill scene where a sergeant calls and recruits answer.','Creating auction or courtroom crowd responses under principal dialogue.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='98b9292b-2996-545f-8575-12f927524474' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Call-and-response walla'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '98b9292b-2996-545f-8575-12f927524474','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='98b9292b-2996-545f-8575-12f927524474' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e4ef9e1d-1ef3-538e-81b1-3d7f1474f4bc','Crossing voices','In dialogue and loop-group work, the condition where two or more voices overlap on the same moment so their words collide, reducing intelligibility or pulling attention to background lines. Editors and loop-group directors stagger lines to keep walla or added dialogue from crossing the principal dialogue.','This is when two people talk at the exact same time and their words clash. It makes speech hard to understand, so editors keep the voices from landing on top of each other.','Naming the fault helps editors keep dialogue clear: background or added lines must not step on the main actors'' words.','When laying in group ADR, the editor slides overlapping lines earlier or later so no two intelligible phrases cross the on-camera principal line.','Dialogue editing',ARRAY['General walla','Group ADR','Call-and-response walla','Energy match','Drop-in']::text[],ARRAY['Piling several intelligible walla lines on the same beat so the words turn to mush.','Letting a loud background call cross a principal''s key line and pull focus.']::text[],ARRAY['Editing a dinner-party scene so guest chatter never overlaps the leads'' lines.','Directing a loop group to stagger callouts so responses do not collide.','Fixing a production track where two boom-recorded actors talk over each other.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e4ef9e1d-1ef3-538e-81b1-3d7f1474f4bc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Crossing voices'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e4ef9e1d-1ef3-538e-81b1-3d7f1474f4bc','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e4ef9e1d-1ef3-538e-81b1-3d7f1474f4bc' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f2834b1e-9dff-5e7b-9358-c4ea426b2b13','Cue streamer','A moving visual cue used in ADR and scoring: a vertical line (streamer) sweeps across the picture and reaches a fixed edge exactly at the sync point, giving the performer a timed visual countdown to begin. It is commonly paired with a punch (a single-frame flash) and/or audible beeps.','A line slides across the screen and hits the edge right when the actor should start talking. It works like a visual countdown so the performer comes in on time.','It gives ADR actors and conductors a precise, silent ''get ready, now'' signal locked to timecode, so replacement lines land in sync without relying on memory.','The ADR recordist places streamers in software such as Video Sync or ADR Master at each cue''s start; the actor watches the streamer arrive at the edge and begins on cue.','ADR cueing',ARRAY['Drop-in','Head pickup','Hard-sync line','Guide VO','Group ADR']::text[],ARRAY['Confusing the streamer (a moving line) with the punch (a single flash) or the three beeps.','Starting to speak when the streamer first appears instead of when it reaches the edge.']::text[],ARRAY['Cueing an actor to replace an off-mic line in an ADR booth.','Guiding a conductor to a downbeat when scoring to picture.','Setting visual cues for a loop group entering together on a crowd reaction.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f2834b1e-9dff-5e7b-9358-c4ea426b2b13' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue streamer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f2834b1e-9dff-5e7b-9358-c4ea426b2b13','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f2834b1e-9dff-5e7b-9358-c4ea426b2b13' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5cc83c61-8ef2-52eb-8ab9-9060eed5b6f6','Drop-in','A recording technique in which the operator punches the transport into record at a precise point over existing material, replaces a short section such as a word, phrase, or breath, and drops out again, leaving the surrounding audio untouched. In ADR it repairs part of a line rather than re-recording the whole take.','The recordist hits record for just a moment to swap out one word or phrase. Everything around it stays the same, like patching a small hole in a take.','It lets an editor repair a single flawed spot without losing a good performance around it, saving time and keeping tone consistent.','Using Pro Tools punch or QuickPunch recording, the recordist drops in over a misspoken word so the actor re-reads only that word in sync.','ADR recording',ARRAY['Head pickup','Cue streamer','Hard-sync line','Energy match','Final-approved read']::text[],ARRAY['Setting the punch points too tightly so the new word clips the words on either side.','Dropping in a replacement whose level or tone does not match the surrounding line.']::text[],ARRAY['Replacing one profane word for a broadcast TV version of a film.','Fixing a single mispronounced word inside an otherwise perfect ADR take.','Punching in a corrected number or name in a narration read.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5cc83c61-8ef2-52eb-8ab9-9060eed5b6f6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Drop-in'),'[^a-z0-9]','','g'));
