INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '98524354-c956-57cb-91c2-ca8b6ea47fd0','Energy match','The practice of matching the vocal energy of a replacement (ADR) performance, including effort, projection, breath, and physical exertion, to the original production take and the on-screen action, so the new line feels like it belongs in the scene. Mismatched energy is a common reason ADR sounds pasted on.','Making the new recorded line sound as strong or as tired as the original. If the actor was running on screen, the replacement voice must sound out of breath too.','It keeps replacement dialogue believable by matching the performance intensity the audience sees, not just the words and lip-sync.','During ADR the supervisor coaches the actor to project or breathe as they did on set, and the editor selects the take whose energy fits the picture.','ADR editing',ARRAY['Final-approved read','Hard-sync line','Drop-in','Crossing voices','Guide VO']::text[],ARRAY['Recording a calm, booth-comfortable read for a line the character shouted while fighting.','Matching lip-sync perfectly but ignoring breath and effort, so the line sounds detached.']::text[],ARRAY['Replacing a line an actor delivered while sprinting or fighting.','Matching a whispered on-set line without losing intimacy in the booth.','Looping an emotional, tearful scene where breath and strain carry the moment.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='98524354-c956-57cb-91c2-ca8b6ea47fd0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Energy match'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '98524354-c956-57cb-91c2-ca8b6ea47fd0','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='98524354-c956-57cb-91c2-ca8b6ea47fd0' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f9b1974f-6d76-546b-b801-18d4074d0f85','Final-approved read','The specific ADR or voice take that the director, showrunner, or supervising sound editor has signed off as the one to use in the final mix. Once designated, it becomes the reference the dialogue editor conforms and syncs, and other takes are set aside.','The one recorded take the director officially picks to keep. Everyone then works from that chosen version and drops the rest.','It removes doubt about which take is the take, so editors and mixers all build on the same approved performance.','After an ADR session the editor labels the circled, approved take as the final-approved read and syncs only that one into the timeline.','ADR workflow',ARRAY['Energy match','Drop-in','Head pickup','Guide VO','Hard-sync line']::text[],ARRAY['Editing to an early take before the director''s final approval, then having to redo the work.','Failing to clearly label the approved take, so a wrong version reaches the mix.']::text[],ARRAY['Locking the director-approved ADR take before a final mix session.','Delivering the approved narration read to the mixer for a documentary.','Conforming only the signed-off take when the picture is re-cut.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f9b1974f-6d76-546b-b801-18d4074d0f85' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Final-approved read'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f9b1974f-6d76-546b-b801-18d4074d0f85','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f9b1974f-6d76-546b-b801-18d4074d0f85' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b6f832cb-6f11-58e7-b3c4-30fe09df9cc0','General walla','Non-specific background crowd murmur made by a loop group or from a library, containing no clearly intelligible words: an undifferentiated bed of human voices that establishes crowd presence behind a scene. It contrasts with specific, scripted callouts or reactions.','The blurry murmur of a crowd where you can''t make out any single word. It fills a scene with the feeling of people around, like the hum of a busy restaurant.','It provides a believable human background so a populated location does not feel empty, without competing with the principal dialogue.','The editor lays general walla under a cafe or street scene, keeping it low and word-free so it supports but never distracts from the leads.','Walla / group ADR',ARRAY['Group ADR','Call-and-response walla','Crossing voices','Cue streamer','Energy match']::text[],ARRAY['Letting recognizable words surface in the murmur, which pulls the audience''s ear.','Reusing the same short walla loop so a repeating phrase or laugh becomes obvious.']::text[],ARRAY['Filling a busy restaurant background behind a two-person conversation.','Adding street or market presence to an exterior dialogue scene.','Bedding a party scene with crowd hum under the leads.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b6f832cb-6f11-58e7-b3c4-30fe09df9cc0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('General walla'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b6f832cb-6f11-58e7-b3c4-30fe09df9cc0','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b6f832cb-6f11-58e7-b3c4-30fe09df9cc0' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2c1702d6-b34d-53cf-8713-4c1ba087a9bc','Group ADR','Automated dialogue replacement performed by a group of voice actors (a loop group) recorded together or in layered passes to create crowd dialogue, walla, reactions, and specific background lines for a scene. It supplies the human background voices that were not recorded cleanly on set.','A team of voice actors records crowd sounds and background chatter for a scene. They fill in the voices of people you see but didn''t hear clearly on set.','It builds realistic, controllable crowd and background dialogue in post, replacing or adding to voices that production sound could not capture cleanly.','A loop-group director scripts callouts and reactions, then records several actors in passes so the editor can layer a full crowd from a handful of people.','Walla / group ADR',ARRAY['General walla','Call-and-response walla','Crossing voices','Cue streamer','Energy match']::text[],ARRAY['Recording too few passes so the crowd sounds thin and obviously small.','Letting group members clash on the same words, creating crossing voices that muddy the bed.']::text[],ARRAY['Voicing a stadium crowd''s cheers and specific callouts.','Populating a hospital or precinct background with staff chatter.','Adding protest chants and reactions around a principal actor.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2c1702d6-b34d-53cf-8713-4c1ba087a9bc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Group ADR'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2c1702d6-b34d-53cf-8713-4c1ba087a9bc','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2c1702d6-b34d-53cf-8713-4c1ba087a9bc' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7140f9ff-eb7e-5eff-b61e-6afd5f2feac5','Guide VO','A temporary or reference voice-over recorded early to establish pacing, timing, and intent for a scene or narration, later replaced by the final performance. It gives picture and sound editors something to cut to before the approved voice is recorded.','A rough, stand-in voice recording used to plan timing before the real one is made. It''s like a pencil sketch that the final voice will later trace over.','It lets editors build and time a scene to spoken words before the final voice-over exists, keeping the edit moving.','An editor cuts a trailer or documentary to a guide VO, then swaps in the final-approved read once the talent records it.','Guide tracks',ARRAY['Final-approved read','Energy match','Drop-in','Cue streamer','Head pickup']::text[],ARRAY['Cutting so tightly to the guide VO that the final read no longer fits the timing.','Letting a guide VO leak into the final mix because it was never replaced.']::text[],ARRAY['Timing a documentary edit to a temporary narration.','Cutting a trailer to a scratch announcer before the star records.','Pacing an animation scene to a guide voice before final dialogue.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7140f9ff-eb7e-5eff-b61e-6afd5f2feac5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Guide VO'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7140f9ff-eb7e-5eff-b61e-6afd5f2feac5','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7140f9ff-eb7e-5eff-b61e-6afd5f2feac5' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fdfc2074-377a-5a5d-8956-5b2c8ae22459','Hard-sync line','A replacement line that must be in tight, frame-accurate lip-sync because the character''s mouth is clearly visible on camera, demanding precise alignment of the ADR to the picture. It contrasts with off-camera or loosely framed lines that tolerate looser sync.','A line where you can clearly see the actor''s mouth, so the new recording must match the lips exactly. There''s little room for error.','Flagging a line as hard-sync tells the editor it needs careful, precise fitting, since any drift will be obvious to the viewer.','The editor spends extra time nudging and warping a hard-sync line to the frame, while a back-of-head line can be placed more quickly.','ADR sync',ARRAY['Head-sync / tail-sync tradeoff','Head pickup','Drop-in','Cue streamer','Energy match']::text[],ARRAY['Treating an on-camera close-up line as loosely as an off-camera one, leaving visible sync drift.','Fixing the head of the line but letting the mouth drift out of sync by the end.']::text[],ARRAY['Replacing a close-up line where the actor''s lips fill the frame.','Fitting ADR for a face-forward monologue.','Syncing a hero line in a scene shot in tight close-up.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fdfc2074-377a-5a5d-8956-5b2c8ae22459' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hard-sync line'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fdfc2074-377a-5a5d-8956-5b2c8ae22459','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fdfc2074-377a-5a5d-8956-5b2c8ae22459' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6d0f4ad7-fee1-56b6-9562-95d39d03d1db','Head pickup','A pickup (partial re-record) that captures the beginning, or head, of a line or phrase, used to fix or complete the opening portion while keeping the rest of an approved take. ''Head'' refers to the start of the clip, as opposed to its tail (the end).','Re-recording just the start of a line to fix its opening. The rest of the good take stays, and only the beginning is swapped in.','It repairs a flawed line opening, such as a missed word, bad breath, or off entrance, without discarding a strong performance in the rest of the line.','The recordist drops in only the first few words of a line as a head pickup, then the editor joins it to the kept tail.','ADR recording',ARRAY['Drop-in','Head-sync / tail-sync tradeoff','Hard-sync line','Final-approved read','Cue streamer']::text[],ARRAY['Recording the head pickup at a different mic distance or energy, so the join is audible.','Cutting the join in the middle of a sustained sound instead of at a clean breath or consonant.']::text[],ARRAY['Replacing a clipped first word at the start of a line.','Fixing a noisy breath before an actor''s opening line.','Re-recording a botched entrance while keeping the rest of the take.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6d0f4ad7-fee1-56b6-9562-95d39d03d1db' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head pickup'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6d0f4ad7-fee1-56b6-9562-95d39d03d1db','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6d0f4ad7-fee1-56b6-9562-95d39d03d1db' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '352239dc-6ced-520b-8fad-6a314cd7cbce','Head-sync / tail-sync tradeoff','The choice a dialogue editor faces when a replacement line''s length differs from the original: aligning the start (head) precisely leaves the end (tail) out of sync, and vice versa, so one end is locked at the expense of the other unless the audio is time-stretched. Editors lock the end where sync matters most on screen.','A new line may be a bit longer or shorter than the old one. You can match its start or its end. You cannot match both at once.','It guides where to place a mismatched take so the most visible sync point stays tight, hiding the drift where the audience is least likely to notice.','For a line that ends on a close-up, the editor tail-syncs it and lets the head drift; time-warp tools can then tighten the rest.','ADR sync',ARRAY['Hard-sync line','Head pickup','Drop-in','Cue streamer','Energy match']::text[],ARRAY['Locking the head out of habit when the on-camera emphasis is on the end of the line.','Forgetting that stretching to fix both ends can add audible artifacts if overdone.']::text[],ARRAY['Fitting an ADR line that runs slightly longer than the original.','Deciding which end to lock when a foreign-language dub differs in length.','Placing a line that starts off-camera but ends on a visible close-up.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='352239dc-6ced-520b-8fad-6a314cd7cbce' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head-sync / tail-sync tradeoff'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '352239dc-6ced-520b-8fad-6a314cd7cbce','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='352239dc-6ced-520b-8fad-6a314cd7cbce' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd75633df-a1b4-5ed2-8e0d-d956f707e53c','Headphone-shell leakage','Unwanted sound escaping from the shell of an ADR performer''s headphones and being captured by the recording microphone, contaminating the clean replacement recording with the guide track, beeps, or click. It is a form of spill (bleed) specific to the actor''s monitoring headphones.','Sound from the actor''s headphones leaks out and gets picked up by the mic. The recording then has a faint echo of the guide track under the new voice.','Recognizing it lets the recordist keep ADR clean, since captured guide-track bleed is hard to remove and can ruin an otherwise good take.','The recordist uses single-ear or closed-back headphones, lowers the cue level, or repositions the mic so guide audio does not leak into the ADR take.','ADR recording',ARRAY['Guide VO','Cue streamer','Drop-in','Head pickup','Energy match']::text[],ARRAY['UNSAFE: Cranking the headphone monitor level to hear cues over a noisy booth, risking hearing damage from prolonged high sound levels; keep exposure within OSHA 29 CFR 1910.95 and NIOSH recommended limits.','Raising the guide level to help the actor, which only increases the leakage into the mic.','Using open-back headphones for on-mic ADR, which leak far more than closed-back headphones.']::text[],ARRAY['A quiet, intimate ADR line where faint beeps bleed into the mic.','Close-mic ADR with the actor wearing both ears of open headphones.','Trying to salvage a take where the click track is audible under the dialogue.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d75633df-a1b4-5ed2-8e0d-d956f707e53c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Headphone-shell leakage'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd75633df-a1b4-5ed2-8e0d-d956f707e53c','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d75633df-a1b4-5ed2-8e0d-d956f707e53c' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '41a8fb7e-f88b-54fd-ac69-da6c0e7ff687','Hydration shift','A change in an actor''s vocal timbre, resonance, and articulation caused by a difference in oral and vocal-fold hydration between the original production recording and a later ADR session, which makes seamless matching of replacement lines harder.','A person''s voice sounds a bit different when their mouth is dry versus moist. If an actor''s mouth is drier at the redo session, the new line will not match the old one.','Naming this factor reminds the ADR team to manage the performer''s vocal condition, through water, warm-up, and session timing, so the re-recorded voice matches the on-set take in tone and clarity.','A dialogue mixer notices a replacement line sounds thinner or drier than the production track and has the actor sip water and warm up before recording another pass.','Performance Matching',ARRAY['Inflection match','Mic-position recall','Looping','Off-camera ADR']::text[],ARRAY['Assuming a voice will sound identical months after the shoot, ignoring day-to-day changes in vocal condition.','Recording ADR without letting the actor warm up or hydrate, then blaming the mic or room for the mismatch.','Trying to fix a hydration-caused tonal mismatch entirely with EQ instead of re-recording a better-matched take.']::text[],ARRAY['An actor returns months after principal photography and their voice reads drier, forcing extra takes to match the original scene.','A late-night ADR session where a tired, dehydrated performer''s replacement lines sound dull against the brighter production track.','Matching a replacement line to an emotional on-set take whose original delivery had a wetter, more resonant vocal quality.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='41a8fb7e-f88b-54fd-ac69-da6c0e7ff687' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hydration shift'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '41a8fb7e-f88b-54fd-ac69-da6c0e7ff687','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='41a8fb7e-f88b-54fd-ac69-da6c0e7ff687' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bcf21c33-6cf5-5881-8b0d-dc4738fc0f3a','Incidental dialogue','Minor, non-principal spoken lines, such as background remarks, reactions, and off-hand comments, that support a scene''s realism without carrying the main narrative, and are often performed by a loop group or supporting cast rather than lead actors.','These are the small background lines in a scene, like a waiter taking an order or people chatting nearby. They fill out the world but are not the main conversation.','It adds a believable layer of human presence and ambience to crowd and background action, filling the space around principal dialogue so scenes feel populated and alive.','A supervising sound editor spots scenes needing incidental dialogue and hires a loop group to record shop chatter, radio calls, or crowd reactions to lay under the main track.','Dialogue Type',ARRAY['Loop group','Looping','Off-camera ADR']::text[],ARRAY['Confusing incidental dialogue with principal dialogue and giving it the same prominence in the mix.','Recording incidental lines so intelligible that they pull focus from the main conversation.','Forgetting that background lines still need appropriate perspective and room tone to sit believably in the scene.']::text[],ARRAY['A busy restaurant scene where loop-group performers murmur orders and small talk under the leads'' conversation.','A newsroom or trading-floor set that needs constant low-level background chatter to feel active.','A hospital corridor where paging, staff exchanges, and passing remarks are added in post to fill the space.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bcf21c33-6cf5-5881-8b0d-dc4738fc0f3a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Incidental dialogue'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bcf21c33-6cf5-5881-8b0d-dc4738fc0f3a','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bcf21c33-6cf5-5881-8b0d-dc4738fc0f3a' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f26b6a1f-c375-528c-a57e-3df894c23f3c','Inflection match','The practice of reproducing the pitch contour, stress, and intonation of the original guide (production) performance when recording an ADR line, so the replacement delivery carries the same emotional and rhythmic shape.','This means copying the ups and downs of how a line was first said. The new take should rise, fall, and stress words the same way, so it feels like the same performance.','It preserves the actor''s original intent and emotion in the replaced line, so the audience does not sense that the delivery was re-recorded.','During an ADR pass the mixer plays the guide track in the actor''s headphones and coaches them to match the original rise, fall, and emphasis of each phrase.','Performance Matching',ARRAY['Lead-in read','Hydration shift','Mic-position recall','Looping','Off-camera ADR']::text[],ARRAY['Matching only the words and timing while ignoring the pitch and stress of the original line.','Over-acting the replacement so the inflection is bigger than the on-camera performance.','Letting the actor read the line cold without hearing the guide track first.']::text[],ARRAY['Replacing a noisy line where the actor must recreate the exact questioning lilt of the original take.','Matching a shouted, rising delivery so the ADR line keeps the same emotional build.','Coaching a performer whose fresh reading is flat compared with the energetic on-set version.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f26b6a1f-c375-528c-a57e-3df894c23f3c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Inflection match'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f26b6a1f-c375-528c-a57e-3df894c23f3c','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f26b6a1f-c375-528c-a57e-3df894c23f3c' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a22ff0fe-b4a4-51cf-987c-fbcdd9c8dd3d','Insert read','A short ADR recording of only a word, phrase, or fragment intended to be dropped into an existing line or scene, rather than replacing the whole line, used to fix a single flubbed word, add a missing beat, or patch an obscured moment.','This is recording just a small piece of a line, not the whole thing. You might redo one word and slot it into the original take to fix a problem.','It lets editors repair or add a small portion of dialogue without re-recording an entire line, saving time and keeping as much of the original performance as possible.','An editor records an insert read of a single clean word to cover a cough or crew noise, then edits it into the middle of the otherwise-good production line.','Recording Technique',ARRAY['Mid-sentence pickup','Lead-in read','Internal ADR sync','Looping','Patch read (near-synonym; often used interchangeably for re-recording a small fragment)']::text[],ARRAY['Recording an insert with a different tone or level so it stands out from the surrounding production line.','Ignoring room tone and perspective, so the patched word sounds like it came from another space.','Grabbing an insert without a lead-in, making the rhythm of the edit feel abrupt.']::text[],ARRAY['Fixing a single mispronounced word in an otherwise perfect take.','Patching one word ruined by an off-camera bump or door slam.','Adding a short reaction word an actor did not say on set but the scene now needs.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a22ff0fe-b4a4-51cf-987c-fbcdd9c8dd3d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Insert read'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a22ff0fe-b4a4-51cf-987c-fbcdd9c8dd3d','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a22ff0fe-b4a4-51cf-987c-fbcdd9c8dd3d' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '83df7f88-ccbe-5e69-9c70-08ec4c3a41cd','Internal ADR sync','Sync achieved within the body of a line, aligning individual syllables, consonant hits, and mouth movements through the middle of a phrase, rather than only matching its start and end points.','This is lining up the middle of a spoken line, not just its start and end. Each part of the new line must match the mouth as it moves.','It keeps the replacement line locked to picture across the whole phrase, preventing drift where the middle words slip out of step with the lips even when the ends match.','A dialogue editor nudges and time-warps syllables inside a line so a plosive lands exactly on the lip closure, tightening sync beyond just the first and last words.','Sync Technique',ARRAY['Lip closure','Labial anchor','Mid-sentence pickup','Inflection match','Looping']::text[],ARRAY['Matching only the first and last words and assuming the middle will line up on its own.','Stretching a whole line uniformly instead of adjusting the individual syllables that drift.','Ignoring visible consonant hits inside the phrase as sync references.']::text[],ARRAY['A long on-camera line where the ends match but a middle word visibly drifts off the lips.','Using time-warp tools to align the interior syllables of an ADR take to the picture.','Fixing a replacement line where a mid-phrase plosive falls before or after the actor''s lips close.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='83df7f88-ccbe-5e69-9c70-08ec4c3a41cd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Internal ADR sync'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '83df7f88-ccbe-5e69-9c70-08ec4c3a41cd','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='83df7f88-ccbe-5e69-9c70-08ec4c3a41cd' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3fc2f537-eaf1-5997-8c82-d1605a366d50','Labial anchor','A visible bilabial articulation, the lip closure of a p, b, or m, used as a fixed reference point for aligning ADR or edited dialogue to picture, because the closing of the lips is a clear, unambiguous sync landmark on screen.','The sounds ''p'', ''b'', and ''m'' make the lips press together, which is easy to see on screen. Editors use that clear lip-close moment as a target to line up the new voice.','It gives the editor a precise, easily seen frame to match against, making sync work faster and more accurate than relying on vowels or open-mouth sounds that are visually vague.','When lining up a replacement line, the editor finds the frame where the actor''s lips meet on a p or b and snaps the matching consonant in the new take to that frame.','Sync Technique',ARRAY['Lip closure','Internal ADR sync','Inflection match','Looping','Off-camera ADR']::text[],ARRAY['Trying to anchor sync on vowels or open-mouth sounds, which give no sharp visual cue.','Assuming every p, b, or m is visible, when some are hidden by angle, motion, or framing.','Locking to a labial hit while letting the rest of the phrase drift out of sync.']::text[],ARRAY['Aligning an ADR line by matching the new b in ''baby'' to the frame where the lips close on screen.','Choosing a sync reference in a close-up where lip movements are highly visible.','Editing a dubbed foreign-language line to hit the same lip-closure frames as the original.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3fc2f537-eaf1-5997-8c82-d1605a366d50' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Labial anchor'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3fc2f537-eaf1-5997-8c82-d1605a366d50','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3fc2f537-eaf1-5997-8c82-d1605a366d50' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'afc71edc-0fb3-540b-8787-9873d1ac54a1','Lead-in read','An ADR technique in which the actor speaks one or more words before the line that actually needs replacing, giving the performance natural momentum and rhythm so the target words are delivered in the same flow as the original.','The actor starts a few words before the part that needs fixing. That run-up helps them find the natural rhythm, so the important words come out sounding relaxed and real.','It helps the performer avoid a cold, stilted delivery on the replacement words by carrying the momentum and pacing of the surrounding speech into the target line.','The ADR mixer asks the actor to begin the sentence a little earlier than the cut-in point so the replaced portion arrives with believable energy and timing.','Recording Technique',ARRAY['Insert read','Mid-sentence pickup','Inflection match','Internal ADR sync','Looping']::text[],ARRAY['Starting cold on the exact replacement word, producing a flat, disconnected reading.','Recording a lead-in but forgetting to keep the target words in sync with the picture.','Making the lead-in so long the actor drifts from the original pacing.']::text[],ARRAY['Replacing the second half of a sentence by having the actor read the whole sentence for flow.','Helping a performer nail an emotional word by letting them build into it from earlier text.','Recording a fast line where the run-up is needed to hit the natural tempo.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='afc71edc-0fb3-540b-8787-9873d1ac54a1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lead-in read'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'afc71edc-0fb3-540b-8787-9873d1ac54a1','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='afc71edc-0fb3-540b-8787-9873d1ac54a1' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'af0f3d67-25fa-50af-8292-e635c5aeace7','Lip closure','The moment when a speaker''s lips come fully together, as in the bilabial consonants p, b, and m; on screen it is a clear, discrete visual event widely used as a primary sync reference in dialogue editing and ADR.','This is the instant the lips press shut, like at the start of ''pat'', ''bat'', or ''mat''. Because it is easy to see, editors use it to line up voice with picture.','It provides an unmistakable visual marker for matching recorded speech to the actor''s mouth, anchoring sync where open-mouth sounds would be too vague to judge.','A dialogue editor scrubs to the frame where the lips meet and aligns the corresponding consonant of the replacement line to that exact frame.','Sync Technique',ARRAY['Labial anchor','Internal ADR sync','Inflection match','Looping','Off-camera ADR']::text[],ARRAY['Confusing a lip closure with a simple open-mouth vowel when picking a sync point.','Aligning near the closure but a frame or two off, causing a soft, rubbery sync feel.','Ignoring that fast speech can hide a lip closure across only one or two frames.']::text[],ARRAY['Snapping a replacement ''my'' to the frame where the actor''s lips close on m.','Judging whether a dubbed line hits the same lip-closed frames as the picture.','Checking sync on a close-up where every lip movement is clearly visible.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='af0f3d67-25fa-50af-8292-e635c5aeace7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lip closure'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'af0f3d67-25fa-50af-8292-e635c5aeace7','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='af0f3d67-25fa-50af-8292-e635c5aeace7' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9866eb2d-3f4a-50b8-95a6-e4cc65270725','Loop group','A team of specialized performers who record background and incidental voices, such as crowd walla, reactions, and unscripted supporting lines, in post-production to fill out scenes; the group ADR counterpart to principal-cast ADR.','This is a group of actors hired to record background voices after filming. They add crowd noise, chatter, and small reactions so scenes sound full of people.','It supplies the human background texture a scene needs, such as crowds, hallways, and restaurants, that was kept quiet on set so the principal dialogue could be recorded cleanly.','A supervising sound editor books a loop group session and directs performers to improvise era- and location-appropriate chatter to lay under a busy scene.','Background Voice',ARRAY['Incidental dialogue','Looping','Off-camera ADR']::text[],ARRAY['Treating loop-group lines as principal dialogue and mixing them too loud or too clear.','Recording anachronistic or wrong-region chatter that breaks the scene''s believability.','Using too few voices so a crowd sounds thin and repetitive.']::text[],ARRAY['Filling a crowded bar or stadium scene with layered background voices.','Recording hospital, police, or military chatter to sit under a tense scene.','Adding passing pedestrians'' remarks to a busy street exterior.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9866eb2d-3f4a-50b8-95a6-e4cc65270725' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Loop group'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9866eb2d-3f4a-50b8-95a6-e4cc65270725','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9866eb2d-3f4a-50b8-95a6-e4cc65270725' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '343bbafe-8266-5ca3-917b-064c4129c8b8','Looping','The original method of, and a still-common synonym for, ADR: replacing production dialogue by having the actor watch a repeating loop of the scene and re-perform the line in sync; historically the picture and matching recording stock were cut into physical film loops that played back repeatedly.','Looping is the old name for redoing an actor''s lines after filming. The scene plays over and over in a loop while the actor keeps trying until the new voice matches.','It lets filmmakers replace dialogue that was unusable on set, because of noise, performance, or later script changes, by re-recording it cleanly in a studio in sync with the picture.','An actor stands at a mic watching a looped clip and rehearses the line several times, then records takes until one matches the on-screen mouth movements.','ADR Workflow',ARRAY['Loop group','Off-camera ADR','Missing fourth beep','Lip closure','Inflection match']::text[],ARRAY['Assuming looping and ADR name different processes, when they refer to the same task.','Expecting a usable take on the first pass instead of building sync over several loops.','Focusing on words while neglecting the lip sync the loop is there to help match.']::text[],ARRAY['Replacing dialogue ruined by wind or traffic on an exterior shoot.','Re-recording a line changed in the edit after shooting wrapped.','Cleaning up a mumbled or off-mic delivery from principal photography.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='343bbafe-8266-5ca3-917b-064c4129c8b8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Looping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '343bbafe-8266-5ca3-917b-064c4129c8b8','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='343bbafe-8266-5ca3-917b-064c4129c8b8' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '91eb86d8-5ee0-5150-ba31-c330ebfec024','Mic-position recall','The practice of reproducing the microphone type, distance, height, and angle used or implied in the original production recording when capturing ADR, so the replacement line matches the on-set track''s perspective and tonal character.','This means placing the mic for the redo the same way it sat during filming. Same distance and angle helps the new line sound like it came from the same spot.','It matches the acoustic perspective of the replacement line to the production track, how close, bright, or roomy it sounds, so edits between them are seamless.','Before recording, the mixer notes whether the scene was shot on a boom overhead or a lav on the chest and positions the ADR mic to imitate that perspective.','Recording Technique',ARRAY['Hydration shift','Inflection match','Internal ADR sync','Looping','Off-camera ADR']::text[],ARRAY['Recording every ADR line on one close mic setup regardless of the original perspective.','Ignoring mic height and angle, so the replacement sounds too close or too bright.','Failing to match a boom or lav character, making the edit between production and ADR obvious.']::text[],ARRAY['Matching a wide shot recorded on a distant boom by backing the actor off the ADR mic.','Recreating a lav-mic sound for a line originally captured on a body mic.','Keeping a consistent perspective across a scene that mixes production and replacement lines.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='91eb86d8-5ee0-5150-ba31-c330ebfec024' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mic-position recall'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '91eb86d8-5ee0-5150-ba31-c330ebfec024','f3b91616-66f6-414b-a35a-23a86671f275',true
