INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '759d4288-c66e-5972-ab3e-1d98e819e2a8','Mid-sentence pickup','An ADR take that begins partway through a line rather than at its start, used to replace or repair only the latter portion of a sentence while retaining the usable earlier part of the production performance.','This is starting the redo in the middle of a sentence, not the beginning. You keep the good first half from filming and only re-record the part that had a problem.','It preserves as much original performance as possible by replacing only the flawed segment of a line, then editing the pickup cleanly onto the retained production audio.','An editor keeps the clean opening of a line and records a mid-sentence pickup for the words spoiled by a passing siren, joining them at a natural pause.','Recording Technique',ARRAY['Insert read','Lead-in read','Internal ADR sync','Looping']::text[],ARRAY['Cutting into the pickup where tone or level does not match the retained production audio.','Starting the pickup cold so its rhythm and energy differ from the first half.','Editing the join mid-word instead of at a clean breath or consonant.']::text[],ARRAY['Replacing the end of a sentence ruined by an off-camera noise while keeping the clean start.','Fixing a flubbed final phrase without re-recording the whole line.','Patching the second half of a line where the actor turned off-mic.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='759d4288-c66e-5972-ab3e-1d98e819e2a8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mid-sentence pickup'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '759d4288-c66e-5972-ab3e-1d98e819e2a8','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='759d4288-c66e-5972-ab3e-1d98e819e2a8' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0ca0e2bc-117d-55b8-91cf-a36b143e8fc3','Missing fourth beep','A reference to the ADR cue system, in which three evenly spaced beeps (traditionally one second apart) count the actor in and the line begins on the silent fourth beat where a fourth beep would fall; the deliberately absent fourth beep marks the exact start point of the performance.','In a redo session, three beeps count the actor in, one second apart. The actor starts speaking on the silent fourth beat. That is the moment a fourth beep would fall, but none plays.','The steady beeps give the actor a predictable rhythm to lock onto, and starting on the silent fourth beat lets them hit the line''s exact frame without a beep bleeding onto the recording.','The ADR mixer sets three count-in beeps in the actor''s headphones, and the performer speaks precisely on the silent fourth beat to land the line in sync.','ADR Workflow',ARRAY['Looping','Internal ADR sync','Monitor bleed print','Off-camera ADR']::text[],ARRAY['Waiting for a fourth beep that never plays instead of starting on the silent beat.','Setting the three beeps at uneven spacing so the actor cannot lock onto a steady rhythm.','UNSAFE: Running cue beeps or headphone level too loud over a long session, risking hearing fatigue and damage.']::text[],ARRAY['Cueing an actor into a line with three headphone beeps and a silent fourth beat.','Training a new performer who keeps waiting for a nonexistent fourth beep before speaking.','Setting up count-in beeps in the DAW so the line starts exactly on the sync frame.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0ca0e2bc-117d-55b8-91cf-a36b143e8fc3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Missing fourth beep'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0ca0e2bc-117d-55b8-91cf-a36b143e8fc3','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0ca0e2bc-117d-55b8-91cf-a36b143e8fc3' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '740ff519-dd7a-5163-b59d-4652b6276950','Monitor bleed print','An unwanted recording in which sound from the actor''s headphones or a monitor speaker, such as the guide track, cue beeps, or playback, leaks into the ADR microphone and is captured onto the recorded take.','This is when sound leaking from the actor''s headphones gets picked up by the mic and recorded. The old track bleeds onto the new take and can ruin it.','Naming this fault flags a recording problem to catch and prevent, since printed headphone or monitor bleed contaminates the clean replacement line and is hard to remove later.','A mixer hearing faint guide-track or beep bleed on a take lowers the headphone level or switches to closed-back headphones before recording again.','Recording Fault',ARRAY['Missing fourth beep','Mic-position recall','Looping','Off-camera ADR']::text[],ARRAY['Setting the actor''s headphone level so high that the guide track leaks into the mic.','Using open-back headphones for ADR, which spill sound into the recording.','Not checking a take for faint beep or playback bleed before moving on.']::text[],ARRAY['A quiet, intimate line where faint headphone bleed becomes audible on the recording.','An actor who needs a loud guide track, forcing a switch to closed-back headphones.','Discovering count-in beeps printed onto an otherwise clean ADR take.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='740ff519-dd7a-5163-b59d-4652b6276950' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Monitor bleed print'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '740ff519-dd7a-5163-b59d-4652b6276950','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='740ff519-dd7a-5163-b59d-4652b6276950' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '41e2e3b6-fd32-53b2-8d85-828c0c3cd66c','Off-camera ADR','ADR for lines delivered when the character''s mouth is not visible on screen, whether off-frame, turned away, or in a wide shot, so the replacement must match timing, tone, and perspective but not precise lip sync.','This is redoing lines when you cannot see the actor''s mouth on screen. Since the lips are hidden, the new line only has to match the timing and feel, not the lip movements.','It gives editors more freedom to reword, retime, or add off-screen lines because there is no visible mouth to sync to; only the scene''s rhythm and sound perspective must fit.','For a line said while a character faces away, the mixer records ADR focused on matching energy and room perspective rather than exact lip closures.','Dialogue Type',ARRAY['Looping','Loop group','Incidental dialogue','Mic-position recall','Inflection match']::text[],ARRAY['Spending time on precise lip sync for a line whose mouth is never seen.','Assuming off-camera means the perspective and room tone no longer matter.','Adding new off-screen lines that clash with the timing or energy of the on-screen action.']::text[],ARRAY['Replacing a line spoken by a character facing away from the camera.','Adding an off-screen shout or comment that was not recorded on set.','Reworking a phone-call voice heard off-camera to fit a script change.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='41e2e3b6-fd32-53b2-8d85-828c0c3cd66c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Off-camera ADR'),'[^a-z0-9]','','g'));
