INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '450c3b1b-9460-50ba-a042-ea4b8ac663c6','Omni crowd','A group-ADR recording technique in which a loop group performs crowd walla into an omnidirectional microphone, capturing the ensemble''s blended voices and natural room reflections as a single non-directional crowd bed rather than isolating each performer.','A way to record a group of background voices at once. Everyone talks into one microphone that picks up sound from all directions. It captures the whole crowd as one blended murmur.','It efficiently captures a natural, cohesive background murmur so a scene feels populated, without the labor of recording and blending each voice on its own track.','A dialogue mixer sets an omnidirectional mic in a live room, arranges the loop group around it, and records several passes of crowd reactions to layer under the scene.','Group ADR',ARRAY['Walla','Loop group','Period walla','Pass-by chatter','Group ADR','Rhubarb']::text[],ARRAY['Placing the group too close to the mic so individual words become intelligible and pull focus from principal dialogue.','Recording only a single pass, so the crowd bed sounds thin and repeats obviously when layered.','UNSAFE: Monitoring the group at excessive headphone or loudspeaker levels over a long session risks noise-induced hearing loss; keep monitoring at moderate levels.']::text[],ARRAY['Building a restaurant-interior background bed','Filling a stadium or arena crowd','Creating party-scene murmur under principal dialogue']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='450c3b1b-9460-50ba-a042-ea4b8ac663c6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Omni crowd'),'[^a-z0-9]','','g'));
