INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f523b64d-34be-54bd-87fb-390b6fd48561','Open-mouth vowel hold','In ADR lip-sync, sustaining an open-mouth vowel sound for the full time a character''s mouth is visibly held open on picture, so the replacement voice matches the shape and duration of the on-screen articulation.','Sometimes an actor on screen holds their mouth wide open. The new voice must hold the same open vowel. It has to last just as long.','It preserves sync during sustained open-mouth moments such as shouts, cries, or held notes, where a clipped vowel would visibly break the match to picture.','An ADR supervisor watches the actor''s mouth on screen and coaches the performer to stretch the vowel until the on-screen mouth closes.','Lip-sync',ARRAY['Post-sync','Performance drift','Phrase-tail match','Pick-up match','Guide track']::text[],ARRAY['Ending the vowel before the on-screen mouth closes, breaking the visible sync.','Changing the vowel color so the sound no longer matches the visible open-mouth shape.']::text[],ARRAY['Matching a character''s held scream to picture','Replacing a sustained reaction cry','Syncing a held vocal note in a musical scene']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f523b64d-34be-54bd-87fb-390b6fd48561' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Open-mouth vowel hold'),'[^a-z0-9]','','g'));
