INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'acb0aa1b-588b-5a15-94e3-6aad52e3b565','Page-turn mitigation','Any technique used to keep the rustle of turning script or cue pages out of a recording take, such as laying out loose single-sided pages, using a silent tablet, or turning pages only during pauses.','Turning script pages makes a papery rustle the microphone can hear. Page-turn mitigation is the set of tricks that stop that noise from landing on the recording.','It keeps the recorded voice clean so editors do not have to spend time removing page-rustle noise from otherwise good takes.','A mixer prints scripts single-sided and loose, or loads them on a silent tablet, so the performer never rustles paper near the microphone.','Recording technique',ARRAY['Pre-roll chatter','Post-roll contamination','Post-sync','Room tone','Booth']::text[],ARRAY['Stapling pages so the performer must flip them noisily close to the mic.','Turning a page in the middle of a line instead of waiting for a pause.']::text[],ARRAY['Recording a long ADR monologue','Cueing multi-page loop-group scripts','Voice-over sessions with paper scripts']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='acb0aa1b-588b-5a15-94e3-6aad52e3b565' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Page-turn mitigation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'acb0aa1b-588b-5a15-94e3-6aad52e3b565','f3b91616-66f6-414b-a35a-23a86671f275',true
