INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a40fbf6e-e934-5cf7-a8ee-a5217bbf0107','Pass-by chatter','Short fragments of background conversation performed by a loop group to represent people moving past or through frame, adding directional, transient voices to a walla bed.','The little bits of talk you hear from people walking past in a scene. A loop group records these short lines so a busy place feels alive and full of movement.','It adds a sense of movement and individuality to a crowd background, so the space feels like real people passing rather than a flat, static murmur.','In a loop-group session, performers deliver brief walking-past exchanges that the editor then pans across the scene to suggest motion.','Group ADR',ARRAY['Walla','Loop group','Omni crowd','Period walla','Group ADR']::text[],ARRAY['Making pass-by lines too witty or intelligible, so they steal focus from the principal dialogue.','Recording pass-bys at one static level so they never sound like they move through the scene.']::text[],ARRAY['Busy sidewalk or street exterior','Hotel lobby or airport terminal','Open-air market background']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a40fbf6e-e934-5cf7-a8ee-a5217bbf0107' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pass-by chatter'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a40fbf6e-e934-5cf7-a8ee-a5217bbf0107','f3b91616-66f6-414b-a35a-23a86671f275',true
