INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1f394e89-dcd3-5854-a076-ceb8529c8a40','Patch read','A brief re-recording of only a small defective portion of a dialogue line, such as a single word, phrase, or breath, intended to be edited seamlessly into an otherwise-good take rather than replacing the whole line.','When only one word or phrase in a line is wrong, you re-record just that small piece. Then you drop it into the good take like a patch on a hole.','It saves time and protects a strong performance by fixing only the faulty fragment instead of forcing the actor to redo the entire line.','The editor flags a bad word, the actor reads just that word a few times, and the mixer cuts the best version into the master take.','Recording technique',ARRAY['Pick-up match','Pick-up boundary','Phrase-tail match','Post-sync','Room tone']::text[],ARRAY['Recording the patch at a different mic distance or level so it will not match the surrounding line.','Forgetting to capture room tone or handles around the patch, making the edit audible.']::text[],ARRAY['Fixing a single mispronounced word','Replacing a censored word for a broadcast version','Repairing one off-sync syllable']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1f394e89-dcd3-5854-a076-ceb8529c8a40' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Patch read'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1f394e89-dcd3-5854-a076-ceb8529c8a40','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1f394e89-dcd3-5854-a076-ceb8529c8a40' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5171690b-f2e9-5cb2-b0b4-40bfc26d02f9','Performance drift','The gradual departure of a replacement (ADR) performance from the tone, energy, pacing, or emotional intent of the original production take, typically creeping in over repeated takes or a long session.','Over many takes, an actor''s re-recorded performance can slowly drift away from how they played the scene on set. The new lines start to feel different from the picture.','Naming it helps supervisors catch and correct this divergence, so the replaced dialogue still matches the picture and the surrounding performance.','The ADR supervisor replays the original guide track between takes to pull the actor back toward the on-set energy, pace, and emotion.','Performance',ARRAY['Guide track','Post-sync','Pickup drift','Open-mouth vowel hold','Lip-sync']::text[],ARRAY['Doing many takes in a row without referencing the original, letting energy and pace slide.','Chasing perfect sync so hard that the original emotion of the scene is lost.']::text[],ARRAY['Re-recording an emotional scene over many takes','Late-session fatigue changing an actor''s delivery','Replacing a shouted on-set line with a calmer booth read']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5171690b-f2e9-5cb2-b0b4-40bfc26d02f9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Performance drift'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
