INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '85e1e3e0-4cb4-59a3-ad61-52c052719d34','Period walla','Crowd background walla recorded so that its vocabulary, slang, idiom, accents, and references are historically accurate to the film''s time period, avoiding anachronistic language.','Background crowd talk that fits the time the story is set in. In a scene from the 1920s, the extras cannot use modern slang or mention things that did not exist yet.','It prevents anachronisms in background dialogue that would break an audience''s belief in a period setting.','The loop-group leader briefs performers on era-appropriate phrases and steers them away from modern words and references during recording.','Group ADR',ARRAY['Walla','Loop group','Omni crowd','Pass-by chatter','Group ADR']::text[],ARRAY['Letting modern slang, brand names, or references slip into a historical crowd bed.','Using accents or dialects that do not fit the era or region of the scene.']::text[],ARRAY['Tavern crowd in a period drama','1940s railway-station background','Historical battlefield or market walla']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='85e1e3e0-4cb4-59a3-ad61-52c052719d34' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Period walla'),'[^a-z0-9]','','g'));
