SELECT '85e1e3e0-4cb4-59a3-ad61-52c052719d34','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='85e1e3e0-4cb4-59a3-ad61-52c052719d34' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ec060430-c6ac-56dd-90a4-6dc29f83735c','Phrase-tail match','Matching the end of a spoken phrase - its final syllable, breath, decay, level, and tone - between a re-recorded segment and the surrounding dialogue so the join is inaudible.','The end of a spoken phrase has a certain fade and breath. When you splice in new audio, its tail must match the old one so the cut cannot be heard.','It ensures edits between pickups, patches, and original dialogue are seamless at phrase endings, where mismatches in level or tone are easy to hear.','The editor trims and levels the new phrase so its trailing breath and decay line up with the original before crossfading the two together.','Dialogue editing',ARRAY['Pick-up match','Pick-up boundary','Patch read','Post-sync','Room tone']::text[],ARRAY['Cutting off the trailing breath so the phrase ends abruptly and unnaturally.','Matching the start of a phrase but ignoring its tail, leaving an audible seam at the end.']::text[],ARRAY['Joining an ADR pickup to production dialogue','Patching a faulty phrase ending','Matching trailing breaths across an edit']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ec060430-c6ac-56dd-90a4-6dc29f83735c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Phrase-tail match'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ec060430-c6ac-56dd-90a4-6dc29f83735c','f3b91616-66f6-414b-a35a-23a86671f275',true
