INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ec0478ed-32e9-5e80-b598-c32d6d4b9865','Pick-up boundary','The precise in- or out-point where a pickup (a partial re-recording) is joined to the retained surrounding dialogue, chosen to fall on a natural break such as a breath, a hard consonant, or a silence so the edit is undetectable.','When you replace only part of a line, there is a spot where the new audio meets the old. That spot is the pick-up boundary, and it is best hidden in a breath or pause.','It defines where the replacement begins and ends, guiding editors to cut at points that naturally hide the transition between old and new audio.','The editor sets the pick-up boundary on a hard consonant or a breath so the change from old audio to new cannot be heard.','Dialogue editing',ARRAY['Pick-up match','Phrase-tail match','Patch read','Post-sync','Room tone']::text[],ARRAY['Placing the boundary in the middle of a vowel, where a tone or level shift becomes obvious.','Ignoring room tone across the boundary, leaving an audible gap or texture change.']::text[],ARRAY['Splicing a re-recorded phrase into a longer line','Choosing an edit point in an ADR session','Joining a booth pickup to production sound']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ec0478ed-32e9-5e80-b598-c32d6d4b9865' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pick-up boundary'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ec0478ed-32e9-5e80-b598-c32d6d4b9865','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ec0478ed-32e9-5e80-b598-c32d6d4b9865' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a74d93a7-92b7-55b7-a09d-b4e3baa4daf2','Pick-up match','The process of matching a re-recorded pickup to the surrounding original dialogue in level, timbre, microphone perspective, ambience, and performance energy so the two blend seamlessly.','A pickup is a small re-recorded part of a line. Pick-up match means making that new piece sound just like the rest. It needs the same loudness, tone, and room sound. Then no one can tell it was added.','It ensures a partial re-record is indistinguishable from the original, preserving the continuity and believability of the line.','The mixer matches the mic type and distance, then uses EQ and reverb matching to blend the pickup into the production track.','Dialogue editing',ARRAY['Pick-up boundary','Phrase-tail match','Patch read','Room tone','Post-sync']::text[],ARRAY['Matching level but not room tone or reverb, so the pickup sounds drier than the scene around it.','Using a different mic or distance, which changes the perspective audibly.']::text[],ARRAY['Blending an ADR line into surrounding production dialogue','Matching a booth pickup to a location line','Keeping continuity across a picture cut']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a74d93a7-92b7-55b7-a09d-b4e3baa4daf2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pick-up match'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a74d93a7-92b7-55b7-a09d-b4e3baa4daf2','f3b91616-66f6-414b-a35a-23a86671f275',true
