INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7d0a1412-e288-5ce5-998d-5d57e65d3eea','Pickup drift','The progressive loss of synchronization or performance match within a pickup, where timing gradually slips relative to the picture or the original line as the take proceeds.','When you re-record part of a line, the timing can slowly slide out of step with the picture. That slow slide is called pickup drift.','Naming it helps editors spot and correct creeping sync errors before they build into an obvious mismatch with the picture.','The editor uses a time-alignment tool such as VocALign to pull a drifting pickup back into sync with the guide track.','Sync',ARRAY['Pick-up match','Performance drift','Guide track','Post-sync','Phrase-tail match']::text[],ARRAY['Fixing the sync on the first word but letting the rest of the pickup drift off.','Overusing time-warping to force sync, which creates audible pitch or texture artifacts.']::text[],ARRAY['A long pickup line slipping out of sync with picture','Aligning an ADR take to its guide track','Correcting a slow timing slip across a phrase']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7d0a1412-e288-5ce5-998d-5d57e65d3eea' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pickup drift'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7d0a1412-e288-5ce5-998d-5d57e65d3eea','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7d0a1412-e288-5ce5-998d-5d57e65d3eea' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e53e6646-fb2c-5a96-89da-7da1658f2b21','Post-roll contamination','Unwanted audio captured during the post-roll - the recording that continues briefly after the cued line ends - such as a breath, an early next word, a movement, or booth noise that intrudes on the usable take.','The recorder keeps rolling for a moment after the line ends. If the actor breathes, moves, or talks in that gap, it can spoil the take. That is post-roll contamination.','Awareness of it keeps the tail of a take clean, giving editors usable handles after the line without extra noise to remove.','The mixer coaches the actor to hold still until the cut, and trims any post-roll noise before delivering the take.','Recording technique',ARRAY['Pre-roll chatter','Room tone','Post-sync','Page-turn mitigation','Punch cue']::text[],ARRAY['Cutting the recording so tight there is no clean handle left after the last word.','Letting the actor drop out of character noisily right after the line ends.']::text[],ARRAY['A breath caught just after a delivered line','The next cue started too early on the tail','A chair creak or paper rustle after the last word']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e53e6646-fb2c-5a96-89da-7da1658f2b21' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Post-roll contamination'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e53e6646-fb2c-5a96-89da-7da1658f2b21','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e53e6646-fb2c-5a96-89da-7da1658f2b21' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9b4b03b0-e78d-530a-bfb2-314434cf38c2','Post-sync','Post-synchronization: the recording of dialogue or other vocal sound in a studio after shooting, edited to synchronize with the picture; the umbrella term that includes ADR, looping, and dubbing.','Post-sync means adding or replacing voices after filming, then lining them up with the picture. Re-recording an actor''s lines in a booth is one form of post-sync.','It provides clean, controllable dialogue when the production sound is unusable, and adds voices such as narration, dubbed lines, or crowd that were not recorded on set.','When location sound is too noisy to use, the dialogue editor schedules post-sync sessions to re-record the affected lines to picture.','Dialogue replacement',ARRAY['ADR','Looping','Dubbing','Guide track','Lip-sync']::text[],ARRAY['Assuming post-sync always sounds worse than production sound, when careful matching can be seamless.','Neglecting to match the acoustic space of the original scene, so the new line sounds like a booth.']::text[],ARRAY['Replacing noisy location dialogue','Foreign-language dubbing of a film','Adding voice-over narration to picture']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9b4b03b0-e78d-530a-bfb2-314434cf38c2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Post-sync'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9b4b03b0-e78d-530a-bfb2-314434cf38c2','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9b4b03b0-e78d-530a-bfb2-314434cf38c2' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4af4c4c0-166e-573d-aed6-0f64e8f3ddd4','Pre-roll chatter','Unwanted vocal sound or noise - an actor''s aside, a breath, a false start, or booth talk - occurring during the pre-roll, the lead-in before the cued line, that intrudes on the head of a take.','Before the actor''s line starts, the recorder is already rolling. Any chatter, breath, or noise in that run-up can spoil the start of the take.','Awareness of it keeps the head of a take clean, so editors have a usable handle of quiet before the first word.','The mixer reminds the actor to stay quiet through the beeps and pre-roll, then trims any chatter before the line begins.','Recording technique',ARRAY['Post-roll contamination','Punch cue','Page-turn mitigation','Room tone','Post-sync']::text[],ARRAY['Talking or breathing heavily during the countdown beeps.','Starting a take with no clean pre-roll handle before the first word.']::text[],ARRAY['An actor''s aside caught before a line','A heavy breath landing during the beeps','A false start on the head of a take']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4af4c4c0-166e-573d-aed6-0f64e8f3ddd4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pre-roll chatter'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4af4c4c0-166e-573d-aed6-0f64e8f3ddd4','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4af4c4c0-166e-573d-aed6-0f64e8f3ddd4' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '20ceedc8-5542-5070-a5ce-da4c397264c7','Punch cue','A cueing signal that tells an ADR performer the exact frame to begin, historically a punch - a flash or hole marked on the film that appears at the sync point - used together with a moving streamer and a series of countdown beeps.','A punch cue is a signal that flashes on screen to show the actor the exact moment to start speaking. It usually comes with a line that sweeps across and three warning beeps.','It gives the performer a precise, repeatable visual and audible countdown so their line starts in sync with the picture, take after take.','The ADR system plays three beeps and runs a streamer to a punch flash; the actor begins on the silent fourth beat, where the punch lands.','Cueing',ARRAY['Streamer','Pre-roll chatter','Post-sync','ADR','Guide track']::text[],ARRAY['Starting on the third audible beep instead of the silent fourth beat where the punch lands.','Watching the streamer but ignoring the punch, so the line starts a frame or two off.','UNSAFE: Monitoring the beeps on headphones at excessive levels over a long session risks noise-induced hearing loss; keep headphone levels moderate.']::text[],ARRAY['Cueing an actor to the start of a line','Signaling the beginning of an ADR take','Matching a shout precisely to picture']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='20ceedc8-5542-5070-a5ce-da4c397264c7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Punch cue'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '20ceedc8-5542-5070-a5ce-da4c397264c7','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='20ceedc8-5542-5070-a5ce-da4c397264c7' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8f4dfc87-0548-568b-a291-950c828a2fb6','Punch-and-roll','A recording workflow in which the system plays back the last few seconds of an existing take as pre-roll, then automatically drops into record at a defined punch point so the performer can continue seamlessly from where they left off. It is widely used in long-form voice work and ADR to repair errors without re-recording an entire pass.','The recorder plays back the last few seconds you already said. Then it starts recording right where you stopped. You keep talking, and the new words join on smoothly. This lets you fix one mistake without redoing the whole take.','It lets a narrator or dialogue editor repair a flub in place while keeping continuous tone, pacing, and performance, avoiding a full retake.','An audiobook narrator or ADR editor sets a pre-roll, hears the last line, and punches in on the next word to overwrite a mistake, keeping the session moving quickly.','Recording Technique',ARRAY['Tail pickup','Rock-and-roll recording','Scratch read','Sync ADR','Room-tone capture']::text[],ARRAY['Punching in too early or too late so the joined words overlap or leave a gap, creating an audible seam.','Changing mic distance, level, or vocal energy after the punch so the repaired section no longer matches the surrounding tone.','UNSAFE: Cranking the pre-roll playback to painful levels in the performer''s headphones; set safe, comfortable monitoring levels to protect hearing.']::text[],ARRAY['An audiobook narrator fixes a single misread word in a long chapter without redoing the page.','A dialogue editor repairs a lip-smack or stumble in an ADR line by punching in on the next syllable.','A voice-over artist recording a long script keeps continuous flow after a cough.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8f4dfc87-0548-568b-a291-950c828a2fb6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Punch-and-roll'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8f4dfc87-0548-568b-a291-950c828a2fb6','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8f4dfc87-0548-568b-a291-950c828a2fb6' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'abb3e147-ab34-50d2-9f4a-b8896261f7c4','Resonance match','The practice of matching the resonant, timbral, and spatial character of a replacement or edited dialogue line to the original production recording, so that body resonance, room reflections, and perspective are perceptually consistent. It is achieved through microphone choice and placement, distance, equalization, and reverberation.','Every voice and room has its own tone color. New lines recorded later must sound like the first take. This means matching the depth of the voice and the feel of the room. Editors adjust the microphone and the tone controls until both blend.','It exists so re-recorded or edited lines sit believably beside production dialogue, preventing a thin, boxy, or disconnected sound that pulls the audience out of the scene.','When cutting ADR against location dialogue, an editor matches mic type, distance, and EQ, then adds matched reverb so the replaced line shares the same resonance and space.','Dialogue Editing',ARRAY['Sync ADR','Room-tone capture','Session-tone drift','Soft-sync line','Tail room']::text[],ARRAY['Matching only loudness while ignoring timbre, so the line is the right level but the wrong tone.','Recording ADR in a dead booth and forgetting the room''s reflections, leaving the line too dry to match location sound.','Overusing equalization to force a match instead of correcting the underlying mic distance and placement.']::text[],ARRAY['Blending a studio ADR line into a scene shot in a tiled bathroom.','Matching a close boom-mic take to a lav-mic take of the same actor.','Making a pickup recorded weeks later match the original set recording.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='abb3e147-ab34-50d2-9f4a-b8896261f7c4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Resonance match'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'abb3e147-ab34-50d2-9f4a-b8896261f7c4','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='abb3e147-ab34-50d2-9f4a-b8896261f7c4' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b28f42a4-bb27-5fc3-9e2b-0a722a94e29e','Rhythmo band','A dialogue-replacement technique in which the script text is written on a horizontally scrolling band, synchronized to picture, that passes a fixed vertical cue line; the performer reads each word as it reaches the line to achieve precise lip-sync. It originated in France as the bande rythmo on clear 35 mm strips and is now implemented in software.','The words of the script scroll across the screen like a moving ribbon. A line marks the exact moment to say each word. The actor reads along as the text passes the line. This helps the new voice match the lips on screen. It began in France and is now done with software.','It gives the performer a continuous visual cue for timing and lip-sync, allowing long takes without memorizing cues or waiting for beeps, which speeds dubbing and ADR.','In dubbing and ADR sessions the mixer loads the rhythmo band in dedicated software so the actor reads the scrolling text in sync with the picture.','ADR Technique',ARRAY['Sync ADR','Punch-and-roll','Scratch read','Rock-and-roll recording','Soft-sync line']::text[],ARRAY['Assuming the rhythmo band replaces good direction; the performance still needs coaching, not just accurate timing.','Poorly timed text on the band pushes the actor to rush or drag, producing lines that read on time but sound unnatural.','UNSAFE: Setting cue tones or guide playback painfully loud in the talent''s headphones; keep monitoring at safe levels to protect hearing.']::text[],ARRAY['Dubbing a foreign-language film into English using scrolling text.','Recording many ADR lines quickly for a television episode.','Guiding a non-native actor to match on-screen lip movements.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b28f42a4-bb27-5fc3-9e2b-0a722a94e29e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Rhythmo band'),'[^a-z0-9]','','g'));
