SELECT 'b28f42a4-bb27-5fc3-9e2b-0a722a94e29e','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b28f42a4-bb27-5fc3-9e2b-0a722a94e29e' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a4176dd4-29e4-5ff7-8302-71d4d63429f6','Rock-and-roll recording','A re-recording and dialogue-recording method using interlocked, resettable transports that can run forward and be backed up (rock back, roll forward) so an operator can review, reposition, and punch in or re-record a section continuously without stopping to rethread or reset. It descended from 1960s back-up recording on the dubbing stage.','The picture and sound machines are locked together. The operator can roll forward, then back up over the same spot. This lets them redo a short section without starting over. It keeps the session flowing during dubbing and dialogue work.','It exists to let mixers and recordists correct small sections and build a mix or ADR pass in continuous cycles, rather than restarting a whole reel after every mistake.','On a dubbing stage or in ADR, the operator rocks back over a line, punches in the fix, and rolls forward, repeating until the section is right.','Recording Technique',ARRAY['Punch-and-roll','Sync ADR','Rhythmo band','Tail pickup','Room-tone capture']::text[],ARRAY['Confusing it with the music genre; here it names the back-up-and-continue recording method, not a style of music.','Backing up without matching the earlier level or perspective, so the re-recorded section no longer matches.','Rolling continuously without clearly marking punch points, so good takes get overwritten.']::text[],ARRAY['Re-recording a short passage of a mix after catching a fader error.','Punching in repeated ADR attempts on one line during a fast session.','Fixing a small dialogue section on a dubbing stage without redoing the reel.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a4176dd4-29e4-5ff7-8302-71d4d63429f6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Rock-and-roll recording'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a4176dd4-29e4-5ff7-8302-71d4d63429f6','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a4176dd4-29e4-5ff7-8302-71d4d63429f6' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4baadd73-115c-51da-b024-0d14c7d6eaae','Room-tone capture','The deliberate recording of a location''s or set''s ambient background sound with no dialogue or action, captured at the same microphone position, gain, and configuration as the scene. Dialogue editors use it to fill gaps, smooth edits, and bridge inserted or replaced dialogue into the ambient bed.','Every room has a quiet background sound, even when no one talks. The crew records this quiet for a short time on set. Editors later slip it under cuts and new lines. This hides gaps so edits sound smooth and natural.','It gives the dialogue editor matching background to patch holes left by edits, noise removal, or ADR, keeping the ambient bed continuous and believable.','At the end of a scene the assistant director calls for quiet and the mixer records roughly thirty seconds to a minute of room tone at the scene''s mic setup.','Production Sound',ARRAY['Session-tone drift','Resonance match','Sync ADR','Specific walla','Tail room']::text[],ARRAY['Recording room tone at a different level or mic position than the scene, so it will not match in the edit.','Skipping room tone on set and hoping to fake it later from noisy gaps between lines.','Capturing only a few seconds, leaving too little to loop cleanly under a long scene.']::text[],ARRAY['Filling a silent gap after a noise is removed from a line.','Bridging an ADR line into the surrounding location ambience.','Smoothing a dialogue edit between two takes with different backgrounds.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4baadd73-115c-51da-b024-0d14c7d6eaae' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Room-tone capture'),'[^a-z0-9]','','g'));
