SELECT '4baadd73-115c-51da-b024-0d14c7d6eaae','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4baadd73-115c-51da-b024-0d14c7d6eaae' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3e370f0b-5a67-5d4c-bd20-8074ad48ab18','Scratch read','A temporary, non-final recording of narration or dialogue captured as a placeholder or timing guide, intended to be replaced by the final performance. It establishes pacing, length, and intent for editing before the finished read is recorded.','A scratch read is a rough, temporary recording of the lines. It is not the final version. Editors use it to set timing and length while they work. Later, the real, polished read replaces it.','It lets the picture edit, timing, and structure proceed before the final voice is available, so scenes can be cut to a realistic length and rhythm.','An editor records a quick scratch read of the narration to lay out the cut, then swaps in the professional voice-over once it is delivered.','Dialogue Editing',ARRAY['Temp narration','Sync ADR','Punch-and-roll','Soft-sync line','Room-tone capture']::text[],ARRAY['Leaving a scratch read in the final mix because it was never replaced.','Cutting the picture so tightly to the scratch timing that the final read no longer fits.','Treating rough scratch quality as acceptable for delivery instead of a guide only.']::text[],ARRAY['Recording a placeholder voice-over to time a documentary edit.','Laying a temporary narration for a test screening.','Guiding animation timing before the final voice cast records.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3e370f0b-5a67-5d4c-bd20-8074ad48ab18' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Scratch read'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3e370f0b-5a67-5d4c-bd20-8074ad48ab18','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3e370f0b-5a67-5d4c-bd20-8074ad48ab18' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c9ac56cc-ef87-5fbd-96d5-babdd3a73a52','Session-tone drift','A gradual change in the tonal, ambient, or level characteristics of recordings over the course of a session or between sessions, arising from shifts in microphone position, room conditions, equipment temperature, or the performer''s voice. It causes later takes or pickups to no longer match earlier ones.','During a long recording session, the sound can slowly change. The microphone may move, the room may warm up, or the voice may tire. Later takes then stop matching the earlier ones. Editors must watch for this drift and fix it.','Naming it helps editors and recordists catch mismatches early and hold consistent mic placement, levels, and room conditions across takes.','A dialogue editor comparing pickups to originals listens for session-tone drift and corrects it with EQ, matched room tone, or a re-record at the original setup.','Dialogue Editing',ARRAY['Resonance match','Room-tone capture','Sync ADR','Tail pickup','Scratch read','Vocal fatigue drift']::text[],ARRAY['Assuming tone stays constant all day and not logging the mic setup for later pickups.','Blaming the edit for a mismatch that is really slow drift in the source recording.','Letting a tiring performer''s changing voice go unaddressed until the takes no longer cut together.']::text[],ARRAY['Pickups recorded hours after the main take no longer match.','A returning actor''s ADR sounds different from a session recorded weeks earlier.','Air conditioning cycling on changes the background between takes.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c9ac56cc-ef87-5fbd-96d5-babdd3a73a52' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Session-tone drift'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c9ac56cc-ef87-5fbd-96d5-babdd3a73a52','f3b91616-66f6-414b-a35a-23a86671f275',true
