INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6f4438a1-b66c-546c-b0b3-3fb28a43f5d4','Slate contamination','Unwanted intrusion of slate sound, such as a clapperboard''s clap or a spoken voice slate, into the usable portion of a take, for example when the slate falls too close to the first line or a tail slate overlaps the performance. It compromises the clean heads or tails needed for editing.','A slate marks each take with a clap or a spoken label. Sometimes that sound spills into the real performance. It can cover the first or last words. This leaves the editor without a clean start or end to cut on.','Naming it helps crews leave clear space around the slate so each take has clean heads and tails for editing and sync.','A sound recordist and editor guard against slate contamination by leaving a gap after the slate before action and avoiding tail slates that crowd the last line.','Production Sound',ARRAY['Tail room','Tail pickup','Room-tone capture','Sync ADR','Scratch read']::text[],ARRAY['Clapping or calling the slate too close to the first word, burying clean dialogue.','Using a tail slate that overlaps the final line, so there is no clean tail to edit.','Forgetting that voice-slate identification can bleed under a soft opening line.']::text[],ARRAY['A clapperboard clap overlaps an actor''s first word.','A tail slate crowds the last line of a quiet scene.','A spoken take label bleeds under the opening of a soft delivery.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6f4438a1-b66c-546c-b0b3-3fb28a43f5d4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Slate contamination'),'[^a-z0-9]','','g'));
