INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8f96ae40-d157-53ea-9f36-4cbbb5e23410','Soft-sync line','A line of dialogue whose visual sync tolerance is loose, typically off-camera, turned away, or without clearly visible lip movement, so exact lip-sync is not required and ADR or editing can be placed more freely. It contrasts with hard-sync, on-camera, lip-visible lines.','Some lines are spoken when the mouth is not clearly seen. The actor may be off-camera or facing away. These lines do not need perfect lip-sync. So editors have more freedom to place or replace them.','Identifying soft-sync lines lets editors and ADR mixers spend tight-sync effort where lips are visible and move faster on lines the audience cannot lip-read.','During ADR spotting, an editor marks soft-sync lines that can be nudged for performance, reserving frame-accurate work for on-camera close-ups.','Dialogue Editing',ARRAY['Sync ADR','Rhythmo band','Resonance match','Scratch read','Tail pickup']::text[],ARRAY['Treating every line as hard sync and wasting time perfecting sync the audience cannot see.','Assuming soft sync means sync can be ignored; it still must feel connected to the scene.','Missing that a soft-sync line briefly shows the lips, which then need tightening.']::text[],ARRAY['Replacing an off-camera reaction line during ADR.','Fixing a line delivered while the actor faces away.','Placing narration-style dialogue over a wide shot with no visible mouth.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8f96ae40-d157-53ea-9f36-4cbbb5e23410' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Soft-sync line'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8f96ae40-d157-53ea-9f36-4cbbb5e23410','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8f96ae40-d157-53ea-9f36-4cbbb5e23410' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '544473bf-6bf0-594c-a0a8-f22be93b3936','Specific walla','Background crowd voice (walla) that contains intelligible, scripted, or plot-relevant words and reactions tied to particular on-screen action, as distinct from general, nonspecific murmur (often called rhubarb). It is performed by a loop group with defined callouts and cues.','Walla is the murmur of a crowd in the background. Specific walla has real, clear lines you can understand. These match what is happening on screen, like a named callout. A loop group records them on cue, not just a general hum.','It adds believable, story-relevant detail to crowd scenes, such as reactions and callouts, that a general murmur cannot provide, supporting clarity and realism.','A loop group director cues actors to record specific walla lines, such as a vendor''s shout or a reaction, timed to on-screen moments, alongside beds of general walla.','Loop Group',ARRAY['Sync ADR','Room-tone capture','Rhythmo band','Scratch read','Soft-sync line']::text[],ARRAY['Recording only general murmur and leaving needed callouts unintelligible or missing.','Making specific lines so loud or clear that they compete with the principal dialogue.','Ignoring period, language, or location accuracy in the scripted crowd lines.']::text[],ARRAY['A market scene needs vendors'' scripted shouts.','A restaurant scene needs a specific reaction to an on-screen event.','A sports crowd needs cued chanting matching the action.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='544473bf-6bf0-594c-a0a8-f22be93b3936' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Specific walla'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '544473bf-6bf0-594c-a0a8-f22be93b3936','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='544473bf-6bf0-594c-a0a8-f22be93b3936' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dc6790e7-89f8-53ef-9747-cbcfbd4674d0','Sync ADR','Automated dialogue replacement recorded to match the original picture precisely, so the new line aligns with the actor''s on-screen mouth movements and timing. It is the lip-sync case of ADR, as opposed to wild lines, narration, or non-sync replacement.','ADR stands for automated dialogue replacement. It records new lines to replace old ones. Sync ADR must match the actor''s lips on screen. The timing has to line up frame by frame with the picture.','It replaces unusable production dialogue with clean studio recordings while preserving the illusion that the words come from the actor on screen.','In an ADR session the actor watches the picture and cue, then delivers the line repeatedly until it matches lip movement and can be fine-tuned in editing.','ADR Technique',ARRAY['Rhythmo band','Punch-and-roll','Rock-and-roll recording','Soft-sync line','Resonance match']::text[],ARRAY['Chasing frame-perfect sync while ignoring performance, so the line matches but sounds flat.','Forgetting to match the room and perspective, leaving a clean line that sounds pasted on.','UNSAFE: Playing cue beeps or guide tracks at painful levels in the actor''s headphones; set safe monitoring levels to protect hearing.']::text[],ARRAY['Replacing dialogue ruined by set noise on a close-up.','Re-recording a mumbled on-camera line for clarity.','Changing a scripted word while keeping the lip movement believable.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dc6790e7-89f8-53ef-9747-cbcfbd4674d0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sync ADR'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dc6790e7-89f8-53ef-9747-cbcfbd4674d0','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dc6790e7-89f8-53ef-9747-cbcfbd4674d0' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '69ec2a15-75a0-516b-8b6e-414ff6590ea4','Tail pickup','A pickup recording that covers only the end (tail) portion of a line or take rather than the whole line, used to repair a flub, noise, or timing problem near the end while keeping the good earlier portion. The tail pickup is later edited onto the original take.','Sometimes only the end of a line goes wrong. Instead of redoing it all, you record just that ending. This new ending is called a tail pickup. The editor joins it onto the good first part.','It saves time and preserves a strong opening performance by re-recording only the problem tail, then splicing it to the kept head.','When an actor nails a line but flubs the last word, the recordist grabs a tail pickup of the ending to edit onto the original take.','Recording Technique',ARRAY['Punch-and-roll','Tail room','Rock-and-roll recording','Sync ADR','Session-tone drift']::text[],ARRAY['Recording the tail pickup at a different level or tone so it will not splice cleanly.','Leaving no overlap word, giving the editor no clean point to join the two parts.','Forgetting to match the pace and energy of the original ending.']::text[],ARRAY['Fixing a flubbed final word of an otherwise perfect take.','Repairing a noise that lands only on the end of a line.','Replacing the tail of a line to adjust timing.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='69ec2a15-75a0-516b-8b6e-414ff6590ea4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tail pickup'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '69ec2a15-75a0-516b-8b6e-414ff6590ea4','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='69ec2a15-75a0-516b-8b6e-414ff6590ea4' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f5d9d7e2-bfb2-5a9d-94ad-ed8d02b65a36','Tail room','Extra recorded material, such as silence, room tone, or held ambience, left at the end (tail) of a take or region, giving editors handle for fades, crossfades, and natural decay. It ensures a clean, editable end rather than an abrupt cut.','Tail room is a little extra recording left at the end of a take. It holds the quiet room sound after the last word. Editors use it to fade out smoothly or blend into the next sound. Without it, cuts can end too sharply.','It provides handle at the end of a clip so edits, fades, and reverb tails resolve naturally instead of clipping off.','A recordist keeps rolling for a moment after the last word so the editor has tail room to fade or crossfade the region.','Dialogue Editing',ARRAY['Tail pickup','Room-tone capture','Slate contamination','Sync ADR','Resonance match']::text[],ARRAY['Stopping the recorder the instant the line ends, leaving no tail to work with.','Confusing tail room with a full room-tone recording; it is the short handle at a take''s end.','Letting noise or a tail slate fill the tail so it cannot be used as clean handle.']::text[],ARRAY['Fading a line gently into the next scene.','Crossfading two dialogue regions without a click.','Preserving a reverb tail at the end of a delivered line.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f5d9d7e2-bfb2-5a9d-94ad-ed8d02b65a36' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tail room'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f5d9d7e2-bfb2-5a9d-94ad-ed8d02b65a36','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f5d9d7e2-bfb2-5a9d-94ad-ed8d02b65a36' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '426d184a-8f1b-5b4c-b53f-3c1d61a23259','Temp narration','Temporary narration recorded as a placeholder in an edit or temp mix before the final narration is produced, used to establish timing, pacing, and structure and often to guide test screenings. It is replaced by the final voice-over in the finished program.','Temp narration is a stand-in voice-over used while editing. It is not the final version. It sets the timing and shows how the story flows. Later, the real narration replaces it.','It lets editors and producers shape and test a program''s structure and length before committing to the final, often more expensive, narration recording.','An editor lays temp narration over a documentary cut to time scenes and screen it for notes, then swaps in the final read.','Dialogue Editing',ARRAY['Scratch read','Sync ADR','Room-tone capture','Soft-sync line','Punch-and-roll']::text[],ARRAY['Forgetting to replace temp narration before final delivery.','Editing so tightly to the temp timing that the final narration no longer fits.','Mistaking rough temp quality for something acceptable to broadcast.']::text[],ARRAY['Timing a documentary cut before the narrator records.','Screening a rough cut with placeholder voice-over for notes.','Pacing a corporate video while awaiting the final voice talent.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='426d184a-8f1b-5b4c-b53f-3c1d61a23259' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Temp narration'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
