WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='426d184a-8f1b-5b4c-b53f-3c1d61a23259' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c9fc4578-dca0-5d77-9253-ccf2f764e85c','Three-beep cue','In ADR, a sequence of three short audible beeps spaced one second apart, fed to the performer''s headphones ahead of a line; the actor begins speaking on the downbeat where a silent fourth beep would fall, so the replacement dialogue aligns to picture. It is frequently paired with a visual streamer or wipe as a redundant timing reference.','The actor hears three beeps in the headphones, one second apart. They start the line right when a fourth beep would come. This keeps the new words lined up with the picture.','It gives the performer a steady, predictable count-in so the re-recorded line starts in sync with the on-screen mouth movements, without the editor having to guess the entry point.','The ADR mixer lays three-beep cues ahead of each looped line in the session so the actor can enter on time, take after take.','ADR cueing',ARRAY['Automated Dialogue Replacement (ADR)','Streamer','Looping','Throwaway lead-in','Lip sync','Wild line']::text[],ARRAY['Thinking you speak on the third beep; the line actually starts one beat later, where the silent fourth beep falls.','Changing the beep spacing away from the session standard, so performers trained on one-second beeps mis-time their entrance.','Leaving the beeps audible in the printed take instead of muting or gating them before the recording is kept.']::text[],ARRAY['Replacing an off-mic line for an actor in a noisy exterior scene.','Cueing a voice actor line-by-line during an animation or dubbing session.','Building an ADR session template so every cue has consistent pre-roll beeps.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c9fc4578-dca0-5d77-9253-ccf2f764e85c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Three-beep cue'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c9fc4578-dca0-5d77-9253-ccf2f764e85c','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c9fc4578-dca0-5d77-9253-ccf2f764e85c' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b670ba98-6d64-5103-b0ba-5101c40d052c','Throwaway lead-in','An extra, unused word or short phrase a performer says immediately before the scripted ADR line to establish rhythm, pitch, and vocal level; it is discarded once the matched line is captured, though it may be kept as an edit handle.','Before the real line, the actor says a spare word or two to warm up. It helps them find the right speed and loudness. That warm-up part is then cut out.','It lets the actor slide into the line''s natural cadence and energy instead of cold-starting on the first word, improving sync and performance match while giving the editor clean handles.','A dialogue editor trims the throwaway lead-in off the front of the take, keeping only the matched line but sometimes retaining it for a crossfade handle.','ADR performance',ARRAY['Automated Dialogue Replacement (ADR)','Three-beep cue','Handle','Wild line','Dialogue editing','Lip sync']::text[],ARRAY['Leaving the throwaway words in the final edit, so an extra syllable appears before the synced line.','Making the lead-in a real scripted word, which confuses the editor about where the usable line begins.','Performing the lead-in at a different level than the real line, so it is useless as a level reference.']::text[],ARRAY['An actor tosses off a soft ''okay'' before delivering the matched ADR line.','A voice actor uses a lead-in breath and word to reach the emotional energy of the take.','An editor uses the discarded lead-in audio as a handle for a smooth crossfade.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b670ba98-6d64-5103-b0ba-5101c40d052c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Throwaway lead-in'),'[^a-z0-9]','','g'));
