WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b670ba98-6d64-5103-b0ba-5101c40d052c' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fbc4bf2f-69db-559b-84d9-60a8a31f6caa','Vocabulary-safe walla','Background crowd walla performed and edited so that no distinct, recognizable, or contextually inappropriate words are intelligible; performers use neutral or nonsense phrases (such as ''rhubarb'' or ''peas and carrots'') to keep the murmur indistinct and free of clashing or legally risky speech.','This is crowd background noise made so no clear words stand out. Actors mumble neutral or nonsense phrases like ''peas and carrots.'' That keeps the chatter blurry and stops odd or wrong words from being heard.','It keeps the crowd as texture rather than competing dialogue, avoiding distracting or wrong-for-the-scene words, language slips, or phrases that could raise legal or continuity problems.','A loop group leader directs performers to stay vocabulary-safe, steering them away from real names, brands, or scene-specific lines that could poke through the mix.','Walla',ARRAY['Walla','Loop group','Rhubarb','Walla poke-through','Walla bed','Group ADR']::text[],ARRAY['Letting performers ad-lib real, intelligible sentences that draw the audience''s ear away from the principal dialogue.','Using recognizable brand names, real people''s names, or slurs that create legal or editorial problems.','Recording crowd lines in the wrong language or period for the scene, so a stray word breaks the illusion.']::text[],ARRAY['Directing a restaurant loop group to murmur neutral phrases under a lead couple''s conversation.','Replacing a live crowd recording that contained an audible, inappropriate shout.','Building a period-drama crowd where modern slang must never surface.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fbc4bf2f-69db-559b-84d9-60a8a31f6caa' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocabulary-safe walla'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fbc4bf2f-69db-559b-84d9-60a8a31f6caa','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fbc4bf2f-69db-559b-84d9-60a8a31f6caa' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6a05f343-513d-5cf2-934b-71c7a09dd154','Vocal fatigue drift','The gradual change in a performer''s vocal quality — pitch, timbre, energy, or steadiness — as the voice tires over a long recording session, causing later takes to no longer match earlier ones or the original production performance.','As an actor records for a long time, their voice slowly tires and changes. Later takes can sound lower, rougher, or weaker than earlier ones. Then the new lines stop matching the first recording.','Naming this effect reminds the team to watch for and manage tiredness so replaced lines still match the character''s voice across a scene.','An ADR supervisor schedules the hardest, most emotional lines early, offers water and breaks, and re-checks matches when a session runs long.','ADR performance',ARRAY['Automated Dialogue Replacement (ADR)','Voice-match note','Wild line','Dialogue editing','Loop group']::text[],ARRAY['Assuming a voice stays identical all day and skipping A/B checks against earlier takes.','Scheduling shouting or crying lines at the end of a long session, when the voice is spent.','UNSAFE: Pushing a performer to keep yelling through hoarseness or pain risks vocal strain or injury; stop, rest, and hydrate instead.']::text[],ARRAY['A long ADR day where the actor''s afternoon takes sit lower and rougher than the morning''s.','Matching new lines to a production track recorded when the actor was fresh.','A voice actor recording hundreds of loud combat efforts across one session.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6a05f343-513d-5cf2-934b-71c7a09dd154' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal fatigue drift'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6a05f343-513d-5cf2-934b-71c7a09dd154','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6a05f343-513d-5cf2-934b-71c7a09dd154' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b35bec4a-040c-5d5b-94fd-dd052df9c4d1','Voice-match note','A direction from the ADR supervisor, director, or editor specifying how a performer must adjust delivery so the re-recorded or substitute voice matches the on-screen actor''s pitch, accent, energy, breath, and emotional tone.','This is a note telling the actor how to make their new line sound like the original. It covers pitch, accent, energy, and feeling. The goal is that no one notices the line was re-recorded.','It guides the performance so replacement dialogue blends seamlessly with the surrounding production sound instead of sounding like a different take or a different person.','During playback the supervisor gives voice-match notes between takes, such as ''a touch breathier'' or ''match the accent on that word,'' until the line sits invisibly in the scene.','ADR performance',ARRAY['Automated Dialogue Replacement (ADR)','Vocal fatigue drift','Lip sync','Dialogue editing','Loop group','Wild line']::text[],ARRAY['Focusing only on lip sync while ignoring tone and accent, so the voice matches the mouth but not the character.','Giving vague notes like ''do it better'' instead of a specific, actionable adjustment.','Forgetting to match breath and room energy, so the clean ADR line feels detached from the scene.']::text[],ARRAY['Matching a stand-in or voice double to a lead actor unavailable for ADR.','Correcting an accent that slipped during the original take.','Blending a re-recorded line into surrounding production dialogue during a mix review.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b35bec4a-040c-5d5b-94fd-dd052df9c4d1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Voice-match note'),'[^a-z0-9]','','g'));
