INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b00eacb8-76f9-5c70-aeaa-86a6af29e381','Walla bed','A continuous, sustained layer of background crowd walla laid under a scene to provide a consistent floor of human presence, over which more specific reactions or featured background lines may be added.','A walla bed is a steady layer of crowd murmur under a scene. It runs the whole time to make a place feel full of people. Other, sharper crowd sounds sit on top of it.','It establishes an even, gap-free sense of occupancy so the location feels populated and the space stays alive even when the principal dialogue pauses.','An editor lays a looped walla bed across the scene first, then spots individual reactions and efforts against it to build a believable crowd.','Walla',ARRAY['Walla','Walla density','Walla sweetener','Room tone','Loop group','Walla contour']::text[],ARRAY['Using a walla bed with an obvious loop point that repeats audibly under quiet dialogue.','Setting the bed too loud so it competes with the principals instead of supporting them.','Choosing a bed whose crowd size or mood does not match the on-screen location.']::text[],ARRAY['Filling a busy restaurant so it sounds occupied under the leads'' conversation.','Keeping a stadium alive between bursts of specific crowd reactions.','Covering a scene shot without sound that needs a full crowd built from scratch.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b00eacb8-76f9-5c70-aeaa-86a6af29e381' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Walla bed'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b00eacb8-76f9-5c70-aeaa-86a6af29e381','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b00eacb8-76f9-5c70-aeaa-86a6af29e381' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e172826d-bc60-5c0c-ab25-96324576e216','Walla contour','The shaped dynamic arc of a walla track over time — its swells, dips, and shifts in intensity — edited or performed to follow the emotional and physical action of the scene rather than remaining at a flat level.','Walla contour is the way crowd noise rises and falls over a scene. It swells at big moments and drops when things calm down. This shaping follows the action instead of staying flat.','It makes the crowd feel reactive and alive, reinforcing story beats such as a gasp, a surge, or a hush, instead of a lifeless constant murmur.','The editor rides fader automation or selects performance takes so the walla builds into a reveal and pulls back under a quiet exchange.','Walla',ARRAY['Walla','Walla bed','Walla density','Walla perspective','Loop group','Walla sweetener']::text[],ARRAY['Leaving the walla at one flat level so the crowd never reacts to what happens on screen.','Swelling the crowd on the wrong beat, stepping on a line or a sound effect.','Making dynamic moves so large they feel like an effect rather than a natural crowd.']::text[],ARRAY['Building a courtroom crowd that erupts at a verdict then settles.','Shaping a party so it dips when two characters step aside to talk.','Following a sports crowd rising and falling with the play.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e172826d-bc60-5c0c-ab25-96324576e216' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Walla contour'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e172826d-bc60-5c0c-ab25-96324576e216','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e172826d-bc60-5c0c-ab25-96324576e216' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3deec445-7f29-5ca4-81eb-72b49d7e1468','Walla density','The perceived number and thickness of voices in a walla track — from a sparse handful to a dense, crowded blend — controlled by how many performers or layered tracks are combined.','Walla density is how crowded the background voices sound. A few voices feel like a small room; many layered voices feel like a packed hall. You set it by stacking more or fewer takes.','It lets the sound team match the crowd''s apparent size to the on-screen space and shot, so a small cafe and a packed stadium read as different scales.','To thicken a crowd, an editor layers multiple walla passes at staggered timing and perspective; to thin it, they strip layers back.','Walla',ARRAY['Walla','Walla bed','Walla perspective','Walla contour','Loop group','Group ADR']::text[],ARRAY['Layering the same loop repeatedly, which builds level but not variety, so the crowd sounds like copies.','Making a small, intimate room too dense so it feels wrong for the shot.','Ignoring perspective while stacking, so every added voice sits at the same distance.']::text[],ARRAY['Turning a dozen loop-group performers into a convincing full stadium.','Keeping a quiet library sparse with only a few distant voices.','Matching crowd size to a wide establishing shot versus a tight two-shot.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3deec445-7f29-5ca4-81eb-72b49d7e1468' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Walla density'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3deec445-7f29-5ca4-81eb-72b49d7e1468','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3deec445-7f29-5ca4-81eb-72b49d7e1468' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '23cf7e0c-4dc6-58bf-9ea3-e2c153a35505','Walla perspective','The spatial placement of walla relative to the camera — its distance, level, equalization, reverberation, and panning — set so the background voices sit at the correct apparent depth and position for the shot.','Walla perspective is where the crowd seems to sit in the space. Near voices are louder and clearer; far voices are softer and duller. It is matched to what the camera shows.','It places the crowd believably in the scene''s geography so background voices feel like they belong to the pictured space, near or far, on-screen or off.','The mixer pans, filters, and adds reverberation to walla so a group across the room sounds distant while nearby extras sit closer and brighter.','Walla',ARRAY['Walla','Walla density','Walla bed','Sound perspective','Room tone','Loop group']::text[],ARRAY['Placing all walla at the same close perspective so distant crowds sound unnaturally present.','Forgetting to re-EQ or add reverberation, so background voices sound dry and up front.','Panning walla in a way that contradicts where the crowd appears on screen.']::text[],ARRAY['Making a crowd on the far side of a hall sound appropriately distant.','Matching walla perspective to a cut from a wide shot to a close-up.','Placing off-screen voices in the surrounds while on-screen extras stay up front.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='23cf7e0c-4dc6-58bf-9ea3-e2c153a35505' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Walla perspective'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '23cf7e0c-4dc6-58bf-9ea3-e2c153a35505','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='23cf7e0c-4dc6-58bf-9ea3-e2c153a35505' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4d2f3c71-05e7-53d5-9c59-abed17efcd5e','Walla poke-through','An individual voice, word, or phrase that becomes distinctly audible above the indistinct walla blend, breaking the intended murmur; usually an unwanted intelligible standout, though occasionally a deliberately featured line.','A poke-through is a single voice or word that jumps out of the crowd murmur. It breaks the blurry blend and grabs the ear. Usually it is a mistake, but sometimes it is done on purpose.','Naming the problem helps editors catch stray intelligible words that pull focus from the principals, and lets them decide when a featured line should intentionally rise out of the crowd.','While reviewing walla, an editor mutes or lowers the layer causing a poke-through, or re-times it so no single word lands in a dialogue gap.','Walla',ARRAY['Walla','Vocabulary-safe walla','Walla bed','Walla density','Loop group','Featured walla']::text[],ARRAY['Not auditioning walla under quiet dialogue, where a poke-through is most exposed.','Leaving a recognizable word in the blend that distracts from or contradicts the scene.','Fixing a poke-through by pulling the whole crowd down instead of addressing the one offending layer.']::text[],ARRAY['A stray ''excuse me'' surfacing under a hushed dramatic beat.','Deliberately letting a vendor''s shout rise from a market crowd as a featured line.','Catching an intelligible word during a final mix quality check.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4d2f3c71-05e7-53d5-9c59-abed17efcd5e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Walla poke-through'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4d2f3c71-05e7-53d5-9c59-abed17efcd5e','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4d2f3c71-05e7-53d5-9c59-abed17efcd5e' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '51256ed3-ffee-56d1-95f2-2977e6834892','Walla sweetener','Additional walla layered into a scene to enhance or fill out an existing crowd or thin production track, adding presence, size, or specific reactions without replacing the original background entirely.','A walla sweetener is extra crowd sound added on top of what was already recorded. It fills out a thin or weak crowd. It makes the scene feel fuller without redoing everything.','It reinforces or supplements existing background so a scene gains fullness, energy, or a missing reaction while keeping any usable production crowd.','An editor adds a walla sweetener under a sparse restaurant recording to bring it up to the size the picture implies.','Walla',ARRAY['Walla','Walla bed','Walla density','Sweetener','Loop group','Production sound']::text[],ARRAY['Adding a sweetener whose room tone or perspective clashes with the production crowd underneath.','Piling on sweeteners until the added crowd overwhelms the original recording.','Using a sweetener with intelligible words that poke through the existing bed.']::text[],ARRAY['Fattening a thin party recording that did not capture enough extras.','Adding specific reactions to a real crowd that stayed too polite.','Bringing a distant, weak stadium recording up to full size.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='51256ed3-ffee-56d1-95f2-2977e6834892' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Walla sweetener'),'[^a-z0-9]','','g'));
