INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd25533a4-a468-5df5-8fc4-54b878416095','Wild ADR','Automated Dialogue Replacement lines recorded without the performer watching and matching picture in real time — delivered ''wild'' for tone, energy, or content — and later fitted to the scene by the dialogue editor rather than performed in sync.','Wild ADR means the actor records lines without matching the picture as they go. They just deliver the words freely. The editor then fits those lines to the scene afterward.','It frees the performer to focus on delivery and emotion when tight lip-sync is not required — for off-screen, distant, or new lines — speeding sessions and often improving the read.','For an off-camera or background line, the mixer records several wild reads, and the editor drops the best one into place without beep-driven sync.','Wild recording',ARRAY['Automated Dialogue Replacement (ADR)','Wild line','Wild pickup','Three-beep cue','Dialogue editing','Loop group']::text[],ARRAY['Recording wild ADR for an on-camera line that actually needs tight lip-sync.','Not logging which wild reads go with which cue, creating confusion in the edit.','Capturing wild lines at a mismatched level or mic so they will not cut against synced dialogue.']::text[],ARRAY['Recording off-screen crowd or radio dialogue that never shows a mouth.','Grabbing several free reads of a shouted line to be placed later.','Adding new story lines over the back of a head or a wide shot.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d25533a4-a468-5df5-8fc4-54b878416095' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wild ADR'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd25533a4-a468-5df5-8fc4-54b878416095','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d25533a4-a468-5df5-8fc4-54b878416095' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e80a663b-528f-5dc9-804d-db12c094fb0d','Wild line','A single line of dialogue recorded wild — without synchronization to picture — either on set after a take or in the studio, to be edited into the scene later; used to replace or supplement a line where sync recording was impractical or unusable.','A wild line is one line recorded without matching the picture. It might be grabbed on set right after filming, or later in a studio. The editor slots it into the scene afterward.','It captures a clean, usable reading of a specific line when the on-camera take was obscured, off-mic, or spoiled, without stopping to reset a full sync recording.','A production mixer records a wild line of an off-camera character right after the shot, while the actor''s voice and the location still match.','Wild recording',ARRAY['Wild ADR','Wild pickup','Wild track','Automated Dialogue Replacement (ADR)','Dialogue editing','Room tone']::text[],ARRAY['Recording a wild line long after the shoot, so the voice or room no longer matches the scene.','Failing to slate or log the wild line, leaving the editor to guess where it belongs.','Changing mic or distance for the wild line so it will not blend with the production track.']::text[],ARRAY['Grabbing an off-camera character''s line on location before moving on.','Re-recording a line spoiled by a passing truck without a full ADR session.','Capturing an alternate reading of a key line for the editor to choose from.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e80a663b-528f-5dc9-804d-db12c094fb0d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wild line'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e80a663b-528f-5dc9-804d-db12c094fb0d','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e80a663b-528f-5dc9-804d-db12c094fb0d' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a986684f-7032-53db-ae50-18d087ee997f','Wild pickup','An additional line or fragment recorded wild — out of sync, typically to ''pick up'' a missed, altered, or improved reading — captured on set or in the studio and dropped into the scene during editing.','A wild pickup is an extra bit of dialogue recorded out of sync. It picks up a line that was missed, changed, or needs to be better. The editor adds it to the scene later.','It lets production or post capture a needed line or correction quickly, without the full setup of a synchronized take, so the edit has the material it needs.','When a script tweak adds a word off-camera, the mixer records a wild pickup on the spot rather than scheduling a later ADR session.','Wild recording',ARRAY['Wild line','Wild ADR','Wild track','Automated Dialogue Replacement (ADR)','Dialogue editing','Pickup']::text[],ARRAY['Treating a wild pickup as final without checking it matches the scene''s voice and room.','Skipping a slate or note, so the pickup is hard to place in the edit.','Recording the pickup in a space whose tone clashes with the original location.']::text[],ARRAY['Grabbing a revised off-camera word after a last-minute script change.','Picking up a line the boom missed during a complex moving shot.','Capturing an extra reaction line to give the editor more coverage.']::text[],'f3b91616-66f6-414b-a35a-23a86671f275'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a986684f-7032-53db-ae50-18d087ee997f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wild pickup'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a986684f-7032-53db-ae50-18d087ee997f','f3b91616-66f6-414b-a35a-23a86671f275',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a986684f-7032-53db-ae50-18d087ee997f' AND gt.achievement_id='f3b91616-66f6-414b-a35a-23a86671f275');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3d5295cd-e77b-58a0-ac2f-3330b9e05c42','A/B dialogue checkerboarding','The practice of distributing consecutive dialogue segments across two or more alternating edit tracks (A, B, A, B...) so that adjacent shots, angles, or microphone perspectives never share a track, giving each its own space for room-tone fill, crossfades, and independent processing by the re-recording mixer.','Dialogue clips are placed on tracks that take turns, like A, B, A, B. This gives each shot its own lane. The mixer can then blend the cuts and set levels for each one.','It separates differing recordings so the mixer can smooth the joins with fills and crossfades and treat each perspective independently, keeping the edited dialogue seamless.','A dialogue editor splits a scene''s cut track onto alternating A/B tracks in Pro Tools, laying room tone under each so no hard background jump is heard at a picture cut.','Track layout',ARRAY['Ambience matching','Room tone','Fill','Boom lane','Acoustic discontinuity']::text[],ARRAY['Leaving two mismatched shots on the same track, so the mixer cannot smooth the join independently.','Splitting takes but forgetting to lay room-tone fill under the gaps, leaving audible holes at cuts.','Failing to keep boom and lav sources on separate tracks, which prevents per-source EQ and level moves.']::text[],ARRAY['Splitting a shot/reverse-shot conversation onto alternating tracks before the final mix.','Preparing a walk-and-talk with many angle changes so the mixer can smooth each cut.','Organizing a courtroom scene so wide and close coverage sit on separate tracks.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3d5295cd-e77b-58a0-ac2f-3330b9e05c42' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('A/B dialogue checkerboarding'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3d5295cd-e77b-58a0-ac2f-3330b9e05c42','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3d5295cd-e77b-58a0-ac2f-3330b9e05c42' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c02e1426-82d1-5b5b-b771-bb0c4e9af53b','Acoustic discontinuity','An audible mismatch in the acoustic character of dialogue across an edit—differences in room tone, reverberation, tonal balance, microphone perspective, or background level—that exposes the join between two recordings.','This is when two clips of speech sound like different rooms. The background, echo, or tone jumps at the cut. The edit stops sounding natural.','Naming this problem lets editors spot and fix breaks in sonic continuity so a scene feels like one continuous space and time.','Hearing a tonal jump between a wide shot and its close-up, the editor adds fill, EQ-matches the clips, or reaches for an alternate take to remove the discontinuity.','Continuity problem',ARRAY['Ambience matching','Room tone','Background perspective match','Fill','A/B dialogue checkerboarding']::text[],ARRAY['Assuming a hard cut in the background will pass unnoticed at the mix stage.','Fixing level but ignoring reverb and tonal differences, so the space still jumps at the edit.','Matching two clips by ear at a low monitor level, then finding the discontinuity obvious in the theatre.']::text[],ARRAY['A close-up cut into a wide shot where the reverb and background suddenly change.','Intercutting studio ADR with location production sound.','Joining two takes recorded hours apart as the room''s air handling changed.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c02e1426-82d1-5b5b-b771-bb0c4e9af53b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Acoustic discontinuity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c02e1426-82d1-5b5b-b771-bb0c4e9af53b','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c02e1426-82d1-5b5b-b771-bb0c4e9af53b' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '31e732de-f087-5c75-9e26-b0a04556dc37','Adaptive-threshold chasing','A noise-reduction approach in which the detection threshold continuously re-estimates and tracks a changing noise floor, so the processor follows fluctuating background noise across a take rather than relying on a single static noise profile.','Background noise can rise and fall during a take. Adaptive tools keep updating what counts as noise. The setting follows the change instead of staying fixed.','It handles recordings whose noise floor drifts—traffic, wind, or HVAC—so cleanup stays effective without teaching the tool a fresh noise profile for every section.','In iZotope RX, the editor uses the adaptive mode of Voice De-noise or Spectral De-noise on a location take where an air conditioner cycles, letting the threshold track the shifting hum.','Noise reduction',ARRAY['Ambience stripping','Room tone','Aspiration loss','Attenuate-versus-replace decision','Acoustic discontinuity']::text[],ARRAY['Pushing adaptive reduction too hard, which introduces musical-noise and watery artifacts.','Assuming an adaptive tool removes the need to work in short, similar-sounding sections.','Trusting the tracking blindly instead of checking that speech detail survived the process.']::text[],ARRAY['Cleaning a location interview where an air conditioner cycles on and off.','De-noising an exterior scene as passing traffic rises and falls.','Reducing wind rumble that gusts unevenly across a take.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='31e732de-f087-5c75-9e26-b0a04556dc37' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Adaptive-threshold chasing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '31e732de-f087-5c75-9e26-b0a04556dc37','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='31e732de-f087-5c75-9e26-b0a04556dc37' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '13731038-0759-52f2-9b8e-f896b523b67b','Alternate-channel mining','The practice of searching the other recorded channels of a production take—such as the boom, individual lavalier ISO tracks, or a mixdown—to find a cleaner, better-perspective, or less-damaged version of a line than the primary channel offers.','Each take is often recorded by several mics at once. Editors dig through those other tracks. They pick whichever channel sounds cleanest for each line.','Multitrack production sound provides redundant captures; mining them lets the editor rescue lines ruined by noise, overlap, or poor perspective on one microphone.','When a boom line is spoiled by a passing car, the editor pulls the same words from that actor''s isolated lav track instead of scheduling ADR.','Source selection',ARRAY['Alternate-take surgery','Boom lane','Boom-lav phase interaction','Attenuate-versus-replace decision','Ambience matching']::text[],ARRAY['Overlooking isolated lav or ISO tracks and scheduling costly ADR that was never needed.','Swapping to another channel without matching its different perspective and tone to neighbouring lines.','Combining the mined channel with the original without checking for phase interaction between the mics.']::text[],ARRAY['A boom line spoiled by a plane, where the same words are clean on the actor''s lav.','Two actors overlapping on the boom but isolated on separate lav ISO tracks.','A distorted mixdown track that forces the editor to rebuild from individual channels.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='13731038-0759-52f2-9b8e-f896b523b67b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Alternate-channel mining'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '13731038-0759-52f2-9b8e-f896b523b67b','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='13731038-0759-52f2-9b8e-f896b523b67b' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '631d29d2-37dd-596c-8193-91b9eb5e2bd1','Alternate-take surgery','The detailed cut-and-fit process of replacing a word, syllable, or phrase in the chosen take with the matching fragment from a different take, matching pitch, pace, level, and ambience so the substitution is inaudible.','Editors swap a bad word for the same word from another take. They match the pitch, timing, and background. Done well, no one can hear the join.','It fixes flubbed, noisy, or off-performance moments without ADR, keeping the original on-set delivery and lip sync.','To fix a word ruined by a cough, the editor drops the same word from take 4 into take 2, nudging its timing and adding fill so it blends.','Editing technique',ARRAY['Alternate-channel mining','Room tone','Attenuate-versus-replace decision','Ambience matching','A/B dialogue checkerboarding']::text[],ARRAY['Matching the words but not the room tone, so the inserted fragment jumps in background.','Ignoring pitch and intonation differences between takes, making the swap sound stitched.','Placing the replacement without checking lip sync against the picture.']::text[],ARRAY['Replacing a single mispronounced word using the matching word from another take.','Fixing a line where the actor coughed mid-sentence.','Smoothing a stumble by borrowing a clean syllable from a rehearsal take.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='631d29d2-37dd-596c-8193-91b9eb5e2bd1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Alternate-take surgery'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '631d29d2-37dd-596c-8193-91b9eb5e2bd1','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='631d29d2-37dd-596c-8193-91b9eb5e2bd1' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '856d849e-a6a2-5840-a01d-51655235aef1','Ambience matching','The technique of making the background ambience—room tone, air, and environmental sound—consistent across a dialogue edit by adding fill, level-matching, and EQ so that no change in the background bed is heard at cuts.','Every location has its own quiet background sound. Editors make that background even across all the cuts. The bed under the voices should never jump.','A steady ambience bed hides edits and makes separate recordings feel like one continuous space and take.','The editor lays a continuous room-tone fill beneath a checkerboarded scene so the background stays constant even where the on-mic recordings differ.','Continuity technique',ARRAY['Room tone','Fill','A/B dialogue checkerboarding','Acoustic discontinuity','Background perspective match']::text[],ARRAY['Using room tone borrowed from a different scene or location, so the character of the background is wrong.','Laying too little fill, which leaves silent holes where the edit shows through.','Looping a fill segment so short that its repeating pattern becomes audible.']::text[],ARRAY['Laying continuous room tone under a checkerboarded scene.','Matching the background of an ADR line to the surrounding production sound.','Evening out ambience where coverage was shot over several days.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='856d849e-a6a2-5840-a01d-51655235aef1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Ambience matching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '856d849e-a6a2-5840-a01d-51655235aef1','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='856d849e-a6a2-5840-a01d-51655235aef1' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7df619a8-b894-5553-b21b-32133b4425b6','Ambience stripping','The removal or strong reduction of background ambience and noise from a dialogue recording—via noise reduction, gating, or spectral editing—to isolate the voice, often so a uniform, controlled ambience can be rebuilt beneath it afterward.','This means taking the background sound off a voice clip. Tools cut the hiss, hum, or room noise. What is left is a cleaner, drier voice.','Stripping ambience gives the mixer a clean, consistent voice, so backgrounds can be rebuilt evenly instead of fighting mismatched noise baked into each clip.','Before rebuilding a scene''s ambience, the editor de-noises each line to strip its own background, then lays one matched room tone underneath.','Noise reduction',ARRAY['Adaptive-threshold chasing','Room tone','Ambience matching','Aspiration loss','Acoustic discontinuity']::text[],ARRAY['Over-stripping until the voice sounds thin, underwater, or full of watery artifacts.','Removing so much natural room that the dialogue sounds unnaturally dead and detached.','Stripping each clip by a different amount, so the cleaned lines no longer match one another.']::text[],ARRAY['De-noising each line before rebuilding a scene''s ambience from scratch.','Removing HVAC hum baked into a dialogue recording.','Isolating a voice from a noisy set so a controlled background can be added.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7df619a8-b894-5553-b21b-32133b4425b6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Ambience stripping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7df619a8-b894-5553-b21b-32133b4425b6','47e2b509-c540-4a23-839c-c7190b673899',true
