INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '36c3843e-b6f9-5a20-a0a0-7f155928ceac','Aspiration loss','The unwanted reduction or removal of the aspirated, breathy components of speech—breaths and the high-frequency turbulence of consonants such as /h/, /f/, /s/, and released stops—typically caused by aggressive noise reduction, gating, or de-essing, leaving dialogue sounding dull or unnatural.','Speech includes soft breaths and sharp hissy consonants. Heavy cleanup can strip these out. The voice then sounds dull, lispy, or robotic.','Recognizing aspiration loss warns editors that noise tools can eat real speech detail, so they balance cleanup against natural intelligibility.','After hard de-noising, the editor notices the ''s'' and ''f'' sounds have gone soft and the breaths have vanished, so they back off the reduction or restore high frequencies.','Processing artifact',ARRAY['Ambience stripping','Adaptive-threshold chasing','Attenuate-versus-replace decision','Room tone','Acoustic discontinuity']::text[],ARRAY['Pushing de-noise or de-essing so hard that consonant energy and clarity are removed with the noise.','Gating that clips off the actor''s breaths, making the delivery sound choppy and unnatural.','Judging cleanup only on a hum meter instead of listening for lost speech detail.']::text[],ARRAY['Noticing dull ''s'' and ''f'' sounds after heavy de-noising.','A gate cutting off an actor''s breaths and making delivery choppy.','Over-de-essing that removes natural consonant detail.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='36c3843e-b6f9-5a20-a0a0-7f155928ceac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Aspiration loss'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '36c3843e-b6f9-5a20-a0a0-7f155928ceac','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='36c3843e-b6f9-5a20-a0a0-7f155928ceac' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1a4a6dff-d569-53e6-a2e7-31c5de00b395','Attenuate-versus-replace decision','The editorial judgment of whether an unwanted sound overlapping dialogue can be adequately reduced by attenuation or spectral repair in place, or whether the affected dialogue must instead be replaced with a clean alternate take, alternate channel, or ADR.','A noise sometimes lands right on a spoken word. Editors decide: turn the noise down, or swap in a clean version? It depends on how tangled the noise and voice are.','It guides efficient cleanup—repairing when possible to keep the original take, replacing when the damage is too fused with the voice to fix cleanly.','Facing a door slam under a line, the editor first tries spectral attenuation; if the slam and word are too blended, they pull the line from an alternate take.','Editing decision',ARRAY['Alternate-take surgery','Alternate-channel mining','Ambience stripping','Aspiration loss','Room tone']::text[],ARRAY['Attenuating so hard that the voice itself is damaged, when a clean replacement was available.','Replacing a line when a quick spectral repair would have preserved better sync and performance.','Deciding by eye on the spectrogram alone instead of listening to whether the fix holds.']::text[],ARRAY['A door slam landing on a spoken word, weighing spectral repair against a take swap.','A chair squeak under a line that may or may not separate cleanly.','A phone buzz overlapping dialogue during a critical performance moment.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1a4a6dff-d569-53e6-a2e7-31c5de00b395' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Attenuate-versus-replace decision'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1a4a6dff-d569-53e6-a2e7-31c5de00b395','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1a4a6dff-d569-53e6-a2e7-31c5de00b395' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a62d7133-97ba-51da-b7d1-413ce936a9e1','Background perspective match','The technique of matching the perspective—apparent distance, level, and reverberant character—of background ambience across a dialogue edit and to the picture, so the sense of space stays consistent as shots change between wide and close framings.','Wide shots should sound farther away than close-ups. Editors keep the background''s sense of distance matched to the picture. It should not jump nearer or farther at a cut.','Consistent background perspective preserves the illusion of a single continuous space and supports the picture''s changing framing.','When a scene cuts from a wide shot to a close-up, the editor keeps the ambience bed''s perspective steady so the room does not seem to shrink or grow.','Continuity technique',ARRAY['Ambience matching','Boom perspective drift','Room tone','Acoustic discontinuity','A/B dialogue checkerboarding']::text[],ARRAY['Matching background level but ignoring reverb, so the sense of distance still jumps at the cut.','Forcing every shot to the same perspective and losing the natural close-versus-wide difference.','Judging perspective on small speakers, then finding the mismatch obvious in a large room.']::text[],ARRAY['Cutting from a wide establishing shot to a tight close-up in the same room.','Keeping a hallway''s ambience at a steady distance as the camera pushes in.','Matching off-screen background level to the on-screen framing.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a62d7133-97ba-51da-b7d1-413ce936a9e1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Background perspective match'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a62d7133-97ba-51da-b7d1-413ce936a9e1','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a62d7133-97ba-51da-b7d1-413ce936a9e1' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b212b118-66fd-5f76-9902-6798340d16ec','Boom lane','A dedicated edit track, or group of tracks, reserved for boom-microphone dialogue and kept separate from lavalier and other source lanes, so each microphone type can be edited, level-matched, and processed independently.','Editors keep boom-mic audio on its own tracks. Clip-on lavalier ("lav") mics go on separate tracks. This lane lets each mic be treated on its own.','Separating boom onto its own lane lets the mixer choose boom or lav per line and apply EQ and noise tools suited to that microphone without affecting the others.','When splitting a scene, the editor routes all boom clips to the boom lane and all lav clips to a lav lane so the mixer can A/B them.','Track layout',ARRAY['A/B dialogue checkerboarding','Boom-lav phase interaction','Alternate-channel mining','Boom perspective drift','Ambience matching']::text[],ARRAY['Mixing boom and lav clips on one track, which defeats per-source EQ, level, and noise processing.','Leaving lanes unlabelled, so the mixer cannot tell which source is which.','Summing boom and lav together without checking their phase interaction first.']::text[],ARRAY['Splitting a scene so all boom clips route to one track group and lavs to another.','Setting up tracks so the mixer can quickly A/B boom versus lav per line.','Applying boom-specific EQ without touching the lav tracks.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b212b118-66fd-5f76-9902-6798340d16ec' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Boom lane'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b212b118-66fd-5f76-9902-6798340d16ec','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b212b118-66fd-5f76-9902-6798340d16ec' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a17d1a30-b3b4-5ce5-91d5-509a330956b7','Boom perspective drift','A gradual change in the apparent distance and tonal character of boom-recorded dialogue within or across takes, caused by the boom operator''s varying mic-to-mouth distance or angle, producing an inconsistent perspective the editor must smooth.','A boom mic moves during filming. As it drifts nearer or farther, the voice changes tone and distance. Editors must even this out.','Identifying the drift lets the editor correct level and tone so a character''s voice keeps a steady perspective through the scene.','If a line starts close and ends distant because the boom pulled back, the editor rides level and EQ, or swaps to the lav, to hold the perspective.','Production sound artifact',ARRAY['Background perspective match','Boom lane','Boom-lav phase interaction','Alternate-channel mining','Acoustic discontinuity']::text[],ARRAY['Correcting the level but not the tone, so the voice still seems to move away.','Ignoring the drift entirely, leaving the character''s voice wandering in space.','Riding level so aggressively that the dialogue''s natural dynamics are flattened.']::text[],ARRAY['A line that starts close and ends distant because the boom pulled back.','A long take where the operator repositioned the boom between actors.','Tone shifting as the boom angled off-axis to avoid a shadow.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a17d1a30-b3b4-5ce5-91d5-509a330956b7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Boom perspective drift'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a17d1a30-b3b4-5ce5-91d5-509a330956b7','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a17d1a30-b3b4-5ce5-91d5-509a330956b7' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd2066f46-5192-5962-af02-8d854f9f9a8b','Boom shadowing','A production-sound and camera problem in which the boom microphone or its pole casts a visible shadow into the filmed frame, spoiling the shot visually even when the recorded dialogue is good; in post it often means the best-sounding take is one the picture cannot use.','Sometimes the boom mic throws a shadow into the shot. That ruins the picture, not the sound. The good audio may sit on a take the film cannot show.','Awareness of boom shadowing explains why a strong-sounding take may be dropped from picture, prompting editors to mine its audio for another angle.','A dialogue editor may lift clean audio from a boom-shadowed take and lay it under a usable camera angle whose own sound was weaker.','Production sound artifact',ARRAY['Boom lane','Alternate-channel mining','Boom perspective drift','Alternate-take surgery','Boom-lav phase interaction']::text[],ARRAY['Assuming a shadowed take''s audio is unusable and discarding the good sound along with the bad picture.','Failing to log which takes were shadowed, so clean audio is never mined later.','Blaming the sound department for a fault that is a lighting and framing issue on set.']::text[],ARRAY['A strong take dropped from picture because the boom''s shadow crossed a wall.','Mining clean audio from a shadowed take to lay under a usable angle.','A wide shot where the boom had to stay high, risking both shadow and thinner sound.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d2066f46-5192-5962-af02-8d854f9f9a8b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Boom shadowing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd2066f46-5192-5962-af02-8d854f9f9a8b','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d2066f46-5192-5962-af02-8d854f9f9a8b' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6f36163a-e223-5920-a3c2-a06138fe4d97','Boom-lav phase interaction','The constructive and destructive interference that occurs when a boom and a lavalier capture the same voice at slightly different distances and are summed, producing time and phase offsets that cause comb filtering, hollowness, or level changes unless the signals are time-aligned or polarity-corrected.','A voice reaches the boom and the lav at slightly different times. Mixing both can make the sound thin or hollow. This is comb filtering, and editors must line the mics up.','Understanding this interaction lets editors and mixers time-align the mics or choose one alone, avoiding the hollow, filtered sound of poorly summed sources.','When blending boom and lav on a line, the editor nudges one clip in time, or uses an alignment tool, to remove comb-filter coloration before the mix.','Microphone phase',ARRAY['Boom lane','Alternate-channel mining','Boom perspective drift','A/B dialogue checkerboarding','Ambience matching']::text[],ARRAY['Summing boom and lav without time-aligning them, which produces audible comb filtering.','Flipping polarity as an automatic fix without listening to whether it actually helps.','Assuming two mics on the same voice always add cleanly, ignoring their distance difference.']::text[],ARRAY['Blending boom and lav on the same line and hearing a hollow, filtered tone.','Time-aligning a lav to the boom before summing them in the mix.','Deciding to use one microphone alone to avoid comb filtering.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6f36163a-e223-5920-a3c2-a06138fe4d97' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Boom-lav phase interaction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6f36163a-e223-5920-a3c2-a06138fe4d97','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6f36163a-e223-5920-a3c2-a06138fe4d97' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dc738e0f-e7e4-5e17-ba59-a22662b7b834','Breath attenuation','The reduction in level of a speaker''s audible inhalation or exhalation within a dialogue track, achieved with clip gain, fades, volume automation, or a dedicated breath-suppression process, so the breath remains natural but no longer distracts.','A breath is the sound of someone breathing in or out while talking. Breath attenuation just means turning that breath sound down. You make it quieter so it does not distract, but you keep it so the speech still sounds natural.','Keeps breaths from jumping out over dialogue or clashing with music and effects while preserving the natural rhythm of speech; it exists because fully removing breaths sounds unnatural.','A dialogue editor lowers a loud gasp before a line using clip gain or a breath tool, setting a target level rather than deleting the breath entirely.','Breath Editing',ARRAY['Breath shaping','Breath replacement','Breath-hole repair','Room tone','Clip gain']::text[],ARRAY['Deleting breaths entirely instead of attenuating them, which makes speech sound robotic and unnatural','Attenuating every breath by the same fixed amount, ignoring that some breaths carry emotion or performance','Cutting so hard into the breath that the following word loses its natural onset']::text[],ARRAY['A close lavalier picks up heavy breathing before an emotional line that must be tamed under music','An audiobook or voiceover has distracting breaths between sentences','A shouted action line where the inhale is louder than the dialogue itself']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dc738e0f-e7e4-5e17-ba59-a22662b7b834' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Breath attenuation'),'[^a-z0-9]','','g'));
