INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8b3bf360-fdb7-59f6-bc34-99341ca1830c','Breath graft','A dialogue-editing repair in which a breath taken from another take, line, or moment is inserted (grafted) into a spot where the original breath is missing, damaged, or mismatched, restoring a natural inhale or exhale at an edit point.','Sometimes an edit leaves a breath that is missing or sounds wrong. A breath graft fixes this. You copy a good breath from somewhere else in the recording and drop it in. It is like patching a photo with a matching piece from another picture.','Restores the natural breathing pattern that edits or noise can destroy, so a cut sounds like one continuous performance rather than spliced pieces.','When joining two takes leaves an abrupt, breathless jump, the editor pulls a similar breath from a nearby handle and crossfades it in to smooth the transition.','Breath Editing',ARRAY['Breath replacement','Breath matching','Breath-hole repair','Room tone','Crossfade']::text[],ARRAY['Grafting a breath from a take with different room tone or a different mic, so the patch stands out','Using a breath whose pitch or effort does not match the surrounding performance','Forgetting to crossfade the graft, leaving an audible click or level jump']::text[],ARRAY['Two dialogue takes are joined and the join sounds breathless and abrupt','A cough or noise ruined the original breath before a key line','Building a smooth performance from several partial takes in ADR or looping']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8b3bf360-fdb7-59f6-bc34-99341ca1830c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Breath graft'),'[^a-z0-9]','','g'));
