INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9f8db348-3e17-58ac-a3f4-9a29ae00a569','Breath matching','The practice of making the breaths around and within a dialogue edit consistent in level, tone, length, and character so that inhales and exhales flow naturally across cut points and between joined takes.','When you cut dialogue together, the breaths on each side can sound different. Breath matching means making them sound alike. You adjust their loudness, length, and tone so they blend. Then the join sounds like one smooth performance.','Preserves the illusion of a single continuous take by preventing mismatched breaths from revealing where edits were made.','After assembling a scene from multiple takes, the editor compares breaths on either side of each cut and adjusts gain or swaps breaths until they agree.','Breath Editing',ARRAY['Breath graft','Breath replacement','Breath shaping','Room tone','Crossfade']::text[],ARRAY['Matching the words but ignoring the breaths, so the edit is exposed by a jarring breath','Assuming all breaths are interchangeable regardless of effort or emotion','Over-processing a breath until it no longer matches the natural voice']::text[],ARRAY['Cutting between a wide-shot boom take and a close lavalier take of the same line','Assembling a monologue from several performances','Smoothing an edit where a line was shortened mid-sentence']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9f8db348-3e17-58ac-a3f4-9a29ae00a569' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Breath matching'),'[^a-z0-9]','','g'));
