INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6e803e42-68be-5e3d-b6d3-c08ef20ff95f','Breath replacement','The substitution of an unusable breath, one that is too loud, noisy, clipped, or corrupted by a sound effect or edit, with a cleaner breath sourced from elsewhere in the recording, so the dialogue keeps a believable breathing pattern.','A breath in a recording can be ruined by noise or a bad edit. Breath replacement swaps it out. You take a clean breath from another part of the recording and use it instead. The speech then sounds normal again.','Keeps dialogue sounding human when the original breath cannot be saved, avoiding the unnatural silence that deleting it would leave.','When a door slam lands on top of an actor''s inhale, the editor removes the damaged breath and drops in a matching clean one from a handle.','Breath Editing',ARRAY['Breath graft','Breath matching','Breath-hole repair','Breath attenuation','Room tone']::text[],ARRAY['Replacing a breath with one recorded at a different distance or on a different mic','Choosing a replacement that is the wrong length for the gap','Leaving a hard edit at the seam instead of crossfading the new breath in']::text[],ARRAY['A sound effect or off-mic noise overlaps the original breath','A breath was accidentally clipped when trimming a line','A distorted or overloaded breath needs a clean substitute']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6e803e42-68be-5e3d-b6d3-c08ef20ff95f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Breath replacement'),'[^a-z0-9]','','g'));
