INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd6fd4b90-9edd-5233-a0d2-590051a50974','Breath shaping','The controlled adjustment of a breath''s dynamic envelope, its attack, level, and decay, using fades and volume automation so the breath sits at the desired loudness and contour rather than being removed outright.','Breath shaping means changing how a breath rises and falls in volume. You use fades and volume moves to soften its start or trim its tail. Instead of deleting the breath, you gently mold it so it fits the line.','Lets an editor tuck breaths under dialogue or music while keeping them natural, giving finer control than a simple cut or a fixed volume drop.','Using volume automation, the editor draws a small fade on the front of a gasp and a longer fade on its tail so it eases into the first word.','Breath Editing',ARRAY['Breath attenuation','Breath matching','Clip gain','Crossfade','Volume automation']::text[],ARRAY['Shaping breaths so aggressively that the following word''s onset is clipped','Applying identical fades to every breath instead of shaping each to its context','Confusing shaping, which contours the breath, with removing it entirely']::text[],ARRAY['Softening a sharp intake of breath before a whispered line','Blending a breath into the start of a musical cue','Smoothing the tail of an exhale so it decays into room tone']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d6fd4b90-9edd-5233-a0d2-590051a50974' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Breath shaping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
