INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '55bbbfac-62e3-55b1-809f-48d67409f3fa','Breath-hole repair','The filling of the gap left when a breath or sound is cut from a dialogue track, using matching room tone or ambient fill so the removal does not create an audible drop to digital silence or a change in background texture.','When you cut a breath out of dialogue, it can leave a silent hole. That hole makes the background suddenly disappear, which is easy to notice. Breath-hole repair fills the gap with matching room sound. The background then stays smooth and even.','Prevents cuts from creating dead spots or texture changes in the background, keeping the ambient bed continuous under the dialogue.','After deleting a noisy breath, the editor pastes matching room tone into the gap and crossfades the edges so the background never drops out.','Breath Editing',ARRAY['Room tone','Breath attenuation','Breath replacement','Crossfade','Ambient fill']::text[],ARRAY['Leaving the gap as digital silence, so the background audibly drops out at the cut','Filling with room tone from a different location or mic that does not match','Forgetting to crossfade the fill, creating clicks at the seams']::text[],ARRAY['A loud breath is removed from between two lines and must not leave silence','Trimming a noise out of a pause during a quiet scene','Cleaning production dialogue where every gap must hold matching ambience']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='55bbbfac-62e3-55b1-809f-48d67409f3fa' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Breath-hole repair'),'[^a-z0-9]','','g'));
