INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e608fc09-bcb9-5507-b960-8ecb2baa24d8','Broadband rustle','Noise spread across a wide range of frequencies caused by clothing moving against a concealed lavalier microphone or its cable, ranging from high-frequency brushing to low-frequency thuds, that contaminates the dialogue signal.','Broadband rustle is the scratchy, brushing sound clothing makes against a hidden clip-on mic. Broadband means it covers many pitches at once, from high swishes to low thumps. It happens when fabric moves over the little microphone as someone shifts.','Naming rustle as broadband explains why it resists simple EQ, which spans the same frequencies as speech, and why editors reach for spectral repair or a clean alternate microphone.','The editor spots broadband rustle under a lavalier line and either switches to the boom take or applies a spectral de-rustle process to separate it from speech.','Production Sound Noise',ARRAY['Chest rub','Cable rub','Concealment muffling','Capsule scrape','De-rustle']::text[],ARRAY['Trying to fix broadband rustle with EQ alone, which also dulls the voice because the noise spans the same frequencies','Assuming rustle can always be removed, when a clean boom take would be the better source','Pushing noise reduction so hard that the dialogue becomes watery or full of artifacts']::text[],ARRAY['A lavalier under a stiff jacket rustles every time the actor gestures','A body-mic track needs cleanup before it can be used over a wide shot','Choosing between a rustly lav and a clean boom for the same line']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e608fc09-bcb9-5507-b960-8ecb2baa24d8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Broadband rustle'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e608fc09-bcb9-5507-b960-8ecb2baa24d8','47e2b509-c540-4a23-839c-c7190b673899',true
