INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c203318c-aa35-5e99-a2e0-dcb125c26a3b','Button knock','A transient thump or tap in a dialogue recording produced when a garment button, snap, or fastener strikes or presses against a concealed lavalier microphone or its capsule as the performer moves.','A button knock is a small thump on the recording. It happens when a shirt button bumps the hidden mic as the actor moves. The button taps the tiny microphone and you hear a knock in the speech.','Naming this specific transient helps a mixer trace an intermittent thump to a costume fastener and fix it at the source by remounting the mic away from buttons.','On set, the sound mixer moves the lavalier above or to the side of the shirt buttons and secures a cable loop so buttons can no longer strike the capsule.','Production Sound Noise',ARRAY['Cable knock','Capsule scrape','Chest rub','Broadband rustle','Concealment muffling']::text[],ARRAY['Mounting the lavalier directly behind a row of buttons, inviting knocks with every movement','Assuming the thump is an electrical fault rather than a mechanical contact noise','Trying to edit out each knock in post instead of preventing it at the mounting stage']::text[],ARRAY['An actor in a button-down shirt taps the hidden mic whenever they move','Intermittent thumps appear only during physical action','A wardrobe change places a button right over the mic position']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c203318c-aa35-5e99-a2e0-dcb125c26a3b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Button knock'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c203318c-aa35-5e99-a2e0-dcb125c26a3b','47e2b509-c540-4a23-839c-c7190b673899',true
