INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4cf2f445-8761-5477-94ad-baca3c740c68','Cable knock','A transient noise caused when a lavalier microphone''s cable is bumped, tapped, or strikes a surface, transmitting the mechanical impact up the cable to the capsule as an audible thump; a form of cable-borne microphonic noise.','A cable knock is a thump caused by the mic''s wire getting bumped. The knock travels up the cable into the tiny microphone. You then hear a thud in the recording. It is different from someone tapping the mic itself.','Distinguishing cable-borne knocks from capsule contact tells the mixer to isolate the cable, with a strain-relief loop and tape, rather than adjusting the capsule.','The mixer forms a small loop in the cable just below the capsule and tapes it down so movement and impacts no longer travel to the microphone.','Production Sound Noise',ARRAY['Cable rub','Button knock','Capsule scrape','Broadband rustle','Concealment muffling']::text[],ARRAY['Skipping the strain-relief loop below the capsule, letting cable movement reach the mic','Pulling the cable taut instead of leaving slack, so every tug becomes a knock','Blaming the microphone when the noise is actually cable microphonics']::text[],ARRAY['A concealed cable slaps against a prop or belt during a move','The talent''s transmitter pack tugs the mic cable between setups','A boom or lav cable knocks a stand or wall during a take']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4cf2f445-8761-5477-94ad-baca3c740c68' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cable knock'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4cf2f445-8761-5477-94ad-baca3c740c68','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4cf2f445-8761-5477-94ad-baca3c740c68' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7c8fbe74-7989-5cca-8e3a-60112603525c','Cable rub','A continuous friction noise generated when a lavalier microphone''s cable rubs against clothing, skin, or itself during movement, coupling into the capsule as broadband scratching or swishing; a form of cable microphonics.','Cable rub is a scratchy, swishing sound. It comes from the mic''s wire rubbing on clothing or skin as someone moves. The rubbing travels up the cable to the microphone. You then hear it mixed into the speech.','Identifying the noise as cable-borne rubbing points to the fix, a broadcast loop and taping the cable, instead of treating it as room or clothing noise.','The mixer dresses the cable in a broadcast loop through the clip and tapes it to the body so it cannot rub against fabric during the scene.','Production Sound Noise',ARRAY['Cable knock','Chest rub','Broadband rustle','Concealment muffling','Capsule scrape']::text[],ARRAY['Leaving the cable loose so it drags across clothing with every movement','Confusing cable rub with clothing rustle and treating the wrong source','Routing the cable over rough or synthetic fabric that maximizes friction']::text[],ARRAY['A lavalier cable runs under a shirt and rubs with each step','A performer''s rapid movement produces swishing on the body-mic track','Wardrobe made of synthetic fabric increases cable friction noise']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7c8fbe74-7989-5cca-8e3a-60112603525c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cable rub'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7c8fbe74-7989-5cca-8e3a-60112603525c','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7c8fbe74-7989-5cca-8e3a-60112603525c' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e4c57015-875f-50dd-9553-bc599062c64b','Capsule scrape','Noise produced when clothing, fabric, jewelry, or a foreign object drags directly across the capsule or grille of a concealed lavalier microphone, generating sharp scraping or scratching transients in the dialogue.','A capsule scrape is a harsh scratching sound. It happens when fabric or an object drags right across the face of the hidden mic. The mic''s little opening picks it up loudly. It sounds much worse than gentle rustle.','Flagging contact directly at the capsule tells the mixer to shield and immobilize the mic head, with a mount or moleskin, so nothing touches the sensitive front of the microphone.','The mixer places the lavalier in a mount or wraps it so clothing is held away from the capsule, preventing anything from dragging across the grille.','Production Sound Noise',ARRAY['Chest rub','Cable rub','Broadband rustle','Concealment muffling','Button knock']::text[],ARRAY['Mounting the capsule so fabric can slide directly over its grille','Leaving jewelry or a necktie free to swing against the mic head','Assuming post can remove a scrape that overloads the capsule at the source']::text[],ARRAY['A necklace or zipper drags across a hidden chest mic','Loose clothing slides over the capsule during movement','A poorly mounted lav lets a collar scrape the grille']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e4c57015-875f-50dd-9553-bc599062c64b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Capsule scrape'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e4c57015-875f-50dd-9553-bc599062c64b','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e4c57015-875f-50dd-9553-bc599062c64b' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '13653263-d66e-57c4-b802-0e91a2df98b0','Character splitting','The dialogue-editing practice of placing each character''s lines on their own dedicated track or track group across a scene or reel, rather than organizing by microphone alone, so that levels, EQ, and processing can be set consistently per character in the premix.','Character splitting means giving each character their own audio track. All of one actor''s lines go on one track through the scene. This lets the mixer set that voice once and keep it steady. It also makes swapping in re-recorded lines easier.','Gives the re-recording mixer consistent, per-character control so each voice can be balanced and processed as a unit, and keeps ADR aligned with the right character throughout.','The dialogue editor routes one actor to tracks 1 and 2 and another actor to tracks 3 and 4 for the whole reel, so the mixer dials in each character''s sound just once.','Track Organization',ARRAY['Checkerboarding','Premix','ADR','Room tone','Split edit']::text[],ARRAY['Confusing character splitting with checkerboarding by microphone, which groups takes differently','Letting the same character drift across many tracks, forcing the mixer to reset settings repeatedly','Splitting characters but ignoring room tone, so gaps between lines do not match']::text[],ARRAY['An ADR-heavy scene where each actor''s replacement lines must track consistently','Preparing a reel so the re-recording mixer can process each voice separately','A dialogue-heavy two-hander that needs steady, per-character levels']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='13653263-d66e-57c4-b802-0e91a2df98b0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Character splitting'),'[^a-z0-9]','','g'));
