WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='13653263-d66e-57c4-b802-0e91a2df98b0' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1a8a54f9-b220-57f8-8a76-5ddfd59cf8b4','Chest rub','Low- to mid-frequency rumble and friction noise caused by clothing rubbing against a lavalier microphone mounted on the chest, or by the chest wall and fabric moving over the capsule as the performer breathes and moves.','Chest rub is a dull, rubbing noise from a mic clipped on the chest. Clothing and the chest move against the hidden mic as the actor breathes or shifts. This rubbing gets recorded along with the voice.','Naming chest-area friction guides the mixer to immobilize the fabric around a chest-mounted lav and choose quieter placement or materials.','The mixer anchors the clothing around the mic with tape triangles and adds a cable loop so the chest and fabric cannot rub the capsule during the take.','Production Sound Noise',ARRAY['Cable rub','Broadband rustle','Concealment muffling','Capsule scrape','Button knock']::text[],ARRAY['Mounting the lav where the chest and clothing flex most, maximizing rub','Using stiff or synthetic wardrobe that rubs loudly against the mic','Not immobilizing the fabric, so every breath produces friction noise']::text[],ARRAY['A chest-mounted lav rumbles as the actor breathes heavily','Stiff costume fabric rubs the hidden mic during a dialogue scene','An actor''s movement flexes the chest against a concealed capsule']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1a8a54f9-b220-57f8-8a76-5ddfd59cf8b4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Chest rub'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
