INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f12c610a-469f-582a-b118-4c0ac973fb31','Concealment muffling','The loss of high-frequency detail and presence in a lavalier''s sound caused by concealing the microphone under clothing, where fabric layers acoustically absorb and attenuate high frequencies, producing a dull, muffled voice.','Concealment muffling is when a hidden mic sounds dull. Hiding the mic under clothing blocks the high notes of the voice. The fabric soaks up those high sounds. So the recording loses its crispness and sounds muffled.','Recognizing that concealment rolls off highs explains why editors add high-frequency lift and why sound teams use high-boost mounts and grid caps to restore clarity.','To counter muffling from a chest-hidden lav, a mixer fits a high-boost grid cap or the editor adds a gentle high-frequency EQ lift to recover presence.','Production Sound Noise',ARRAY['Broadband rustle','Chest rub','Cable rub','Capsule scrape','Equalization']::text[],ARRAY['Burying the lav under thick fabric layers and expecting a bright, natural sound','Trying to fix heavy muffling with extreme EQ boost, which also lifts noise and rustle','Ignoring placement and relying only on post to restore lost high frequencies']::text[],ARRAY['A lav hidden under a heavy coat sounds dull and closed-in','Matching a muffled concealed-mic take to a bright boom take','A costume change forces the mic deeper under fabric, reducing clarity']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f12c610a-469f-582a-b118-4c0ac973fb31' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Concealment muffling'),'[^a-z0-9]','','g'));
