INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2ae4e36b-dc3b-504c-963a-1a79ffc7a48d','Consonant erosion','The progressive loss of high-frequency detail and transient energy in consonant sounds (such as s, t, f, and k) within recorded dialogue, typically caused by aggressive noise reduction, de-essing, de-reverb, or codec compression that removes the spectral content those consonants depend on for intelligibility.','Consonants are the sharp sounds like "s" and "t" that make words clear. Heavy noise cleanup can wear them away. Then speech sounds dull and hard to follow.','Naming this failure mode reminds editors that restoration processing has a cost; consonants carry much of speech intelligibility, so protecting them sets how far cleanup can safely go.','A dialogue editor watches for consonant erosion when dialling in a denoiser or de-esser, easing off the strength once the "s" and "t" sounds start to soften.','Dialogue Repair',ARRAY['Denoise modulation','De-plosive overreach','Dialogue declicking','Dialogue-isolation residue','Sibilance']::text[],ARRAY['Pushing a denoiser to remove all hiss without noticing the consonants have gone soft and muffled','Assuming heavier de-essing is always cleaner, when it can strip the sharp edges words need','Judging cleanup only on quiet gaps instead of checking that spoken words stay crisp']::text[],ARRAY['Cleaning a noisy location recording where strong denoise settings begin to blur sibilants','Restoring an archival interview and finding aggressive processing has dulled the speech','Preparing dialogue for a codec-limited broadcast where high frequencies are already reduced']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2ae4e36b-dc3b-504c-963a-1a79ffc7a48d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Consonant erosion'),'[^a-z0-9]','','g'));
