INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '196bc501-21b2-5537-9fab-69d7d59b599d','Consonant graft','A dialogue editing technique in which a clear consonant, or consonant cluster, from an alternate take or nearby word is spliced onto a word whose own consonant is damaged, masked, or missing, restoring intelligibility while preserving the performance of the original vowel and rhythm.','Sometimes a word loses its ending sound, like a dropped "t". An editor can borrow that sound from another take. They join it on so the word sounds whole again.','It lets an editor rescue an otherwise strong performance line when a single consonant is lost to noise, an overlap, or a mic problem, avoiding a full ADR replacement.','The editor finds a matching consonant in an alternate take, trims it tightly, and crossfades it onto the flawed word, matching level, pitch, and room tone so the join is inaudible.','Editing Technique',ARRAY['Dialogue assembly','Dialogue fill','Consonant erosion','Dialogue declicking','ADR']::text[],ARRAY['Grafting a consonant from a take with different room tone, so the splice jumps out','Not matching pitch or pace, which makes the repaired word sound unnatural','Using a hard cut instead of a crossfade, which creates an audible click at the join']::text[],ARRAY['A key line has its final "t" buried under a door slam, and an alt take supplies a clean one','An actor''s plosive was clipped by the recorder, so a consonant is borrowed to rebuild the word','Overlapping dialogue masks one word''s start, so it is rebuilt using a consonant from a wild line']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='196bc501-21b2-5537-9fab-69d7d59b599d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Consonant graft'),'[^a-z0-9]','','g'));
