INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8be03f29-9fd5-5397-9b7f-8c21ec1044dc','DX','The standard abbreviation for dialogue in film and television post-production, referring to the spoken-word element of a soundtrack; DX tracks and stems carry sync production dialogue, ADR, and narration, kept separate from music and effects for editing and mixing.','"DX" is just shorthand for dialogue, the talking in a film. Sound teams keep the talking on its own tracks. That makes it easy to edit and mix apart from music and effects.','Labelling dialogue as DX gives every department a shared, unambiguous tag so the spoken element can be routed, split, and mixed as its own stem.','An editor names tracks and stems "DX" so the re-recording mixer instantly knows which material is dialogue when balancing it against music and effects.','Track Organization',ARRAY['DX A / DX B','Dialogue-tainted PFX','Dialogue tracklay','Dialogue assembly','ADR']::text[],ARRAY['Confusing DX (dialogue) with FX (effects) or MX (music) when labelling tracks','Placing production effects on DX tracks, which contaminates the dialogue stem','Assuming DX means only on-set dialogue, forgetting it also covers ADR and narration']::text[],ARRAY['Organizing a Pro Tools session into DX, FX, and MX track groups before editing','Delivering split stems where the DX stem must stand alone for foreign-language dubbing','A mixer solos the DX stem to check dialogue level against the music']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8be03f29-9fd5-5397-9b7f-8c21ec1044dc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('DX'),'[^a-z0-9]','','g'));
