INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1a8ea109-da3d-5d14-80e6-931a7925f309','DX A / DX B','A convention for splitting edited dialogue across two or more alternating tracks (A, B, and so on) so that adjacent lines, angles, or characters sit on separate tracks; this checkerboarding lets the mixer apply independent EQ, level, and noise processing and crossfade between differing backgrounds.','Editors spread dialogue across tracks named A, B, and so on. Lines that sound different go on different tracks. This lets the mixer treat each one on its own and blend between them.','Separating dialogue onto A/B tracks by perspective or tone gives the mixer room to match mismatched shots and to fade between different room sounds without abrupt jumps.','When two camera angles of a scene sound different, the editor places one angle''s lines on DX A and the other''s on DX B, filling gaps with matching room tone so the mixer can smooth the transition.','Track Organization',ARRAY['DX','Dialogue fill','Dialogue tracklay','Dialogue assembly','Dialogue conform']::text[],ARRAY['Leaving mismatched-sounding lines on one track, forcing a single EQ setting on all of them','Not filling the gaps on A and B tracks with room tone, so backgrounds drop out at cuts','Splitting randomly instead of by sound character, which gives the mixer no useful grouping']::text[],ARRAY['Checkerboarding a dialogue scene shot with two mics that have different tone','Separating each character''s coverage so a mixer can ride levels independently','Alternating wide and close angles onto A and B tracks to smooth the perspective cut']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1a8ea109-da3d-5d14-80e6-931a7925f309' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('DX A / DX B'),'[^a-z0-9]','','g'));
