SELECT '1a8ea109-da3d-5d14-80e6-931a7925f309','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1a8ea109-da3d-5d14-80e6-931a7925f309' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '19379bd7-db86-539f-b3e8-2b1ccf3465e0','De-plosive overreach','The over-application of de-plosive (plosive reduction) processing, in which reducing the low-frequency energy of p and b bursts is pushed so far that it also removes legitimate low-end from the voice or dulls the plosive consonant itself, thinning the dialogue and weakening intelligibility.','A "plosive" is the pop from sounds like "p" and "b". Tools can soften those pops. Push a tool too hard and it also strips real bass and body from the voice.','Naming this over-processing failure warns editors that plosive repair should target only the pop, since the same low frequencies also give the voice weight and the consonant its punch.','An editor uses a de-plosive tool or a targeted high-pass only on the affected syllable, checking that the voice keeps natural body rather than blanket-filtering every plosive.','Dialogue Repair',ARRAY['Consonant erosion','Dialogue declicking','Denoise modulation','Dialogue-isolation residue','DX']::text[],ARRAY['Applying a static high-pass filter to the whole track to kill plosives, thinning every word','Over-reducing the plosive until the "p" and "b" sounds lose their punch','Treating mic bumps and plosives with the maximum setting instead of the least amount needed']::text[],ARRAY['A close-miced monologue has heavy plosives that tempt an editor to over-filter','Voiceover recorded without a pop shield needs plosive repair without losing warmth','Cleaning a lav-mic performance where p-pops overlap with wanted low-end']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='19379bd7-db86-539f-b3e8-2b1ccf3465e0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('De-plosive overreach'),'[^a-z0-9]','','g'));
