SELECT '19379bd7-db86-539f-b3e8-2b1ccf3465e0','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='19379bd7-db86-539f-b3e8-2b1ccf3465e0' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '94088221-e8d5-51cf-b9f9-9dfac8809f77','Denoise modulation','An artifact of adaptive or spectral noise reduction in which the residual background noise rises and falls in step with the dialogue, because the processor treats noise during speech differently than in the gaps; the audible result is a pumping or breathing noise floor rather than a steady one.','Noise cleanup should leave a steady, quiet background. Pushed too hard, the leftover hiss swells up and down as someone talks. It sounds like the background is breathing.','Recognizing this artifact tells the editor the denoiser is working too aggressively, so the goal shifts to a consistent, natural noise floor instead of maximum noise removal.','The editor eases off the reduction amount or adjusts the noise profile until the background stays even under speech, sometimes leaving a little more noise to keep it steady.','Dialogue Repair',ARRAY['Consonant erosion','Dialogue-isolation residue','Dialogue fill','De-plosive overreach','Dialogue declicking']::text[],ARRAY['Chasing total silence in the gaps, which makes the noise pump up whenever dialogue plays','Using one aggressive noise profile across scenes with changing backgrounds','Judging the denoise only in solo, missing the pumping that shows up under the full mix']::text[],ARRAY['Denoising an air-conditioned interior where the noise floor starts breathing with the lines','Cleaning traffic rumble from an exterior and hearing the residue surge under speech','Matching a heavily denoised close-up to a lighter-treated wide shot']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='94088221-e8d5-51cf-b9f9-9dfac8809f77' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Denoise modulation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '94088221-e8d5-51cf-b9f9-9dfac8809f77','47e2b509-c540-4a23-839c-c7190b673899',true
