INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '97f929b8-2089-53bb-bb5d-9de7b4fe232f','Denture click','A mouth-noise transient in recorded dialogue produced by an actor''s dentures or dental work, heard as a small click or clack, especially on plosives and mouth movements; it is a subset of the saliva and lip clicks addressed by mouth-declick restoration tools.','Some actors'' false teeth make tiny clicking sounds while they speak. A close mic picks these up. Editors remove them so the clicks don''t distract from the words.','Identifying denture clicks as a distinct mouth noise helps the editor target and remove them without harming the surrounding speech.','The editor uses a mouth-declick tool or hand-edits the individual click, replacing it with matching room tone so the repair is inaudible.','Dialogue Repair',ARRAY['Dialogue declicking','Consonant erosion','Dialogue fill','Denoise modulation','DX']::text[],ARRAY['Confusing a denture click with a digital click and reaching for the wrong tool','Over-processing a whole line to remove one click, dulling the speech around it','Missing clicks that only stand out loud in a quiet, close-miked scene']::text[],ARRAY['A quiet, intimate close-up where an older actor''s dentures click on every "t"','An audiobook or voiceover session with audible mouth clicks between words','Restoring dialogue for a drama where denture clicks sit on top of soft lines']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='97f929b8-2089-53bb-bb5d-9de7b4fe232f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Denture click'),'[^a-z0-9]','','g'));
