INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '73ee18f8-8f96-55a8-8737-d1bfffbc2931','Dialogue assembly','The stage of dialogue editing in which the editor gathers and lays out all needed dialogue material (sync production takes, alternates, wild lines, and ADR) onto organized tracks in sync with picture, building the foundation before detailed cleanup and smoothing; the term is often used interchangeably with conforming when original recordings replace the picture editor''s guide track.','Assembly is the first big step of dialogue editing. The editor collects every needed take and line. Then they lay them on tracks, lined up with the picture.','It creates an organized, in-sync base of all usable dialogue so later editing, splitting, and mixing have complete, well-labelled material to work from.','Working from the picture editor''s cut and the sound reports, the editor pulls the matching original recordings onto tracks in sync, choosing the best takes and marking gaps that need fill or ADR.','Editorial Workflow',ARRAY['Dialogue conform','Dialogue tracklay','DX A / DX B','Dialogue fill','ADR']::text[],ARRAY['Editing from the picture department''s mixed guide track instead of the original recordings','Skipping careful sync checks, so lip-sync errors carry through the whole edit','Failing to label takes and rolls, which makes later reconform and troubleshooting hard']::text[],ARRAY['Starting a dialogue edit by conforming original field recordings to the locked cut','Assembling alternates and wild lines alongside the sync takes for a drama scene','Building the dialogue base before handing splits to the re-recording mixer']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='73ee18f8-8f96-55a8-8737-d1bfffbc2931' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue assembly'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '73ee18f8-8f96-55a8-8737-d1bfffbc2931','47e2b509-c540-4a23-839c-c7190b673899',true
