INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fa7ede28-f16a-5203-84ed-40fde5191f3b','Dialogue conform','The process of matching a dialogue edit to picture: first, imposing the picture editor''s edit decisions (via an EDL or change list) onto the original multitrack production recordings; and, after picture changes, re-conforming the existing edited session to the new cut so completed work is preserved rather than redone.','The picture edit often changes after sound work starts. Conforming lines the dialogue back up with the new picture. Special tools move the edits so earlier work is kept.','It keeps dialogue in sync with an evolving picture edit and lets editors work from original source recordings, protecting hours of editing when scenes are trimmed, added, or moved.','Using a change list from the picture department, the editor runs conform software to trim, shift, or insert session material so every line matches the updated cut, then checks sync at each change point.','Editorial Workflow',ARRAY['Dialogue assembly','Dialogue tracklay','DX','Dialogue fill','Picture lock']::text[],ARRAY['Beginning heavy editing before picture lock, then facing a large, error-prone reconform','Trusting the automated conform without checking sync at each edit point','Ignoring metadata like roll and timecode, so the conform cannot match the right source files']::text[],ARRAY['Reconforming a dialogue session after the editor delivers a new change list','Conforming original location multitracks to a locked picture EDL to start the edit','Handling a re-cut scene mid-project without losing the existing dialogue work']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fa7ede28-f16a-5203-84ed-40fde5191f3b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue conform'),'[^a-z0-9]','','g'));
