INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3e4fca33-edbc-58dc-9868-4f38ad7d4bb7','Dialogue declicking','The removal of short transient clicks, pops, and digital impulse artifacts from recorded dialogue (including mouth and saliva clicks, edit-point discontinuities, and radio-mic interference) using dedicated de-click processing or manual editing, while preserving the underlying speech.','Recorded speech often has tiny clicks and pops. They come from the mouth, edits, or radio mics. Declicking finds and removes them while leaving the words untouched.','It cleans distracting transient noises out of dialogue without altering the voice, keeping lines smooth and professional.','The editor runs a de-click module or zooms in to redraw or crossfade over individual clicks, using room tone to fill any gap left behind.','Dialogue Repair',ARRAY['Denture click','Dialogue fill','Consonant erosion','Denoise modulation','DX']::text[],ARRAY['Setting de-click sensitivity so high it treats consonant transients as clicks and dulls them','Cutting a click out and leaving a silent hole instead of filling with room tone','Relying only on automatic detection and missing clicks buried under speech']::text[],ARRAY['Removing lip smacks and mouth clicks from a quiet close-up performance','Cleaning radio-mic clicks caused by RF dropouts on a location shoot','Smoothing edit points where two takes were joined and left a click']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3e4fca33-edbc-58dc-9868-4f38ad7d4bb7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue declicking'),'[^a-z0-9]','','g'));
