INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0c8d3411-4fbb-50bf-8dfc-1709f7b77438','Dialogue fill','Room tone or matching background ambience placed into the gaps of a dialogue edit (between and around lines, and on alternate split tracks) so the background stays continuous under and between spoken words, preventing audible drops or holes at edits and cuts; also called fill or presence.','When you cut between takes, the background can suddenly drop out. Fill is quiet room sound placed in the gaps. It keeps the background smooth so cuts don''t jump out.','It provides a seamless background bed so edits, splits, and silences do not reveal themselves as sudden changes in ambience.','The editor gathers room tone recorded on set, or borrows quiet sections between lines, and lays it into every gap on the dialogue tracks, crossfading it against the sync recordings.','Editing Technique',ARRAY['Dialogue declicking','DX A / DX B','Dialogue assembly','Dialogue tracklay','Room tone']::text[],ARRAY['Leaving digital silence in gaps, so the background drops out at every edit','Using fill from a different location whose tone does not match the scene','Forgetting to fill the alternate A/B tracks, so backgrounds pop in and out at cuts']::text[],ARRAY['Filling the gaps between lines so a scene''s ambience stays continuous','A set where no dedicated room tone was recorded, forcing fill taken from quiet moments in takes','Smoothing checkerboarded A/B dialogue tracks so cuts between angles are inaudible']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0c8d3411-4fbb-50bf-8dfc-1709f7b77438' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue fill'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0c8d3411-4fbb-50bf-8dfc-1709f7b77438','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0c8d3411-4fbb-50bf-8dfc-1709f7b77438' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fea1b5b2-718b-536c-a2c8-7bb9062bca33','Dialogue tracklay','The organized laying-out of edited dialogue across a session''s tracks (splitting lines by character, perspective, mic, or sound quality onto dedicated and alternate tracks, filling gaps, and labelling routing) to prepare a clean, mix-ready dialogue premix for the re-recording stage.','Tracklay means arranging the edited dialogue neatly across many tracks. The editor groups lines by who is speaking or how they sound. This gives the mixer a tidy layout.','A clear track layout lets the re-recording mixer process, balance, and route groups of dialogue efficiently, and keeps consistent-sounding material together.','The editor distributes lines onto split tracks (for example by character or angle), fills gaps with room tone, and names and routes tracks so the mix session opens ready to balance.','Editorial Workflow',ARRAY['Dialogue assembly','DX A / DX B','Dialogue fill','Dialogue conform','DX']::text[],ARRAY['Piling all dialogue onto one or two tracks, leaving the mixer no way to group it','Not naming or routing tracks, so the mix session is confusing to open','Splitting inconsistently, mixing character-based and angle-based logic on the same reel']::text[],ARRAY['Laying out a finished dialogue edit into character splits before the mix','Preparing a mix-ready session with labelled DX A/B tracks and fill','Organizing tracks so a mixer can quickly EQ and level each perspective']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fea1b5b2-718b-536c-a2c8-7bb9062bca33' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue tracklay'),'[^a-z0-9]','','g'));
