INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cdd3ef3d-56e4-5f1b-9345-afa96fd522df','Dialogue-isolation residue','The audible artifacts left in dialogue after source-separation or dialogue-isolation processing (which extracts speech from mixed or noisy recordings), such as watery smearing, spectral flutter, dropped consonants, or ghostly remnants of the removed background, that betray the separation and reduce naturalness.','Some tools can pull speech out of a noisy mix. They are not perfect. What is left can sound watery or smeared, and bits of the old background may linger.','Naming this residue reminds editors that isolation tools trade cleanliness for artifacts, so their output must be judged and often blended or limited rather than trusted blindly.','After running a dialogue-isolation or separation tool, the editor auditions for smearing and remnants, eases back the strength, or blends the isolated track with the original to hide the artifacts.','Dialogue Repair',ARRAY['Denoise modulation','Consonant erosion','Dialogue declicking','De-plosive overreach','DX']::text[],ARRAY['Trusting an isolated dialogue track fully without listening for watery artifacts','Pushing separation to the maximum, which leaves heavy smearing on the voice','Using isolation as a first resort instead of trying a cleaner source or standard denoise first']::text[],ARRAY['Extracting dialogue from a recording where music or effects bled onto the mic','Rescuing a line from an archival mono mix using source separation','Isolating speech from heavy background traffic when no cleaner take exists']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cdd3ef3d-56e4-5f1b-9345-afa96fd522df' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue-isolation residue'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cdd3ef3d-56e4-5f1b-9345-afa96fd522df','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cdd3ef3d-56e4-5f1b-9345-afa96fd522df' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'de968373-e1f9-532a-ab70-690f13fe8bc8','Dialogue-tainted PFX','Production effects (PFX) - usable on-set sounds such as footsteps, door closes, and prop handling captured on the production tracks - that cannot be cleanly reused because dialogue overlaps or bleeds onto them, tainting the effect so it cannot be split into the effects stem without carrying unwanted speech.','On set, useful sounds like footsteps get recorded along with the talking. If a line overlaps a sound, you cannot use that sound alone. The speech is stuck to it.','Flagging PFX as dialogue-tainted tells the team the sound cannot move cleanly to the effects stem, so it must be replaced with Foley or a clean effect to keep the dialogue and effects stems separate.','When splitting tracks, the editor spots a production effect with dialogue over it, keeps it with the dialogue if needed for sync, and notes it for Foley or sound effects to recreate cleanly.','Track Organization',ARRAY['DX','DX A / DX B','Dialogue tracklay','Dialogue fill','Foley']::text[],ARRAY['Moving a dialogue-tainted effect into the effects stem, dragging speech along with it','Assuming every production effect is reusable without checking for dialogue overlap','Not flagging tainted PFX for Foley, leaving a gap when the dialogue stem is muted']::text[],ARRAY['A door slam that lands under a spoken line cannot be split cleanly to effects','Preparing splits for foreign dubbing, where tainted PFX must be recreated as Foley','A footstep overlapping dialogue is noted for replacement rather than reuse']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='de968373-e1f9-532a-ab70-690f13fe8bc8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dialogue-tainted PFX'),'[^a-z0-9]','','g'));
