INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '182c8983-6861-59e2-baba-eae627ee6bee','Dynamic phase alignment','The continuous, time-varying correction of timing and phase between two or more microphones capturing the same source (typically boom and lavalier) so that combining them does not produce comb filtering or cancellation. Unlike a fixed offset, it re-tracks the alignment throughout a take to follow moving actors, microphones, or perspective changes.','Two microphones pick up the same voice a tiny bit apart in time. Mixed together, they can sound thin or hollow. Dynamic phase alignment lines one mic up with the other. It keeps adjusting as the actor moves during the take.','It lets an editor blend boom and lav tracks freely without the hollow, filtered tone caused by phase differences, and it maintains that match as the geometry between actor and mics changes over a shot.','Dialogue editors run tools such as Sound Radix Auto-Align Post in dynamic mode across boom-and-lav pairs before a mix so any combination of mics stays in phase throughout a moving take.','Phase & Sync',ARRAY['Comb filtering','Boom','Lavalier','Perspective','ISO track','Phase cancellation']::text[],ARRAY['Applying a single static offset to the whole clip when the actor moves, so alignment drifts and comb filtering returns mid-line.','Assuming polarity (flipping phase 180 degrees) is the same as time-and-phase alignment; polarity alone will not fix arrival-time differences.','Aligning to the wrong reference mic, degrading the track that actually sounds best.']::text[],ARRAY['Blending a boom and a radio lav on a walk-and-talk where the distance between actor and boom constantly changes.','Removing the hollow, phasey tone heard when a lav and boom of the same line are summed in the mix.','Preparing multi-mic production dialogue so the re-recording mixer can freely cross-fade between mics.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='182c8983-6861-59e2-baba-eae627ee6bee' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dynamic phase alignment'),'[^a-z0-9]','','g'));
