INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '60d50255-f279-51ef-b34a-555cd2fc4776','Edit exposure','The degree to which a dialogue edit is perceptible to the audience, determined mainly by how much the background tone, level, or texture changes across the splice. An edit is ''exposed'' when a mismatch at the cut makes the join audible rather than invisible.','An edit is ''exposed'' when the audience can hear the cut. It happens when the background sound jumps at the splice. The more the background changes, the more the edit stands out. Editors add room tone so cuts stay hidden.','The concept guides an editor''s judgement about which cuts are safe and which need smoothing, since the goal of dialogue editing is joins that the audience never notices.','An editor auditions each questionable cut in context and, where the edit is exposed, adds matching fill, extends handles, or uses a crossfade until the join disappears.','Editing Technique',ARRAY['Room tone','Fill','Crossfade','Handle','Splice','Fill seam']::text[],ARRAY['Judging an edit only by soloing the dialogue track instead of in the full context of backgrounds where exposure is really heard.','Relying on a crossfade to hide a cut where the two backgrounds differ too much; fill or an ADR fix is needed instead.','Cutting mid-word or mid-sibilant, exposing the edit through an obvious break in the voice.']::text[],ARRAY['Deciding whether a cut between two takes with different air-conditioning tone needs a fill patch.','Reviewing a scene on the mix stage where a previously unnoticed edit becomes obvious at higher monitoring levels.','Choosing an alternate take because its background makes the necessary edit less exposed.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='60d50255-f279-51ef-b34a-555cd2fc4776' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Edit exposure'),'[^a-z0-9]','','g'));
