INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f8751aca-393e-598e-99fa-70b6b20deb44','Fabric tick','A short transient click or crackle in a lavalier-microphone track caused by clothing or fabric brushing, tapping, or dragging against the capsule or its mount. It is a discrete member of the broader family of lav ''rustle'' artifacts, distinct from continuous cloth swish.','A clip-on mic often sits under an actor''s clothes. When cloth brushes the mic, it makes a short click. This click is called a fabric tick. Editors remove these ticks so speech sounds clean.','Naming the artifact lets editors target these brief transients specifically, using spectral repair or de-rustle processing, so the isolated clicks do not distract from otherwise usable lav dialogue.','An editor spots fabric ticks on the spectrogram as bright vertical streaks and paints them out with spectral repair, or uses RX De-rustle, choosing a lav-free alternate mic for that moment when the tick sits over a word.','Noise & Artifacts',ARRAY['Lavalier','De-rustle','Spectral repair','Boom','Noise floor','Handle']::text[],ARRAY['Reaching for broadband noise reduction, which does not track these unpredictable transients and dulls the voice instead.','Removing the tick but leaving a silent hole, so the missing background under it now exposes the edit.','UNSAFE: Soloing and boosting a lav to hunt for faint ticks at very high monitoring levels; keep exposure within OSHA 29 CFR 1910.95 limits to protect hearing.']::text[],ARRAY['Cleaning ticks from a lav hidden under a stiff costume in a period drama.','Deciding between patching a fabric tick with spectral repair or cutting to the boom for that syllable.','Preparing a lav track so the re-recording mixer can use it without audible clothing clicks.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f8751aca-393e-598e-99fa-70b6b20deb44' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fabric tick'),'[^a-z0-9]','','g'));
