INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '67f5e106-c02d-532f-be14-69308136fde7','Field-recorder expansion','The workflow of replacing a mono/stereo production mixdown ''guide track'' in the edit with the full set of isolated (ISO) channels from the original polyphonic field-recorder files, matched by timecode and metadata. In Pro Tools this is the ''Expand Channels to New Tracks'' operation on a Field Recorder guide track.','On set, a recorder captures each mic on its own track. The editor often gets only a simple mixed version first. Expansion swaps that mix for all the separate mic tracks. This gives the editor every microphone to choose from.','It rebuilds access to every individual microphone while preserving the picture editor''s cuts and fades, so the dialogue editor can pick the best mic for each line instead of being stuck with the location mix.','The editor relinks the guide track to the original field-recorder files, then expands it to reveal boom, lav, and other ISO channels aligned to the existing edit, ready to choose and clean.','Conform & Workflow',ARRAY['Guide dialogue','ISO track','Timecode','Polyphonic WAV','Boom','Lavalier']::text[],ARRAY['Trying to match by file name alone when timecode or scene/take metadata is missing, producing wrong or failed matches.','Expanding channels but forgetting the ISOs need their own noise cleanup, assuming they are as finished as the delivered mix.','Confusing the production mixdown guide track with an ADR guide, and treating a temporary reference as final audio.']::text[],ARRAY['Recovering a clean boom ISO after the location mixdown favored a noisy lav.','Conforming an AAF from picture editorial back to all original microphones before dialogue editing begins.','Choosing the best of several radio-mic ISOs for an actor after expanding a crowded scene.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='67f5e106-c02d-532f-be14-69308136fde7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Field-recorder expansion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '67f5e106-c02d-532f-be14-69308136fde7','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='67f5e106-c02d-532f-be14-69308136fde7' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0a4b5ec7-b9e9-5929-96a7-b5a5f82599b4','Fill bed','A continuous underlying layer of matching room tone (fill) laid across a scene beneath the edited dialogue so the background remains constant and edits, level changes, and gaps are masked. It functions as the steady ''base'' onto which cleaned production lines are placed.','Every room has a quiet background sound, even when no one talks. A fill bed is a steady layer of that sound. Editors lay it under a whole scene. It hides the gaps between spoken lines.','It gives a scene one uninterrupted background so the ear hears a single space rather than the shifting tone of many separate production clips and their silences.','An editor lays a matched room-tone bed on a dedicated track under a scene, then places dialogue over it, so cuts and quiet gaps sit in a seamless, continuous ambience.','Room Tone & Fill',ARRAY['Room tone','Fill','Fill seam','Fill loop','Fill harvesting','Edit exposure']::text[],ARRAY['Using a bed whose tone or level does not match the production dialogue, so the join between line and bed is audible.','Laying one bed across scenes that were shot in different acoustic spaces, ignoring changes in perspective or location.','Letting the bed play under ADR or effects where it doubles an ambience the mixer will add separately.']::text[],ARRAY['Smoothing a dialogue scene cut from many takes so it plays as one continuous room.','Filling the silent gaps left after breaths and noises are removed from a quiet interior.','Providing the re-recording mixer a clean, continuous background under the principal dialogue.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0a4b5ec7-b9e9-5929-96a7-b5a5f82599b4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fill bed'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0a4b5ec7-b9e9-5929-96a7-b5a5f82599b4','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0a4b5ec7-b9e9-5929-96a7-b5a5f82599b4' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5ceba4ae-faf4-5ccd-b242-21ef7a3e92d7','Fill buildup','The unwanted accumulation of background level or noise floor that results from overlapping, stacking, or crossfading multiple pieces of fill, so the ambience audibly rises where segments coincide. It is a level/energy artifact of assembling fill, not a property of any single clip.','Editors patch quiet gaps with recorded background sound, called fill. Stacking too many pieces can make the background grow louder. This slow rise is fill buildup. It makes the quiet parts sound noisier than they should.','Recognizing buildup keeps the background at a constant level, since summing overlapping fill adds energy and would otherwise make the ambience swell exactly where the most patching was done.','An editor watches for rising background where fill layers overlap, thinning crossfades or trimming stacked segments so the summed room tone stays even across the scene.','Room Tone & Fill',ARRAY['Fill','Fill bed','Fill pumping','Crossfade','Noise floor','Room tone']::text[],ARRAY['Crossfading two overlapping fill clips with equal-gain fades, so their sum bumps up in level at the overlap.','Adding more and more fill patches without checking the cumulative background level against the rest of the scene.','Blaming a compressor for a swelling background that is actually summed fill building up underneath it.']::text[],ARRAY['Noticing the room tone gets louder in a passage that required many small fill patches.','Balancing overlapping fill segments so the background does not surge under a run of quick cuts.','Diagnosing why a smoothed scene sounds noisier in its busiest edited section.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5ceba4ae-faf4-5ccd-b242-21ef7a3e92d7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fill buildup'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5ceba4ae-faf4-5ccd-b242-21ef7a3e92d7','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5ceba4ae-faf4-5ccd-b242-21ef7a3e92d7' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '35982bc7-c482-568f-a8da-45aa07840cea','Fill harvesting','The practice of gathering usable room tone (fill) from the production recordings themselves — pauses between lines, handles, unused takes, and material before ''action'' or after ''cut'' — to build a stock of tone that matches each microphone and setup for patching that scene.','Fill is quiet background sound used to patch a scene. Harvesting means gathering it from the raw recordings. Editors grab the quiet moments before and after each take. They save these clips to smooth the dialogue later.','Because tone taken from the same take and mic matches perfectly, harvesting supplies the best possible fill when no dedicated room-tone recording exists or when the recorded room tone does not match.','An editor scans each take for clean gaps and off-slate moments, cuts out those quiet stretches, and files them per mic and scene as fill for building beds and patching holes.','Room Tone & Fill',ARRAY['Room tone','Fill','Fill pull','Fill bed','Handle','ISO track']::text[],ARRAY['Harvesting fill from a different mic or take than the line it will patch, so texture and level do not match.','Grabbing ''quiet'' that actually contains a faint off-mic voice, footstep, or camera noise that repeats when used.','Skipping harvesting because a wild room-tone track exists, even when that track was recorded with a different mic or perspective.']::text[],ARRAY['Building a fill library when the location crew failed to record dedicated room tone.','Collecting matching tone from the pauses within a take to patch that same take''s edits.','Assembling per-microphone fill for a scene covered by boom and several lavs.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='35982bc7-c482-568f-a8da-45aa07840cea' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fill harvesting'),'[^a-z0-9]','','g'));
