INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6d6755ab-88c1-56fd-be6f-652510cde35f','Fill loop','A short segment of room tone repeated end-to-end (looped) to cover a gap longer than the available matching tone. Effective loops are chosen and crossfaded so no repeating pattern, cadence, or transient betrays the repetition.','Sometimes an editor has only a short piece of background sound. A fill loop repeats that piece to cover a longer gap. The trick is to hide the repeat. A clear pattern would sound fake to the audience.','It extends limited fill across long silences so the background stays continuous, letting a few seconds of clean tone service a much longer stretch of dialogue.','An editor picks a loop free of distinct events, crossfades the loop points, and often reverses or offsets copies so the repeated tone reads as natural continuous ambience.','Room Tone & Fill',ARRAY['Room tone','Fill','Fill bed','Crossfade','Fill seam','Fill harvesting']::text[],ARRAY['Looping a piece that contains a distinct tick, breath, or tone, so the event pulses at the loop rate.','Butt-joining loop points without a crossfade, creating a click at every repeat.','Using a loop too short, so its rhythm becomes recognizable and the background sounds artificial.']::text[],ARRAY['Covering a long, quiet dialogue gap when only a few seconds of matching tone were harvested.','Extending a fill bed under a slow scene without an audible repeat.','Sustaining consistent room tone beneath a monologue cut from several takes.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6d6755ab-88c1-56fd-be6f-652510cde35f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fill loop'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6d6755ab-88c1-56fd-be6f-652510cde35f','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6d6755ab-88c1-56fd-be6f-652510cde35f' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dc376fc9-a401-559a-a12f-4dccaa078826','Fill pull','A single piece of matching room tone extracted from material immediately adjacent to an edit — the same take and same microphone — and used to patch the hole at that cut. The ''pull'' comes from as close as possible to the join so texture, level, and perspective match exactly.','When a cut leaves a hole, the editor needs matching background sound. A fill pull grabs a piece from right next to the hole. It comes from the same take and same mic. That way the texture matches perfectly.','Pulling fill from adjacent material guarantees the closest possible match, which is the surest way to make an individual edit invisible without hunting through a wider fill library.','At a problem cut, the editor opens the handles of the neighboring clip, pulls a clean stretch of its tone, and drops it into the gap to hide the join.','Room Tone & Fill',ARRAY['Fill','Room tone','Fill harvesting','Handle','Fill seam','Edit exposure']::text[],ARRAY['Pulling from a spot that seems quiet but carries a faint word-tail or mouth noise into the patch.','Pulling from a distant take when adjacent same-take tone was available, giving a worse match.','Forgetting to crossfade the pulled fill into the surrounding tone, leaving a seam at each end.']::text[],ARRAY['Patching the split-second hole left after removing a cough between two lines.','Filling under a word that had to be replaced from another take.','Grabbing tone from a take''s handle to bridge a tight, exposed cut.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dc376fc9-a401-559a-a12f-4dccaa078826' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fill pull'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dc376fc9-a401-559a-a12f-4dccaa078826','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dc376fc9-a401-559a-a12f-4dccaa078826' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cc878772-eec3-5274-9a30-f6d7809669a7','Fill pumping','An audible rhythmic swelling and ducking of the background under dialogue caused by mismatched fill levels between segments, or by noise reduction/gating that lets the ambience rise and fall between edits. The steady room tone appears to breathe in time with the cuts.','Background sound should stay steady under the dialogue. If fill levels don''t match, the background swells and fades. This rise and fall is called pumping. It pulls the listener''s attention to the edits.','Identifying pumping helps an editor keep the background perfectly even, because any level or gate-driven fluctuation between fill pieces makes otherwise hidden edits noticeable.','When the room tone seems to breathe with the cuts, the editor matches fill levels, softens noise-reduction thresholds, and crossfades segments so the background holds a constant level.','Room Tone & Fill',ARRAY['Fill','Fill bed','Fill buildup','Noise floor','Crossfade','Edit exposure']::text[],ARRAY['Matching fill by waveform size rather than by ear, so equal-looking pieces still pump in level.','Setting aggressive noise reduction per clip, so the noise floor jumps at every clip boundary.','Fixing pumping with a downstream gate, which often deepens the breathing instead of curing it.']::text[],ARRAY['A dialogue scene whose air-conditioning hum seems to pulse in time with each edit.','Uneven lav fill making the background surge and dip beneath a conversation.','Noise-reduced production tracks whose floor rises and falls between cleaned lines.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cc878772-eec3-5274-9a30-f6d7809669a7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fill pumping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cc878772-eec3-5274-9a30-f6d7809669a7','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cc878772-eec3-5274-9a30-f6d7809669a7' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3824fb9b-1122-52f7-8855-16c19b6d6553','Fill seam','The boundary where two pieces of fill, or a piece of fill and the production tone, meet on the timeline. When level and texture match the seam is inaudible; when they do not, it reveals itself as a click, bump, or sudden change in the background.','A fill seam is the join where two pieces of background meet. If the pieces match, you cannot hear the join. If they don''t match, the seam clicks or jumps. Editors use crossfades to hide the seam.','Thinking in terms of seams focuses the editor on every join in the background, since it is the seams, not the fill itself, that expose edits when they are not smoothed.','The editor crossfades each fill seam and matches level and tone across it, checking that the background flows through the join with no click or step.','Room Tone & Fill',ARRAY['Fill','Crossfade','Fill bed','Fill loop','Splice','Edit exposure']::text[],ARRAY['Butt-cutting fill pieces with no crossfade, so a click appears at the seam.','Crossfading across a seam where the two backgrounds differ, smearing the change instead of hiding it.','Matching level at the seam but ignoring a tonal difference that still makes the join audible.']::text[],ARRAY['Joining a harvested fill clip to a looped section under a long pause.','Blending a fill patch into the production tone on either side of a removed noise.','Checking every join in a fill bed before handing the scene to the mix.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3824fb9b-1122-52f7-8855-16c19b6d6553' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fill seam'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3824fb9b-1122-52f7-8855-16c19b6d6553','47e2b509-c540-4a23-839c-c7190b673899',true
