INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '948fcf1a-caaa-5868-a960-75ab2e95a86c','Formant smearing','The blurring or loss of definition of a voice''s formants — the resonant frequency peaks that give vowels their identity and the speaker their vocal character — caused by time-stretching, pitch-shifting, spectral processing, or heavy noise reduction. The result is speech that sounds dull, hollow, or unnatural.','A voice has resonant peaks that give it its character. These peaks are called formants. Heavy pitch or time processing can blur them. The voice then sounds smeared, dull, or robotic.','Understanding formant smearing tells an editor when processing is degrading intelligibility and identity, guiding gentler settings or formant-preserving tools that keep the voice natural.','When stretched or pitched dialogue starts to sound artificial, the editor enables formant preservation, reduces the amount of processing, or re-cuts so less time or pitch change is needed.','Noise & Artifacts',ARRAY['Formant','Pitch shift','Time stretch','Spectral repair','ADR','Intelligibility']::text[],ARRAY['Pitch-shifting a voice without formant correction, so it takes on an unnatural, chipmunk-like or hollow quality.','Over-applying spectral noise reduction until the formants blur and the voice loses presence.','Blaming a microphone for a dull, smeared voice that was actually degraded by heavy time or pitch processing.']::text[],ARRAY['Stretching a line to fit a lip-sync window without making the actor sound processed.','Pitch-nudging an ADR take to match production while keeping the natural voice.','Judging how far noise reduction can go on dialogue before the voice smears.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='948fcf1a-caaa-5868-a960-75ab2e95a86c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Formant smearing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '948fcf1a-caaa-5868-a960-75ab2e95a86c','47e2b509-c540-4a23-839c-c7190b673899',true
