INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'de0fe644-dc95-5e55-96ab-37bad06700b5','Guide dialogue','Production dialogue kept as a temporary reference — a ''guide'' — rather than as final audio: used to cut picture, to cue and pace ADR or re-recording, or to guide animation and localization. It preserves timing, performance, and phrasing even when the recording itself is too poor to use in the mix.','Guide dialogue is the original talk recorded on set. It is kept as a reference, not always for the final film. Editors use it to time re-recorded lines or animation. Later it is often replaced with cleaner audio.','It carries the original performance and timing forward through post so replacement dialogue, animation, or a dubbed language can be matched to what was actually spoken and when.','An editor lines up ADR or animation against the guide dialogue for sync and delivery, then mutes or replaces the guide once the clean version is approved.','Conform & Workflow',ARRAY['ADR','Field-recorder expansion','Room tone','Lip sync','Production sound','Timecode']::text[],ARRAY['Letting unusable guide dialogue leak into the final mix because it was never muted after replacement.','Cutting ADR to the wrong reference and losing sync when the guide and picture were offset.','Discarding guide tracks too early, before the replacement lines are locked and approved.']::text[],ARRAY['Cueing and timing an ADR session against the noisy on-set recording.','Providing animators a scratch vocal to animate mouth movements against.','Keeping a timing reference for a foreign-language dub of a scene.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='de0fe644-dc95-5e55-96ab-37bad06700b5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Guide dialogue'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'de0fe644-dc95-5e55-96ab-37bad06700b5','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='de0fe644-dc95-5e55-96ab-37bad06700b5' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b9914b98-2464-5872-a527-73058299c96b','Handle preservation','The practice of retaining extra frames of usable audio, with matching room tone, beyond the intended in and out points of a dialogue edit, so crossfades, sync nudges, and later re-cuts can be made without running out of material. In turnover and conform, handles are the additional media exported on each side of a clip.','Handles are extra bits of sound left on each end of a clip. You keep them so you can slide edits or add fades later without gaps. It is like leaving extra cloth at a seam so you can let the hem out.','It lets editors and mixers adjust edit points, build smooth crossfades, and reconform to picture changes without re-sourcing the original recordings.','When exporting an AAF or OMF, or conforming a session, the editor sets a handle length so each clip carries spare audio at its head and tail.','Editorial Workflow',ARRAY['Microphone splitting','Mix-track guide','Room tone','Crossfade','Lav lane','Micro-comping']::text[],ARRAY['Exporting clips with zero or too-short handles, leaving no material to build crossfades or fix sync.','Assuming handles contain matching room tone when the extra audio includes off-mic noise or another actor''s line.','Trimming handles away during cleanup and then being unable to reconform after a picture change.']::text[],ARRAY['Preparing an AAF turnover from the picture editor for the dialogue editor.','Building a crossfade across a hard cut between two takes.','Reconforming dialogue after the picture department delivers a new cut.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b9914b98-2464-5872-a527-73058299c96b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Handle preservation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b9914b98-2464-5872-a527-73058299c96b','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b9914b98-2464-5872-a527-73058299c96b' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '147c2259-c52f-5deb-8a97-9d648dd11e06','Head-turn loss','The drop in level and loss of high-frequency content that occurs when a performer turns their head away from the microphone, moving the voice off the mic''s on-axis pickup into its less-sensitive, more colored off-axis region. It produces an audible timbral and loudness shift within a single line.','When an actor turns their head away from the mic, the voice gets quieter and duller. The mic hears the side of the sound, not the front. It is like someone talking while they turn away from you.','Recognizing it explains why a word or line suddenly dulls, so the editor can match tone across the edit or choose a better microphone source.','The editor spots the dip mid-line, then patches it from a lavalier or another take, or applies EQ and level moves so perspective stays consistent.','Mic Perspective',ARRAY['Mic-angle change','Microphone splitting','Lav lane','Mix-track guide','Handle preservation']::text[],ARRAY['Boosting level alone to fix a head turn, which leaves the dull off-axis tone unmatched.','Not checking the lavalier track, which often stays on-mic when the boom loses the head turn.','Assuming the recording is faulty rather than a normal off-axis effect of head movement.']::text[],ARRAY['An actor delivers a line while turning to exit frame.','A two-shot where a character glances away mid-sentence.','Matching the boom to a lavalier when the head turn dulls the boom.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='147c2259-c52f-5deb-8a97-9d648dd11e06' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Head-turn loss'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '147c2259-c52f-5deb-8a97-9d648dd11e06','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='147c2259-c52f-5deb-8a97-9d648dd11e06' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f1bcf764-f1f2-522f-8deb-8d7b22d25111','Inhale truncation','The editorial shortening or removal of an audible in-breath before or between lines of dialogue, done to tighten pacing or reduce a distracting or oversized breath while keeping speech sounding natural.','This means trimming the sound of a breath before a line. Editors do it to tighten timing or hide a loud gasp. Cutting too much can make talking sound robotic.','It controls the rhythm and cleanliness of dialogue, removing distracting breaths without stripping the natural breathing that makes speech believable.','The editor shortens the inhale with a trim and crossfade, or replaces it with quieter room tone, keeping enough breath that the delivery still sounds human.','Editing Technique',ARRAY['Room tone','Crossfade','Handle preservation','Micro-comping','Lip-smack suppression']::text[],ARRAY['Removing every breath, which makes the performance sound unnatural and rushed.','Cutting an inhale so tightly that the following word loses its attack or gets clipped.','Leaving a hard edit with no crossfade, creating a click or tonal jump where the breath was.']::text[],ARRAY['Tightening a monologue that drags because of heavy breaths.','Reducing an exaggerated gasp before an emotional line.','Cleaning up narration or voice-over pacing.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f1bcf764-f1f2-522f-8deb-8d7b22d25111' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Inhale truncation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f1bcf764-f1f2-522f-8deb-8d7b22d25111','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f1bcf764-f1f2-522f-8deb-8d7b22d25111' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a2c23812-b094-587a-ad94-14e8fa5c8f0e','Intermittent rustle','Clothing- or contact-borne friction noise on a microphone, typically a lavalier, that appears sporadically rather than continuously and correlates with the performer''s movement. Its on-and-off nature makes it harder to treat with steady broadband noise reduction.','This is scratchy clothing noise that comes and goes on a mic. It happens when the actor moves, not all the time. Because it is not steady, simple noise removal misses it.','Naming the pattern guides the repair approach: the editor targets each burst instead of applying constant noise reduction meant for steady hiss.','The editor isolates each rustle burst and treats it with specialized de-rustle processing, or replaces the moment from a cleaner take or microphone.','Noise & Artifacts',ARRAY['Lav rustle','Jewelry tick','Microphone splitting','Room tone','Handle preservation']::text[],ARRAY['Applying steady-state broadband noise reduction, which does not track noise that starts and stops.','Processing the whole clip when only short bursts need repair, dulling the clean speech.','Missing quiet rustle hidden under louder words because it is intermittent.']::text[],ARRAY['An actor gestures, brushing the hidden lavalier only on certain moves.','Rustle appears only when a character walks, not when still.','Choosing between boom and lavalier because the lavalier rustles intermittently.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a2c23812-b094-587a-ad94-14e8fa5c8f0e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Intermittent rustle'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a2c23812-b094-587a-ad94-14e8fa5c8f0e','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a2c23812-b094-587a-ad94-14e8fa5c8f0e' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1583d828-5470-5d04-986d-2fd3d0720852','Jewelry tick','A short, transient click or tick caused by jewelry such as necklaces, bracelets, earrings, or buttons striking a body-worn microphone, its cable, or another piece of jewelry during a take. It reads as a sharp, brief impulse over the dialogue.','This is a small click from jewelry hitting a hidden mic or another piece of jewelry. Think of a necklace tapping the mic as the actor moves. It shows up as a sharp tick over the words.','Identifying it as a discrete transient tells the editor to remove it with click-repair tools rather than broadband noise reduction.','The editor finds each tick on the waveform and repairs it with a de-click tool or a short spot fix, or patches the spot from a clean alternate source.','Noise & Artifacts',ARRAY['Lav crackle','Lav rustle','Intermittent rustle','Microphone splitting','Handle preservation']::text[],ARRAY['Trying to fix a sharp tick with noise reduction meant for steady background, which leaves the transient.','Over-processing and creating a dull hole where the click was.','Not checking a second microphone that may be free of the tick.']::text[],ARRAY['An actor wearing a necklace leans forward and the pendant taps the lavalier.','A watch or bracelet clicks against a wrist-hidden cable.','Two pieces of jewelry click together during movement.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1583d828-5470-5d04-986d-2fd3d0720852' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Jewelry tick'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1583d828-5470-5d04-986d-2fd3d0720852','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1583d828-5470-5d04-986d-2fd3d0720852' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e15e0707-39e5-59e5-b793-3597b7c05785','Lav chest resonance','A low-frequency emphasis or boominess in body-worn (lavalier) dialogue caused by the microphone''s placement on the chest, where chest-cavity resonance and proximity to the torso build up low-mid energy. It usually requires corrective EQ to match a boom or a more open sound.','A mic on the chest picks up extra low, boomy sound from the body. It can make a voice sound thick or muffled. Editors cut some low tones to fix it.','Understanding the cause lets the editor apply the right EQ to thin the boominess so the lavalier matches the boom and sounds natural.','The editor rolls off or dips the offending low-mid range on the lavalier track, and may add a slight presence boost to restore clarity and match perspective.','Tonal Correction',ARRAY['Lav rustle','Mic-angle change','Microphone splitting','Head-turn loss','Lav lane']::text[],ARRAY['Assuming the actor''s voice is naturally boomy instead of recognizing chest placement as the cause.','Cutting too much low end, leaving the voice thin and unmatched to the boom.','Applying one fixed EQ to every lavalier when placement and wardrobe differ from shot to shot.']::text[],ARRAY['A lavalier taped to the sternum sounds thick next to the boom.','Matching a chest-mounted lavalier to an open boom in the same scene.','A wide shot forces reliance on a boomy hidden lavalier.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e15e0707-39e5-59e5-b793-3597b7c05785' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lav chest resonance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e15e0707-39e5-59e5-b793-3597b7c05785','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e15e0707-39e5-59e5-b793-3597b7c05785' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6ea8d604-f468-5417-8b34-e4fabff3a33a','Lav crackle','An intermittent crackling artifact on a lavalier track, heard as many closely spaced low-level clicks, typically caused by moisture or sweat contaminating the capsule or by an intermittent connection in the cable, connector, or transmitter. It differs from clothing rustle in being contact- or electrically-based rather than friction-based.','This is a crackly, sputtering noise on a body mic. It often comes from sweat getting into the mic or a loose cable. It sounds like many tiny clicks close together.','Correctly diagnosing crackle points the editor toward de-crackle and de-click repair, and tells production the mic or connector may need attention.','The editor applies de-crackle processing, spot-repairs bursts, or replaces affected moments from the boom or a clean take.','Noise & Artifacts',ARRAY['Jewelry tick','Lav rustle','Intermittent rustle','Microphone splitting','Room tone']::text[],ARRAY['Confusing sweat or connection crackle with clothing rustle and reaching for the wrong repair tool.','Trying to rescue a heavily crackling take when a clean boom of the same line is available.','Over-processing with de-crackle until the voice sounds dull and watery.']::text[],ARRAY['A performer sweats under hot lights and the hidden lavalier starts to crackle.','An intermittent connector click appears only on the lavalier, not the boom.','Deciding between repairing lavalier crackle and cutting to the boom.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6ea8d604-f468-5417-8b34-e4fabff3a33a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lav crackle'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6ea8d604-f468-5417-8b34-e4fabff3a33a','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6ea8d604-f468-5417-8b34-e4fabff3a33a' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4b8bc24e-f68a-5247-9cdd-6bfa53a1c48c','Lav lane','A dedicated track or playlist lane in the editing session reserved for lavalier-microphone material, kept separate from boom and other sources so lavalier takes can be organized, edited, processed, and level- and EQ-matched independently.','This is a track set aside just for the body-mic recordings. Keeping body mics on their own lane makes them easy to edit and match. It is like sorting laundry into separate baskets.','It keeps each microphone type on its own path so perspective, EQ, and noise treatment can be handled consistently and switched cleanly during the mix.','The editor routes all lavalier sources to their own lanes or tracks, splitting them from the boom during the split-tracks stage of prep.','Editorial Workflow',ARRAY['Microphone splitting','Mix-track guide','Handle preservation','Micro-comping','Lav rustle']::text[],ARRAY['Mixing lavalier and boom clips on one track, making it impossible to process each source separately.','Not labeling lanes per character or microphone, causing confusion during the mix.','Forgetting to carry room tone and handles onto the lavalier lane for smooth edits.']::text[],ARRAY['Splitting a production AAF into separate boom and lavalier lanes.','Organizing multiple wireless lavaliers per character across a scene.','Handing an organized session to the re-recording mixer.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4b8bc24e-f68a-5247-9cdd-6bfa53a1c48c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lav lane'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4b8bc24e-f68a-5247-9cdd-6bfa53a1c48c','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4b8bc24e-f68a-5247-9cdd-6bfa53a1c48c' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cb326416-901c-5d5a-8c1d-b3c3d301c193','Lav rustle','Friction noise produced when a lavalier microphone or its cable rubs against clothing, skin, or itself as the performer moves, ranging from high-frequency brushing to low-frequency thumps. It is a leading cause of unusable body-microphone dialogue.','This is scratchy noise from clothing rubbing on a hidden body mic. It happens when the actor moves. It can range from a soft brush to a dull thump.','Identifying it directs the editor to de-rustle tools or to a cleaner source, and reminds production to mount and dress the mic to avoid contact.','The editor treats affected moments with de-rustle processing or cuts to the boom, choosing per moment based on which source is cleaner.','Noise & Artifacts',ARRAY['Intermittent rustle','Jewelry tick','Lav crackle','Microphone splitting','Lav chest resonance']::text[],ARRAY['Assuming rustle can always be removed in post instead of capturing a clean boom on set.','Using steady-state noise reduction, which does not track movement-based rustle.','Over-processing until the dialogue sounds muffled and lifeless.']::text[],ARRAY['A hidden lavalier under a jacket brushes fabric as the actor walks.','Choosing boom over lavalier for a moment ruined by rustle.','Applying de-rustle to salvage a wide shot with no usable boom.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cb326416-901c-5d5a-8c1d-b3c3d301c193' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lav rustle'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cb326416-901c-5d5a-8c1d-b3c3d301c193','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cb326416-901c-5d5a-8c1d-b3c3d301c193' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '034380a6-4ef9-5ee6-81f1-d56d144620d0','Lip-smack suppression','The reduction or removal of mouth noises such as lip smacks, clicks, and saliva sounds between and within words of dialogue, using specialized mouth-declick processing or manual editing while preserving natural speech transients such as plosives.','This means removing little mouth clicks and lip smacks between words. Special tools find and lower these sounds. The goal is clean speech that still sounds natural.','It cleans distracting mouth noise from close-miked dialogue and narration so lines sound polished without dulling real speech sounds.','The editor runs a mouth de-click pass or hand-edits individual smacks, checking that plosives and word attacks remain intact.','Dialogue Cleanup',ARRAY['Inhale truncation','Jewelry tick','Micro-comping','Room tone','Handle preservation','Mouth declicking','Mouth-noise cluster']::text[],ARRAY['Setting de-click sensitivity so high that plosives and consonants get softened.','Removing every mouth sound, which can make delivery sound unnaturally sterile.','Hand-editing smacks without a crossfade, leaving a gap or click.']::text[],ARRAY['Cleaning a quiet, close-miked emotional scene.','Polishing narration or voice-over with audible mouth noise.','Prepping an actor''s ADR or dialogue for a clean mix.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='034380a6-4ef9-5ee6-81f1-d56d144620d0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Lip-smack suppression'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '034380a6-4ef9-5ee6-81f1-d56d144620d0','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='034380a6-4ef9-5ee6-81f1-d56d144620d0' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4fe33d8f-2f75-51cb-a996-3c29b1e196ce','Mic-angle change','An audible change in a voice''s timbre and level caused by a shift in the angle between the microphone and the sound source, whether between takes, between shots, or as the boom operator repositions, arising from the mic''s off-axis frequency response. It creates matching problems across edits.','This is a tone change caused by the mic pointing at the actor from a new angle. Sound off to the side is duller than sound straight on. Different angles make cuts hard to match.','Recognizing it explains why two takes will not intercut smoothly, so the editor can EQ, level-match, or choose sources to keep perspective consistent.','The editor compares takes, then matches tone with EQ or picks the source whose angle best matches the surrounding lines.','Mic Perspective',ARRAY['Head-turn loss','Microphone splitting','Lav chest resonance','Mix-track guide','Lav lane']::text[],ARRAY['Matching only loudness and ignoring the off-axis tone difference between angles.','Intercutting takes with very different mic angles without any EQ matching.','Blaming the actor''s performance for a tonal jump that is really a mic-angle issue.']::text[],ARRAY['Cutting between a wide shot boomed from below and a close-up boomed from above.','Two takes where the boom sat at different distances or angles.','Matching an over-the-shoulder angle to its reverse.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4fe33d8f-2f75-51cb-a996-3c29b1e196ce' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mic-angle change'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4fe33d8f-2f75-51cb-a996-3c29b1e196ce','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4fe33d8f-2f75-51cb-a996-3c29b1e196ce' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8f001050-ceaa-5920-a723-75066ee51963','Micro-comping','Assembling the best-sounding dialogue from multiple takes at a very fine scale, at the level of individual words, syllables, or even phonemes, to build a single clean, well-performed line. It is a detailed form of comping specific to dialogue repair and performance shaping.','This means building one good line from tiny pieces of several takes. You might swap a single word or syllable. It is like fixing a sentence one word at a time.','It lets the editor rescue a line''s clarity, sync, or performance by borrowing the cleanest fragments across takes without redoing the whole line.','Using playlists or stacked takes, the editor cuts in individual words or syllables, matches tone and sync, then crossfades the joins.','Editorial Workflow',ARRAY['Handle preservation','Microphone splitting','Inhale truncation','Room tone','Lav lane']::text[],ARRAY['Comping fragments from takes with different mic tone or background, so the joins stand out.','Ignoring sync, so a swapped word no longer matches the picture.','Skipping crossfades at the joins, creating clicks or tonal jumps.']::text[],ARRAY['Replacing one muffled word from a strong take with a clean version from another.','Fixing a single mispronounced syllable without full ADR.','Building the best emotional read from several partial takes.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8f001050-ceaa-5920-a723-75066ee51963' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Micro-comping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8f001050-ceaa-5920-a723-75066ee51963','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8f001050-ceaa-5920-a723-75066ee51963' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a7522304-48aa-52c7-8ded-816560b394e8','Microphone splitting','The dialogue-prep practice of separating the different microphone sources of a scene, such as boom, each lavalier, and any plant mics, onto their own tracks or lanes so each can be edited, cleaned, EQ''d, and level-matched independently before the mix. It replaces a single mixed track with per-microphone control.','This means putting each mic on its own track. The boom goes on one, each body mic on another. That way you can clean and match every mic on its own.','It gives the editor and mixer independent control of each source''s tone, noise, and level so they can choose the best microphone moment to moment.','When prepping a session, the editor routes the isolated mics to separate tracks and organizes them by character and microphone type.','Editorial Workflow',ARRAY['Lav lane','Mix-track guide','Handle preservation','Micro-comping','Head-turn loss']::text[],ARRAY['Editing from the mixed track only and losing the ability to choose a cleaner isolated mic.','Not labeling split tracks by character or microphone, causing confusion at the mix.','Failing to keep sync when spreading mics across multiple tracks.']::text[],ARRAY['Prepping a scene recorded with a boom and several wireless lavaliers.','Splitting a multitrack field recording into per-character tracks.','Handing a source-separated session to the re-recording mixer.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a7522304-48aa-52c7-8ded-816560b394e8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Microphone splitting'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a7522304-48aa-52c7-8ded-816560b394e8','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a7522304-48aa-52c7-8ded-816560b394e8' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2c2e007b-da89-5660-aac9-4580c82886d8','Mix-track guide','The use of the production mixer''s on-set mixdown (mix) track, a blended mono or stereo reference combining the microphones as balanced on set, as a guide for syncing, editing decisions, and understanding intent, while the isolated (iso) tracks are used to rebuild the actual dialogue in post.','On set, the mixer makes one blended track from all the mics. Editors use it as a guide to sync and to hear the intended choice. Then they rebuild the real sound from the separate mic tracks.','It documents the sound mixer''s creative intent and gives a stable reference, while the isolated tracks provide the clean building blocks for the final edit.','The editor lines up and references the mix track, reads the sound report, then edits mainly from the isolated boom and lavalier tracks.','Editorial Workflow',ARRAY['Microphone splitting','Lav lane','Handle preservation','Micro-comping','Room tone']::text[],ARRAY['Editing the whole scene from the mix track and never checking the cleaner isolated tracks.','Ignoring the sound report that explains the mixer''s choices in the mix track.','Assuming the mix track''s balance is final rather than a guide.']::text[],ARRAY['Syncing dailies using the reference mix track.','Reading a sound report to see which microphone the mixer favored.','Rebuilding a scene from isolated tracks while keeping the mix track for reference.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2c2e007b-da89-5660-aac9-4580c82886d8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mix-track guide'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2c2e007b-da89-5660-aac9-4580c82886d8','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2c2e007b-da89-5660-aac9-4580c82886d8' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd6721b01-5d27-53d1-8574-6987a16e9666','Mouth declicking','The removal of small transient mouth sounds - clicks, ticks, and lip smacks caused by saliva and tongue movement - from a dialogue recording, using dedicated mouth de-click processing or manual editing, while preserving natural speech transients such as plosives and consonant attacks.','Mouth declicking removes tiny clicks and lip smacks from speech. These come from spit and tongue moves between words. A special tool finds and lowers them. Real speech sounds still stay.','It cleans distracting mouth noise from close-miked dialogue and narration so lines sound polished, without dulling the real sounds of speech.','The editor runs a mouth de-click pass or hand-edits individual clicks, checking that word attacks and plosives remain intact.','Dialogue Cleanup',ARRAY['Mouth-noise cluster','Lip-smack suppression','Musical-noise artifact','Room tone','Handle preservation','Micro-comping']::text[],ARRAY['Setting de-click sensitivity so high that consonants and plosives get softened or lisped.','Trying to remove clicks with broadband noise reduction, which is meant for steady hiss, not transients.','Hand-editing a click without a crossfade, leaving a gap or a new click.']::text[],ARRAY['Cleaning a quiet, close-miked emotional scene where every mouth click is audible.','Polishing narration or voice-over that has dry-mouth clicks.','Prepping an actor''s ADR line for a clean mix.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d6721b01-5d27-53d1-8574-6987a16e9666' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mouth declicking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd6721b01-5d27-53d1-8574-6987a16e9666','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d6721b01-5d27-53d1-8574-6987a16e9666' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ea6ef766-52dd-5a26-bbff-e0bc8ec0eb07','Mouth-noise cluster','A group of mouth sounds - clicks, ticks, smacks, and saliva noises - occurring close together within a short span of dialogue, often before or between words, that reads as a dense burst rather than a single isolated click and usually needs concentrated cleanup.','This is a bunch of mouth clicks packed close together. They come in a short burst, not one at a time. A dry mouth or a pause before a line often causes them. They need extra cleanup.','Naming the pattern tells the editor to expect several clicks in one spot, so cleanup targets the whole burst instead of a single tick.','The editor treats the run with a mouth de-click pass or hand-edits each click, then fills any gaps with matching room tone.','Dialogue Cleanup',ARRAY['Mouth declicking','Lip-smack suppression','Room tone','Musical-noise artifact','Handle preservation']::text[],ARRAY['Removing only the loudest click and leaving the quieter ones in the cluster.','Over-processing the whole burst until the surrounding words sound dull and unnatural.','Cutting the cluster out completely and leaving a silent hole instead of room tone.']::text[],ARRAY['An actor with a dry mouth delivers a line after a long pause.','A close-miked whisper full of tongue and saliva clicks.','Prepping narration where clicks bunch up before each sentence.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ea6ef766-52dd-5a26-bbff-e0bc8ec0eb07' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mouth-noise cluster'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ea6ef766-52dd-5a26-bbff-e0bc8ec0eb07','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ea6ef766-52dd-5a26-bbff-e0bc8ec0eb07' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '780a90b1-3541-5fde-80c4-6806ea6f6b7e','Musical-noise artifact','An artifact produced by aggressive spectral noise reduction, heard as random chirpy, watery, or ''space-monkey'' tones left over after processing. It arises when statistical variations in the noise spectrum cause random triggering of the reducer''s sub-band gates, leaving isolated spectral fragments.','This is a chirpy, watery sound left behind by heavy noise removal. Cutting too much noise leaves tiny random tones. People call it musical noise. It sounds like faint bird chirps or bubbling.','Recognizing it warns the editor that the noise reduction is too strong, so they can back it off and keep the dialogue sounding natural.','The editor hears the chirps, then lowers the reduction amount or raises the artifact-smoothing control until the tones disappear.','Noise & Artifacts',ARRAY['Noise-print mismatch','Mouth declicking','Noise-floor stepping','Room tone','Noise-floor choreography']::text[],ARRAY['Pushing noise reduction hard to kill all hiss, which trades the hiss for chirpy musical noise.','Blaming the recording for the chirps instead of the over-aggressive processing that created them.','Adding more reduction to hide the artifact, which usually makes it worse.']::text[],ARRAY['Denoising a noisy location recording too aggressively.','Cleaning air-conditioner hiss from dialogue and hearing watery tones appear.','Comparing reduction settings to find the point where musical noise starts.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='780a90b1-3541-5fde-80c4-6806ea6f6b7e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Musical-noise artifact'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
