WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='780a90b1-3541-5fde-80c4-6806ea6f6b7e' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '654679ed-9445-59a4-a027-aac764eb0648','Noise-floor choreography','The deliberate planning and management of the background noise level (noise floor) across a scene so that it rises, falls, and transitions smoothly and believably, matching room tone and backgrounds to picture and edits rather than letting the floor jump abruptly.','This means planning how the background hiss and room sound change through a scene. The editor keeps the quiet background steady and smooth. It should shift naturally, never jump. It is like blending the base layer of sound.','It keeps the invisible bed of background sound consistent so cuts and cleanup do not draw attention to level changes in the quiet parts.','The editor lays matching room tone under lines and gaps, and rides levels so the background flows evenly from shot to shot.','Noise & Artifacts',ARRAY['Noise-floor stepping','Room tone','Noise-print mismatch','Musical-noise artifact','Overlap track']::text[],ARRAY['Cleaning each line in isolation so the background level jumps between clips.','Forgetting to fill gaps with room tone, leaving dead holes between lines.','Matching only loudness and ignoring the tone of the background from shot to shot.']::text[],ARRAY['Smoothing the background bed across a scene cut from several takes.','Blending a cleaned-up line back into a noisier surrounding scene.','Building continuous room tone under a dialogue sequence.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='654679ed-9445-59a4-a027-aac764eb0648' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Noise-floor choreography'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '654679ed-9445-59a4-a027-aac764eb0648','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='654679ed-9445-59a4-a027-aac764eb0648' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8f512c20-bbaa-5824-b6dd-70f415900c8e','Noise-floor stepping','An audible, abrupt jump in the level or character of the background noise (noise floor) at an edit point or processing boundary, where the quiet bed of sound steps up or down instead of remaining continuous. It is a common giveaway of an unsmoothed dialogue edit.','This is when the background hiss suddenly jumps at a cut. One clip is quiet, the next is louder. The step makes the edit obvious. Matching room tone hides it.','Spotting it tells the editor that clips or processed sections do not match, so they can fill or level the background to hide the seam.','The editor patches the join with matching room tone, adjusts levels, or crossfades so the background does not jump at the cut.','Noise & Artifacts',ARRAY['Noise-floor choreography','Room tone','Noise-print mismatch','Crossfade','Musical-noise artifact']::text[],ARRAY['Cutting between takes with different backgrounds and not filling the gap with room tone.','Denoising only some clips in a scene, so the treated ones step below the untreated ones.','Using a hard cut with no crossfade where the background level changes.']::text[],ARRAY['Intercutting two takes recorded with different air-handling noise.','A cleaned line dropping to near silence next to a noisy untouched line.','Joining a studio ADR line to a noisy production line.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8f512c20-bbaa-5824-b6dd-70f415900c8e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Noise-floor stepping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8f512c20-bbaa-5824-b6dd-70f415900c8e','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8f512c20-bbaa-5824-b6dd-70f415900c8e' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dafd271c-fb6b-5cfc-847e-81ca949d0d98','Noise-print mismatch','A condition in spectral noise reduction where the captured noise profile (noise print) does not accurately represent the noise actually present in the section being processed - because the noise changed, or the print was taken from the wrong spot - leading to incomplete reduction or added artifacts such as musical noise.','A noise print is a sample of the background the tool learns to remove. A mismatch means that sample does not match the real noise. So the tool misses some noise or adds chirps. You then grab a fresh, matching sample.','Understanding it tells the editor to capture a fresh noise print from the same conditions, so the reducer removes the right noise cleanly.','The editor re-learns the noise print from a quiet spot in the same shot, or splits the scene and prints each section separately.','Noise & Artifacts',ARRAY['Musical-noise artifact','Noise-floor stepping','Noise-floor choreography','Room tone','Mouth declicking']::text[],ARRAY['Using one noise print for a whole reel when the background changes between shots.','Capturing the print from a section that has faint dialogue or effects in it.','Pushing reduction harder to compensate for a bad print instead of re-learning it.']::text[],ARRAY['Denoising a scene where the room tone differs shot to shot.','Reusing an old noise print on a new location that sounds different.','Re-learning the profile after the air conditioning turns on mid-scene.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dafd271c-fb6b-5cfc-847e-81ca949d0d98' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Noise-print mismatch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dafd271c-fb6b-5cfc-847e-81ca949d0d98','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dafd271c-fb6b-5cfc-847e-81ca949d0d98' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '82638692-cec5-5881-8de8-102c084b0360','Overlap track','A separate editing track used to hold overlapping dialogue - words from one character that run under or across another''s lines, or a line that laps over a picture cut - kept off the main dialogue line so each part can be edited, level-matched, and mixed independently.','When two people talk at once, their lines cross over. The editor puts the extra line on its own track. That track is the overlap track. It keeps each voice separate to edit and mix.','It separates crossing lines so the editor can clean, sync, and balance each voice without one edit disturbing the other.','During prep the editor moves overlapping words or lapped lines onto dedicated overlap tracks, keeping handles and room tone with them.','Editorial Workflow',ARRAY['Microphone splitting','Handle preservation','Room tone','Crossfade','Lav lane','Mix-track guide']::text[],ARRAY['Leaving overlapping lines on one track, so trimming one voice cuts into the other.','Not carrying room tone and handles onto the overlap track, leaving gaps at the joins.','Losing sync when moving a lapped line to another track.']::text[],ARRAY['Two characters interrupting each other in an argument.','A line that continues across a cut to the next shot.','Splitting a group scene so each speaker sits on its own track.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='82638692-cec5-5881-8de8-102c084b0360' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Overlap track'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '82638692-cec5-5881-8de8-102c084b0360','47e2b509-c540-4a23-839c-c7190b673899',true
