INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '45560cf1-7ba6-5e87-bcec-451618abe284','PFX','Production effects - the incidental, non-verbal sound events captured on the production dialogue recording along with the dialogue, such as footsteps, door slams, prop handling, chair squeaks, and glass clinks. They are the ''events without words'' living in the production tracks that are handled separately from the spoken lines.','PFX means production effects. These are real sounds caught with the dialogue on set. Think footsteps, a door slam, or a cup set down. They are the non-speech sounds in the recording.','Identifying production effects lets the editor keep useful real-world sounds and manage them separately, which matters for both the mix and for foreign-language versions.','The editor marks and splits production effects off the dialogue tracks so they can be kept, cleaned, or replaced for the effects and music-and-effects deliverables.','Production Effects',ARRAY['PFX extraction','PFX isolation','PFX continuity','PFX marriage','Room tone','Overlap track']::text[],ARRAY['Deleting a useful production effect that would have been hard to recreate later.','Treating a loud prop sound like dialogue noise and processing it out by accident.','Forgetting that production effects are needed for the M&E (music and effects) version.']::text[],ARRAY['A door slam that happens right as a character speaks.','Footsteps and prop sounds recorded on the boom during a scene.','Preparing tracks for a foreign-language (M&E) delivery.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='45560cf1-7ba6-5e87-bcec-451618abe284' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('PFX'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '45560cf1-7ba6-5e87-bcec-451618abe284','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='45560cf1-7ba6-5e87-bcec-451618abe284' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cf5222b8-323c-51dc-9487-67300adfd323','PFX continuity','The consistency of production effects across an edited scene, so that recurring or ongoing effects - footsteps, ambient prop sounds, a running engine - stay smooth and believable from shot to shot rather than jumping, dropping out, or changing character at cuts.','This means keeping production sounds steady across cuts. Footsteps or a door should not jump or vanish at an edit. The editor fills and matches them. The scene then sounds seamless.','It keeps the real-world sounds of a scene flowing naturally so edits do not expose gaps or level jumps in the effects.','The editor fills missing effect moments from handles or alternate takes and matches their level and tone so the effects carry continuously through the scene.','Production Effects',ARRAY['PFX','PFX extraction','PFX isolation','PFX marriage','Noise-floor stepping','Room tone']::text[],ARRAY['Cutting to a take where a footstep or prop sound suddenly disappears.','Matching dialogue level but ignoring a jump in the background effects.','Removing an effect from one shot but leaving it in the next, breaking continuity.']::text[],ARRAY['Keeping footsteps consistent across a walk-and-talk cut from many takes.','Holding a steady prop or machine sound through a scene''s edits.','Smoothing a door or car effect that laps across a picture cut.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cf5222b8-323c-51dc-9487-67300adfd323' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('PFX continuity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cf5222b8-323c-51dc-9487-67300adfd323','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cf5222b8-323c-51dc-9487-67300adfd323' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3663afee-a318-5bb8-ace2-bc43daaf6038','PFX extraction','The process of pulling a production effect out of the production dialogue recording - copying or moving the effect onto its own track - so it can be preserved, cleaned, or delivered separately, especially for building the music-and-effects (M&E) mix used in foreign-language versions.','This means taking a real sound out of the dialogue recording. The editor copies it to its own track. Then it can be cleaned or used alone. This matters most for foreign-language versions.','It saves useful real-world sounds and makes them available for the effects mix and the M&E version, where the dialogue is removed but the effects must remain.','The editor isolates the effect from the dialogue clip, moves it to an effects track, and fills the dialogue track behind it with matching room tone.','Production Effects',ARRAY['PFX','PFX isolation','PFX marriage','PFX continuity','Room tone','Handle preservation']::text[],ARRAY['Extracting the effect but leaving a silent gap in the dialogue track instead of room tone.','Cutting so tightly that part of the effect is lost or a word is clipped.','Extracting an effect that is married to dialogue and cannot be cleanly separated.']::text[],ARRAY['Pulling a gunshot off the dialogue track for the effects stem.','Preparing production effects for an M&E (music and effects) delivery.','Moving a prop sound onto its own track for the mixer.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3663afee-a318-5bb8-ace2-bc43daaf6038' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('PFX extraction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3663afee-a318-5bb8-ace2-bc43daaf6038','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3663afee-a318-5bb8-ace2-bc43daaf6038' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '592c9515-ae6e-5e4b-82ba-a4b70f7e9d19','PFX isolation','Separating a production effect from the surrounding dialogue and background so it stands alone on its own track or region, allowing it to be edited, processed, level-matched, or muted independently of the spoken lines.','This means getting a real sound on its own, away from the talking. The editor puts it alone on a track. Then they can treat just that sound. It does not affect the dialogue.','It gives the editor and mixer independent control of a production effect so it can be shaped or removed without touching the dialogue.','The editor splits the effect onto a dedicated track, often choosing the cleanest microphone source, so it can be handled on its own at the mix.','Production Effects',ARRAY['PFX','PFX extraction','PFX marriage','PFX continuity','Microphone splitting','Overlap track']::text[],ARRAY['Assuming every effect can be fully isolated when it overlaps the dialogue.','Not choosing the cleanest microphone source when isolating the effect.','Isolating the effect but losing sync with the picture.']::text[],ARRAY['Isolating a door slam so it can be timed to the picture.','Splitting a prop sound from dialogue for separate EQ at the mix.','Putting a footstep on its own track to raise it in the effects mix.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='592c9515-ae6e-5e4b-82ba-a4b70f7e9d19' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('PFX isolation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '592c9515-ae6e-5e4b-82ba-a4b70f7e9d19','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='592c9515-ae6e-5e4b-82ba-a4b70f7e9d19' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b83407bb-5d92-5621-8af3-bb140affb10c','PFX marriage','The condition in which a production effect is inseparably combined with dialogue in the same recording - the effect and the words occur at the same time on the same microphone - so the effect cannot be cleanly removed or delivered on its own. Married effects complicate M&E preparation because removing the dialogue also removes the effect, which must then be recreated.','A married effect is a real sound stuck on top of the words. They happen at the same moment on the same mic. You cannot pull them apart cleanly. For foreign versions, the sound has to be remade.','Recognizing a married effect warns the editor that it cannot simply be split off, so the effect will need to be recreated with Foley or a library sound for the music-and-effects mix.','The editor flags the married moment, and the sound team rebuilds that effect separately so the music-and-effects version still has it after the dialogue is removed.','Production Effects',ARRAY['PFX','PFX extraction','PFX isolation','PFX continuity','Room tone','Handle preservation']::text[],ARRAY['Assuming a married effect can be extracted cleanly when the words sit right on top of it.','Deleting a married effect with the dialogue and forgetting it must be replaced for M&E.','Leaving a married effect out of the M&E notes, so the foreign version loses the sound.']::text[],ARRAY['A slap that lands exactly on a shouted line.','A prop sound buried under a spoken word on the same boom.','Preparing M&E where a married effect must be recreated with Foley.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b83407bb-5d92-5621-8af3-bb140affb10c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('PFX marriage'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b83407bb-5d92-5621-8af3-bb140affb10c','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b83407bb-5d92-5621-8af3-bb140affb10c' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dbeb1423-4478-52fc-a02c-76198c7c2124','PFX pull','The dialogue editor''s task of isolating usable non-dialogue sounds (footsteps, prop handling, doors, clothing, impacts) captured on the production sound tracks and copying them onto dedicated production-effects (PFX) tracks. These pulled sounds stay in sync with picture so they remain available for the final mix and for M&E (music and effects) versions when the original dialogue is replaced.','Production sound records more than voices. It also catches footsteps, doors, and props. A PFX pull is when the editor copies those useful sounds onto their own tracks. PFX means production effects.','It preserves incidental sounds recorded live with the dialogue so they can be reused in the mix, and it supplies effects for foreign-language (M&E) versions where the spoken dialogue is swapped out.','While cleaning dialogue tracks, the editor spots a good door slam or footstep on the production recording and copies it to a labeled PFX track for the mixer and the M&E deliverable.','Dialogue Editing Workflow',ARRAY['PFX sweetener','Room tone','M&E stem','Production sound','Foley']::text[],ARRAY['Pulling effects that contain audible dialogue or dialogue bleed, which then cannot be used in an M&E version','Losing sync with picture so the pulled effect no longer matches the on-screen action','Leaving pulled effects on the dialogue tracks instead of routing them to dedicated PFX tracks']::text[],ARRAY['Building an M&E (music and effects) stem for a foreign-language release','Preserving a well-recorded prop sound that Foley could not reproduce convincingly','Handing organized PFX tracks to the re-recording mixer before the final dub']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dbeb1423-4478-52fc-a02c-76198c7c2124' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('PFX pull'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dbeb1423-4478-52fc-a02c-76198c7c2124','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dbeb1423-4478-52fc-a02c-76198c7c2124' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4cb899d6-7ffa-52de-9999-ee8796e89f46','PFX sweetener','A production effect (a non-dialogue sound captured on the production tracks) used to reinforce or sweeten a designed effect or Foley cue in the mix, adding realism or detail rather than standing alone as the primary sound.','A sweetener is an extra sound layered under a main sound to make it richer. A PFX sweetener uses a real sound from the set for this. PFX means production effects.','It lets the mix borrow the authentic character of a location-recorded sound to thicken or add believability to a Foley or effects layer without replacing it.','A sound editor layers a real on-set glass clink from the production track under a cleaner library or Foley effect so the moment feels genuine.','Dialogue Editing Workflow',ARRAY['PFX pull','Foley','Room tone','Production sound','Sound effects editing']::text[],ARRAY['Making the sweetener as loud as the main effect instead of letting it sit beneath','Using a sweetener that still contains dialogue, making it unusable in an M&E version','Layering so many sweeteners that the sound becomes cluttered and unnatural']::text[],ARRAY['Adding an authentic on-set footstep under a Foley footstep for extra weight','Reinforcing a designed door effect with the real door sound from the production track','Giving a restaurant scene added realism from genuine location ambience']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4cb899d6-7ffa-52de-9999-ee8796e89f46' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('PFX sweetener'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4cb899d6-7ffa-52de-9999-ee8796e89f46','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4cb899d6-7ffa-52de-9999-ee8796e89f46' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8a4d6b0e-5c74-5231-abd6-8e9a4ccfadac','Palatal click','A short, sharp mouth-noise transient produced when the tongue separates from the hard palate (the roof of the mouth), often aided by saliva. In dialogue editing it is treated as an unwanted click within speech that is reduced or removed during cleanup.','It is a tiny click made when the tongue peels off the roof of the mouth. Saliva can make it worse. Editors remove these clicks so speech sounds clean.','Naming the click by where it forms helps the editor find and remove distracting mouth noise so the dialogue sounds clear and professional.','Zooming into the waveform between words, the editor finds a saliva click and repairs it by hand or with a mouth de-click tool.','Audio Artifact',ARRAY['Mouth click','Lip smack','De-click','Sibilance','Room tone']::text[],ARRAY['Removing so many clicks that consonants like t and k lose their natural attack','Deleting the click and leaving a silent gap instead of filling it with room tone','Over-processing with a de-click tool, which can dull or smear the surrounding words']::text[],ARRAY['Cleaning a quiet, close-mic voiceover where mouth noises are very audible','Preparing an actor''s intimate dialogue for a scene with little background sound','Repairing clicks before dialogue goes to the re-recording mixer']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8a4d6b0e-5c74-5231-abd6-8e9a4ccfadac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Palatal click'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8a4d6b0e-5c74-5231-abd6-8e9a4ccfadac','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8a4d6b0e-5c74-5231-abd6-8e9a4ccfadac' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'da922e32-fada-5379-8a27-08a0334bb7e9','Parking track','A track, or a muted region within a session, used to temporarily hold audio takes, alternates, or removed clips that are not in the active edit but that the editor wants to keep readily accessible for later reference or reuse.','A parking track is a spare track for holding clips you are not using yet. You park takes there so they are easy to grab later. Nothing on it plays in the mix.','It keeps alternate takes and outtakes organized and within reach without cluttering the active edit or forcing the editor to re-import material later.','When choosing between takes, the editor drags the rejected but promising options onto a muted parking track in case the director asks to hear them again.','Session Organization',ARRAY['Performance comping','Alternate take','Playlist','Handles']::text[],ARRAY['Leaving a parking track unmuted so stray clips play in the mix','Failing to label parked clips, making them impossible to identify later','Deleting parked alternates too early, before the edit is locked']::text[],ARRAY['Storing runner-up takes during a dialogue comp for quick recall','Holding trimmed clips off to the side while reconforming to a new picture cut','Keeping alternate line readings available for the director''s review']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='da922e32-fada-5379-8a27-08a0334bb7e9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Parking track'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'da922e32-fada-5379-8a27-08a0334bb7e9','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='da922e32-fada-5379-8a27-08a0334bb7e9' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'da3261eb-046e-5f29-8b5e-4ad464f9989b','Performance comping','The practice of assembling a single, seamless performance by selecting and joining the best portions from multiple takes of the same line or scene, cutting at word, syllable, or breath boundaries so the composite sounds like one continuous delivery.','Actors record a line several times. Comping means picking the best bits from each take. The editor joins them into one smooth performance. The joins should be invisible.','It delivers the strongest possible performance from the available takes, fixing weak moments, flubs, or noise by borrowing better readings from other takes.','The editor cuts the first half of one take together with the stronger second half of another, matching level and tone so the seam is inaudible.','Dialogue Editing Workflow',ARRAY['Parking track','Phoneme patching','Alternate take','ADR','Playlist']::text[],ARRAY['Cutting between takes where the room tone or level does not match, exposing the edit','Comping across takes with different mic perspective, causing a perspective jump','Choosing takes for technical cleanliness over the best acting performance']::text[],ARRAY['Combining the best line readings from several circled takes','Replacing a coughed or stumbled word with a clean version from another take','Building a final dialogue performance before the mix']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='da3261eb-046e-5f29-8b5e-4ad464f9989b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Performance comping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'da3261eb-046e-5f29-8b5e-4ad464f9989b','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='da3261eb-046e-5f29-8b5e-4ad464f9989b' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '04fc676c-3364-58be-b55e-82dbf31582d1','Perspective discontinuity','An audible mismatch in acoustic perspective, meaning microphone distance, room reflections, and off-axis tone, between adjacent shots or edits, so that a character''s voice seems to jump in apparent distance or space across a cut.','Perspective is how close or far a voice sounds. If it changes suddenly at a cut, the scene feels wrong. This mismatch is called a perspective discontinuity. Editors smooth it out.','Identifying it lets the editor match tone and space across cuts so dialogue feels like it comes from one consistent room, keeping the audience inside the scene.','When a close lav shot cuts to a distant boom shot, the editor equalizes and adds matching room tone, or chooses a better take, to hide the shift.','Audio Artifact',ARRAY['Perspective','Room tone','Boom','Lavalier','Equalization']::text[],ARRAY['Cutting between boom and lav takes without matching their tone or distance','Ignoring background level changes that make the perspective jump obvious','Fixing tone but forgetting to match reverb or room sound between shots']::text[],ARRAY['A wide shot cutting to a close-up where the voice suddenly sounds much nearer','Intercutting boom and lavalier microphones within the same conversation','Matching dialogue perspective before handing tracks to the mixer']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='04fc676c-3364-58be-b55e-82dbf31582d1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Perspective discontinuity'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '04fc676c-3364-58be-b55e-82dbf31582d1','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='04fc676c-3364-58be-b55e-82dbf31582d1' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9d5eeef7-0660-5d9b-add7-7694eb436a4c','Phasey speech','Dialogue that sounds hollow, thin, or comb-filtered because two correlated versions of the same voice, typically a boom and a lavalier, or a direct and a reflected path, are summed with a small time offset, producing frequency-dependent phase cancellation.','When two mics catch the same voice a moment apart, mixing them cancels some tones. This makes speech sound hollow or thin. That thin sound is called phasey speech.','Recognizing the phasey quality tells the editor to correct the timing relationship or favor one microphone, restoring full, natural-sounding dialogue.','Hearing a hollow tone when boom and lav are blended, the editor time-aligns the two tracks or mutes one to remove the cancellation.','Audio Artifact',ARRAY['Comb filtering','Phase cancellation','Boom','Lavalier','Perspective discontinuity']::text[],ARRAY['Blending boom and lav without time-aligning them, causing comb filtering','Trying to fix phasiness with EQ alone instead of correcting the timing','Summing both mics when one clean microphone would sound fuller']::text[],ARRAY['Combining boom and lavalier tracks of the same actor','Strong room reflections mixing with the direct sound in a hard-surfaced location','Diagnosing why blended dialogue sounds hollow before the mix']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9d5eeef7-0660-5d9b-add7-7694eb436a4c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Phasey speech'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9d5eeef7-0660-5d9b-add7-7694eb436a4c','47e2b509-c540-4a23-839c-c7190b673899',true
