INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'afef26f3-18b4-5dfd-a9b3-4e96b9b74635','Phoneme patching','A fine dialogue-editing technique that repairs a word by replacing or inserting a single phoneme, an individual speech sound such as a consonant or vowel, borrowed from another take or another word, so a mispronounced, dropped, or damaged sound is corrected while the rest of the word is preserved.','Words are made of small sounds called phonemes. Phoneme patching swaps in one clean sound to fix a word. It is like fixing one letter instead of the whole word.','It lets the editor salvage an otherwise perfect take by fixing a single flawed sound, avoiding a full re-record (ADR) of the line.','To repair a swallowed t at the end of a word, the editor drops in a clean t from another take and matches its level and tone.','Dialogue Repair',ARRAY['Performance comping','Plosive reconstruction','ADR','Sibilance','Crossfade']::text[],ARRAY['Patching a phoneme from a take with different pitch or pace, so it sounds unnatural','Placing the edit inside a vowel, where the join is easy to hear, instead of at a consonant','Forgetting a short crossfade, leaving an audible click at the splice']::text[],ARRAY['Fixing a dropped consonant that made a word unclear','Correcting a mild mispronunciation without full ADR','Rebuilding a word partly masked by an on-set noise']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='afef26f3-18b4-5dfd-a9b3-4e96b9b74635' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Phoneme patching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
