INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '99d5fc14-e68e-5bae-b45c-a71e0d90cce7','Picture reconform','The process of updating an in-progress sound edit to match a revised version of the picture, using a change list or a comparison of edit decision lists (EDLs) to automatically shift, trim, insert, or remove sections so existing dialogue edits realign to the new cut without redoing the work.','Picture editors keep changing the cut, even after lock. Reconforming moves the sound edits to match the new picture. A change list tells the tools exactly what moved.','It keeps completed dialogue editing in sync when the picture changes, saving the editor from manually finding and moving every affected edit.','Given a new cut and a change list, the editor runs a reconform tool that compares the old and new EDLs and repositions the tracks to match.','Post Workflow',ARRAY['Conform','EDL','Handles','Timecode','Picture lock']::text[],ARRAY['Reconforming without enough handles, so extended edits run out of usable audio','Trusting the change list blindly and not checking sync by ear afterward','Failing to back up the old session before applying the reconform']::text[],ARRAY['A director recuts a scene after audio post has already begun','Matching sound to a new picture version delivered mid-schedule','Comparing two EDLs to build a list of picture changes before updating tracks']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='99d5fc14-e68e-5bae-b45c-a71e0d90cce7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Picture reconform'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '99d5fc14-e68e-5bae-b45c-a71e0d90cce7','47e2b509-c540-4a23-839c-c7190b673899',true
