INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b14174ce-7ae6-5191-8e76-943017785908','Plant lane','A dedicated track or playlist lane in the editing session reserved for dialogue captured by plant microphones, which are mics hidden in the set, kept separate from boom and lavalier sources so their distinct perspective and tone can be managed independently.','A plant mic is hidden in the set to catch dialogue. A plant lane is a track just for those mics. Keeping them separate makes them easier to balance and fix.','It organizes plant-mic dialogue on its own lane so the editor and mixer can route, balance, and process that source separately from other microphones.','The editor sorts each actor''s coverage by source, placing all hidden plant-mic takes on their own labeled lane for the mixer.','Session Organization',ARRAY['Plant mic','Boom','Lavalier','Split tracks','Perspective']::text[],ARRAY['Mixing plant-mic clips onto the boom track, hiding their different perspective','Not labeling the lane, so the mixer cannot tell the source apart','Ignoring that plant mics often need their own EQ and level treatment']::text[],ARRAY['Organizing a scene that used a mic hidden in a car dashboard','Separating plant-mic coverage for a wide shot where booming was impossible','Delivering source-sorted tracks so the mixer can choose the best microphone']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b14174ce-7ae6-5191-8e76-943017785908' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Plant lane'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b14174ce-7ae6-5191-8e76-943017785908','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b14174ce-7ae6-5191-8e76-943017785908' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0f574909-5523-5a8c-bef7-982def3090d0','Plosive reconstruction','The repair of a plosive consonant (such as p, b, t, d, k, or g) whose burst was clipped, distorted, over-reduced by de-plosive processing, or lost, done by editing in a clean plosive from another take or reshaping the transient so the word reads naturally.','Plosives are punchy sounds like p and t. Sometimes they get damaged or removed by accident. Plosive reconstruction rebuilds that sound so the word sounds normal again.','It restores the natural attack and intelligibility of a word after a plosive has been damaged or over-processed, avoiding a full re-record.','After de-plosive processing dulls a p, the editor grafts a clean p burst from another take and blends its level and tone.','Dialogue Repair',ARRAY['Plosive','De-plosive','Phoneme patching','Crossfade','Transient']::text[],ARRAY['Over-using de-plosive first, then having to rebuild the plosive that was destroyed','Borrowing a plosive from a take with different pitch or pace, so it sounds pasted in','Skipping a short crossfade and leaving a click at the join']::text[],ARRAY['Fixing a p or b flattened by aggressive plosive removal','Rebuilding a consonant lost to a microphone overload','Restoring word clarity before the dialogue premix']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0f574909-5523-5a8c-bef7-982def3090d0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Plosive reconstruction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0f574909-5523-5a8c-bef7-982def3090d0','47e2b509-c540-4a23-839c-c7190b673899',true
