INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '87df836e-cf09-5d8e-a285-94127dc312da','Post-cut fill','A short piece of matching room tone or ambience placed immediately after an edit point to fill the gap left by a cut, so the background stays continuous and the splice does not create an audible hole or level drop in the dialogue track.','Every cut can leave a silent hole in the background. Post-cut fill drops matching room tone right after the cut. This keeps the background smooth so the edit stays hidden.','It maintains a seamless background across edits by patching the gap after a cut, preventing the sudden silence that would reveal the join.','After trimming a line, the editor lays room tone from the same setup over the space right after the cut and crossfades it in.','Dialogue Editing Workflow',ARRAY['Room tone','Fill','Crossfade','Handles','Perspective discontinuity']::text[],ARRAY['Using room tone from a different location, so the fill does not match the scene','Butting the fill without a crossfade, creating a click or a bump at the edit','Leaving a silent gap after the cut, which makes the edit obvious']::text[],ARRAY['Smoothing the background after removing a stumble or noise from a line','Filling the gap left when tightening the pause between two lines','Bridging a cut between two takes that have slightly different backgrounds']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='87df836e-cf09-5d8e-a285-94127dc312da' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Post-cut fill'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '87df836e-cf09-5d8e-a285-94127dc312da','47e2b509-c540-4a23-839c-c7190b673899',true
