INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c5076ca9-c4a6-5905-a16e-95c47ea456f3','Pre-action fill','Room tone or matched background ambience laid into the timeline at the head of a scene, covering the period before the action or first line of dialogue begins, so the ambient bed runs continuously from the moment the picture cuts in rather than starting abruptly with the first recorded sound.','It is quiet background sound placed before the action starts. It fills the gap so the scene does not begin with dead silence.','It establishes a continuous, natural-sounding ambient bed from the first frame of a scene, preventing an abrupt or silent start before dialogue or action arrives.','A dialogue editor drops matching room tone across the head of a scene so the background does not pop on with the first word or footstep.','Fill & Room Tone',ARRAY['Room tone','Fill','Reversed fill','Room-tone contouring','Handles','Production sound roll']::text[],ARRAY['Starting the fill exactly at the first line instead of before it, so the background snaps on audibly.','Using room tone from a different location or microphone, so the pre-action bed does not match the scene.','Leaving a true-silence gap at the head of the scene, which sounds unnatural on a real location.']::text[],ARRAY['Building the head of a scene where the camera holds on a room before anyone speaks.','Bridging from a hard picture cut into a quiet interior before the first line.','Underpinning a slow scene opening so the ambience is present before action begins.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c5076ca9-c4a6-5905-a16e-95c47ea456f3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pre-action fill'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c5076ca9-c4a6-5905-a16e-95c47ea456f3','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c5076ca9-c4a6-5905-a16e-95c47ea456f3' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9b35a8b1-be1d-5f4d-ae1c-54877be5dd16','Production dialogue pull','The task of selecting and extracting usable dialogue takes, alternate reads, and individual words or syllables from the recorded production sound rolls and transferring them into the edit for assembly, so the cleanest and best-performing production material is available to the dialogue editor.','It means picking the best spoken lines from what was recorded on set. The editor pulls those takes out to use them in the edit.','It gathers the strongest and cleanest production dialogue from all recorded takes so the editor can build the smoothest, most intelligible track before any replacement dialogue is considered.','An editor scrubs through the day''s takes, marks the best reads and alternates, and pulls them onto dialogue tracks against picture.','Dialogue Workflow',ARRAY['Production sound roll','Alternate take','Sound report','Fill','ADR','Safety dialogue track']::text[],ARRAY['Pulling only the circled take and ignoring alternates that could fix a noisy or misspoken word.','Ignoring the sound report notes, so a flagged noisy take gets pulled instead of a clean one.','Pulling audio without preserving sync to picture, forcing a costly re-sync later.']::text[],ARRAY['Preparing dialogue tracks at the start of a picture-edit conform.','Finding a clean alternate word to replace one ruined by an off-camera noise.','Assembling coverage from multiple takes to match the picture-cut performance.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9b35a8b1-be1d-5f4d-ae1c-54877be5dd16' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Production dialogue pull'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9b35a8b1-be1d-5f4d-ae1c-54877be5dd16','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9b35a8b1-be1d-5f4d-ae1c-54877be5dd16' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f1961cab-be11-5384-8415-e314453595d0','Production sound roll','A discrete, numbered unit of production sound recordings, historically a single tape reel and now a group of files logged under one roll number, typically per recording device per shooting day, used to organize and reference location audio in sound reports and post-production.','It is one numbered batch of the sound recorded on set. Each roll groups files together so they are easy to find later.','It organizes location recordings into trackable numbered units so post-production can locate any take quickly and cross-reference it against the sound report.','An editor uses the roll number and timecode from the sound report to find and import the exact take recorded on set.','Production Media',ARRAY['Sound report','Timecode','Production dialogue pull','Metadata','Broadcast WAV']::text[],ARRAY['Confusing the sound roll number with the camera roll or the scene number.','Importing from the wrong roll because the sound report was not checked.','Assuming one roll equals one scene, when a roll can span many scenes and takes.']::text[],ARRAY['Locating a specific take by roll and timecode during the dialogue pull.','Reconciling delivered media against the sound report roll list.','Tracing a sync problem back to the original production roll.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f1961cab-be11-5384-8415-e314453595d0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Production sound roll'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
