WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f1961cab-be11-5384-8415-e314453595d0' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '44e3196f-333c-5ee6-8c4c-4ebf4002f1a6','RF hash','Continuous broadband radio-frequency interference picked up by a wireless microphone system and demodulated into the audio band, heard as a persistent hissy, swishing, or frying noise layered over the recorded dialogue.','It is a steady frying or hissing noise from radio interference. A wireless mic can pick it up and add it under the voice.','Naming this fault helps editors and mixers identify continuous radio interference as the cause of a hiss under dialogue, so the right repair or replacement decision follows.','When a mixer or editor hears a constant frying hiss on a radio-mic track, they recognize RF hash and switch to a cleaner boom or plan replacement dialogue.','RF Artifacts',ARRAY['RF spit','Dropout','Wireless microphone','Diversity reception','Boom track','Squelch']::text[],ARRAY['Mistaking RF hash for normal preamp hiss and boosting it further with noise reduction.','Blaming the microphone capsule when the fault is radio interference on the wireless link.','UNSAFE: Raising monitoring level to hear detail under the hash for long periods, risking hearing damage; keep monitoring within OSHA hearing-exposure limits.']::text[],ARRAY['Diagnosing a constant hiss on a lav track shot near broadcast transmitters.','Deciding between a hashy radio mic and a clean boom for the final track.','Flagging an unusable take caused by wireless interference on set.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='44e3196f-333c-5ee6-8c4c-4ebf4002f1a6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('RF hash'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '44e3196f-333c-5ee6-8c4c-4ebf4002f1a6','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='44e3196f-333c-5ee6-8c4c-4ebf4002f1a6' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '32f9f432-9fdd-5e93-8a1f-ab261a4de5ef','RF spit','Short, intermittent bursts of radio-frequency interference or momentary dropout artifacts on a wireless microphone recording, heard as crackles, ticks, or spitting sounds punctuating the dialogue, as distinct from the continuous noise of RF hash.','It is short crackle or spitting sounds from radio interference. A wireless mic makes these little bursts when the signal breaks up.','The term lets editors pinpoint brief radio glitches on a radio-mic track so they can patch them from alternates or repair them individually.','An editor spots and repairs or replaces the crackling syllables caused by RF spit, often pulling a clean word from another take.','RF Artifacts',ARRAY['RF hash','Dropout','Wireless microphone','De-click','Alternate take','Boom track']::text[],ARRAY['Treating RF spit as mouth clicks and de-clicking the whole line unnecessarily.','Trying to smooth a dropout with fades instead of replacing the damaged word.','Not checking the boom or a safety track for a clean version of the spit-damaged moment.']::text[],ARRAY['Repairing occasional crackles on a lav caused by antenna shadowing.','Choosing between de-clicking and replacing a spit-damaged word.','Flagging intermittent wireless glitches during the dialogue pull.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='32f9f432-9fdd-5e93-8a1f-ab261a4de5ef' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('RF spit'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '32f9f432-9fdd-5e93-8a1f-ab261a4de5ef','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='32f9f432-9fdd-5e93-8a1f-ab261a4de5ef' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '45da2700-4bcb-59ea-8970-304140ecdac2','Reference production','Production dialogue kept as a sync and performance reference, a guide track, so that replacement lines can be matched to the original timing, delivery, and lip-sync, even when the production recording itself is too noisy or damaged to use in the final mix.','It is the on-set voice recording kept as a guide. Editors use it to match new lines to the original timing and lip movements, even if it sounds bad.','It preserves the original performance and sync as a benchmark so replacement dialogue can be timed and delivered to match what was shot.','When production sound is unusable, the editor still keeps it muted under the replacement lines as a reference to line up timing and lip-sync.','Dialogue Workflow',ARRAY['ADR','Guide track','Production dialogue pull','Lip sync','Production sound roll']::text[],ARRAY['Deleting the noisy production track instead of muting it and keeping it as a sync reference.','Assuming a reference track must be broadcast-clean, when its only job is timing and performance.','Losing sync by removing the reference before replacement dialogue is fully fitted.']::text[],ARRAY['Guiding replacement-dialogue timing when the location recording is too noisy to use.','Matching a replacement word''s delivery to the original on-set read.','Checking lip-sync of edited dialogue against the original production take.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='45da2700-4bcb-59ea-8970-304140ecdac2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reference production'),'[^a-z0-9]','','g'));
