INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0395d9b6-7690-5947-8774-84a97fc51330','Residual plosive','A low-frequency burst from a plosive consonant such as p, b, t, or k that remains audible in a dialogue recording after de-plosive processing, high-pass filtering, or EQ has been applied, appearing as a leftover thump or pop in the low end.','It is a leftover popping thump on hard letters like ''p'' and ''b''. It stays in the recording even after you try to remove it.','Identifying a residual plosive tells the editor that further targeted low-frequency repair is needed, rather than more broadband filtering that would thin the voice.','An editor spots a leftover ''p'' pop and treats just that moment with a spectral repair or short low-cut instead of filtering the whole line.','Dialogue Repair',ARRAY['Plosive','High-pass filter','De-plosive','Spectral repair','Windscreen','Room-tone pumping']::text[],ARRAY['Applying a heavy high-pass across the whole line, thinning the voice just to kill one pop.','Confusing a residual plosive with a low rumble or handling noise.','Ignoring the plosive until the mix, where it can overload the low end and monitors.']::text[],ARRAY['Cleaning close-mic dialogue where the windscreen did not stop every pop.','Repairing a single ''b'' thump left after de-plosive processing.','Preparing a line for the mix so plosives do not spike the low frequencies.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0395d9b6-7690-5947-8774-84a97fc51330' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Residual plosive'),'[^a-z0-9]','','g'));
