INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7f4976e6-898c-59e0-9267-afb5d40eb37a','Restoration chirp','A short tonal artifact, also called musical noise or a birdie, introduced by spectral noise-reduction or restoration processing, produced when random variations in the noise spectrum cause sub-band gates to trigger erratically, leaving isolated warbling tones over the dialogue.','It is a small warbling or chirping sound left by noise removal. Cleaning tools can add these fake tones when pushed too hard.','Recognizing restoration chirp warns the editor that noise reduction is set too aggressively, so settings can be eased before the artifact reaches the mix.','When an editor hears watery chirps after de-noising, they back off the reduction or raise artifact-control settings, trading the chirps for a slightly higher noise floor.','Dialogue Repair',ARRAY['Spectral de-noise','Musical noise','Noise floor','Voice de-noise','Room-tone pumping']::text[],ARRAY['Pushing noise reduction until the background is gone but the dialogue chirps.','Adding more reduction to fix the chirps, which usually makes them worse.','UNSAFE: Monitoring restoration passes at high volume for long stretches, risking hearing damage; keep levels within OSHA hearing-exposure limits.']::text[],ARRAY['De-noising an air-conditioner hum from an interior dialogue scene.','Balancing reduction depth against artifacts on a noisy exterior lav.','Checking a cleaned line on speakers and headphones for warbling tones.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7f4976e6-898c-59e0-9267-afb5d40eb37a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Restoration chirp'),'[^a-z0-9]','','g'));
