INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bdea0188-acc4-583e-80b2-5da45d5d7eb2','Reversed fill','A section of room-tone or ambience fill that is played backwards, or a reversed duplicate butted against the original, used to lengthen a fill or to disguise an audible repeating pattern or recognizable event so the looped background does not draw attention.','It is background sound played backwards to hide a repeat. Reversing a copy stops the listener from noticing the loop.','It extends limited room tone and breaks up recognizable patterns so a looped ambient bed sounds continuous and natural instead of obviously repeating.','When only a short room-tone clip exists, an editor reverses a copy and joins it end to end to fill a longer gap without an obvious loop.','Fill & Room Tone',ARRAY['Fill','Room tone','Pre-action fill','Room-tone contouring','Crossfade','Loop']::text[],ARRAY['Reversing tone that contains a distinct sound, so the event plays backwards and stands out.','Forgetting a crossfade at the reverse point, leaving an audible seam.','Reversing so short a piece that the back-and-forth pattern becomes obvious.']::text[],ARRAY['Extending a few seconds of room tone to cover a long dialogue gap.','Hiding a repeating cricket or hum cycle in a looped ambience.','Smoothing a fill under replacement dialogue where only a short tone sample exists.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bdea0188-acc4-583e-80b2-5da45d5d7eb2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reversed fill'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bdea0188-acc4-583e-80b2-5da45d5d7eb2','47e2b509-c540-4a23-839c-c7190b673899',true
