INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ad43f890-a21f-555c-ac3b-aa952d2246d4','Room-tone collapse','An abrupt drop or thinning of the background ambience at a dialogue edit or gap, where the room tone suddenly falls away, often when production sound is muted or fill is missing, leaving an unnatural pocket of near-silence that exposes the cut.','It is when the background sound suddenly drops out at a cut. The scene goes too quiet, so the edit becomes obvious.','The term flags a missing or interrupted ambient bed so the editor knows to add fill and keep the background continuous across the edit.','An editor hears the background vanish at a cut and lays matching fill into the gap so the ambience stays constant.','Fill & Room Tone',ARRAY['Room tone','Fill','Pre-action fill','Room-tone pumping','Crossfade','Handles']::text[],ARRAY['Cutting out a breath or noise and leaving true silence instead of filling with room tone.','Muting a clip without checking that background continues underneath it.','Assuming a crossfade alone will hide a gap where the tone itself disappears.']::text[],ARRAY['Filling the silent hole left after removing an off-camera noise.','Bridging a cut between two takes with different background levels.','Covering a gap where a clip was muted for a picture change.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ad43f890-a21f-555c-ac3b-aa952d2246d4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Room-tone collapse'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ad43f890-a21f-555c-ac3b-aa952d2246d4','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ad43f890-a21f-555c-ac3b-aa952d2246d4' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e317e211-59b9-559f-a1fb-391d52ab19f5','Room-tone contouring','The practice of shaping the level, and sometimes the equalization, of room-tone fill over time so the background matches changing scene dynamics and camera perspective, raising it under wider shots or louder action and easing it for intimate moments, so ambience stays believable shot to shot.','It means adjusting the background volume as the scene changes. You raise or lower the room sound so it fits each shot.','It keeps the ambient bed matched to the picture and dialogue dynamics so backgrounds feel natural and consistent across cuts rather than flat and static.','An editor rides fill level with automation, lifting it for a wide exterior and pulling it back for a quiet close-up.','Fill & Room Tone',ARRAY['Room tone','Fill','Automation','Room-tone pumping','Perspective','Pre-action fill']::text[],ARRAY['Leaving fill at one flat level so it fights the scene''s changing dynamics.','Over-riding the level so the background audibly pumps up and down.','Ignoring perspective, so a close-up carries the same big ambience as a wide shot.']::text[],ARRAY['Matching backgrounds across a scene that cuts between wide and close shots.','Easing ambience under an intimate, whispered exchange.','Lifting room tone to support a busier, louder moment in a scene.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e317e211-59b9-559f-a1fb-391d52ab19f5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Room-tone contouring'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e317e211-59b9-559f-a1fb-391d52ab19f5','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e317e211-59b9-559f-a1fb-391d52ab19f5' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7681c161-5ef1-5133-af96-129572d6dee9','Room-tone pumping','An audible rising and falling of the background ambience level, breathing or surging under the dialogue, typically caused by mismatched fill levels, over-aggressive noise reduction, or clumsy automation, which makes the ambient bed sound unnatural.','It is background sound that keeps swelling and fading. The room noise seems to breathe, which sounds wrong under speech.','Naming this fault points the editor to its cause, such as uneven fill, heavy noise reduction, or bad automation, so the background can be smoothed to a steady level.','When the background breathes with each phrase, the editor evens out fill levels and softens noise reduction to hold a steady bed.','Fill & Room Tone',ARRAY['Room tone','Fill','Room-tone contouring','Spectral de-noise','Restoration chirp','Automation']::text[],ARRAY['Setting noise reduction so hard that the background surges back between words.','Butting clips with different tone levels without matching or filling them.','Relying on a noise gate that opens and closes, pumping the ambience.']::text[],ARRAY['Smoothing a dialogue track where fill levels jump between edits.','Fixing background that breathes after heavy de-noising.','Evening out ambience under a scene cut from several noisy takes.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7681c161-5ef1-5133-af96-129572d6dee9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Room-tone pumping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7681c161-5ef1-5133-af96-129572d6dee9','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7681c161-5ef1-5133-af96-129572d6dee9' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c68eb125-4153-53aa-8159-2d729a6ee18a','Safety dialogue track','A backup recording of the dialogue kept in reserve: on set, a duplicate channel recorded at a lower level so it survives unexpected peaks without clipping, and in editing, a preserved copy of the original take, so a clean source remains available if the primary track distorts or is damaged.','It is a backup copy of the recorded voice. If the main track is too loud and distorts, the quieter backup can save the take.','It guards against losing a performance to clipping, distortion, or damage by keeping a second, cleaner source of the same dialogue.','When a sudden shout clips the main track, the editor switches to the lower-level safety track for a clean version of the line.','Dialogue Workflow',ARRAY['Production sound roll','Production dialogue pull','Limiter','Clipping','Alternate take']::text[],ARRAY['Deleting the safety track to save space before the mix is locked.','Assuming the safety is a duplicate at the same level, then finding it also clipped.','Forgetting to check the safety track when the main take distorts on a loud line.']::text[],ARRAY['Recovering a shouted line that clipped on the primary channel.','Restoring a damaged word from the reserved backup during the dialogue pull.','Choosing the clean safety take when the main track overloads on a peak.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c68eb125-4153-53aa-8159-2d729a6ee18a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Safety dialogue track'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c68eb125-4153-53aa-8159-2d729a6ee18a','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c68eb125-4153-53aa-8159-2d729a6ee18a' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'db63f18b-618c-5d7c-b41c-cf05ec93fdd2','Saliva click','A brief, sharp transient click in close-miked dialogue produced when saliva bridges and parts between the tongue, lips, teeth, or palate during speech. It reads as a discrete impulse over or between words and is treated as mouth noise rather than steady background.','This is a small wet click made by spit in the mouth. It happens as the tongue or lips move while talking. A close mic picks it up as a sharp tick over the words.','Naming it as a discrete mouth transient tells the editor to remove it with mouth de-click tools rather than broadband noise reduction meant for steady hiss.','The editor finds each click on the waveform or spectrogram and repairs it with a mouth de-click pass or a short manual spot fix.','Noise & Artifacts',ARRAY['Tongue click artifact','Lip-smack suppression','Sibilant lisping','Room tone','Spectral patching','Handle preservation']::text[],ARRAY['Treating a saliva click with steady-state noise reduction, which leaves the sharp transient in place.','Over-processing until nearby consonants and word attacks sound dull.','Removing so much that the moment leaves an audible gap instead of matching room tone.']::text[],ARRAY['Cleaning a quiet, close-miked emotional scene where mouth clicks stand out.','Polishing narration or voice-over with dry-mouth clicks.','Prepping close dialogue for a clean final mix.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='db63f18b-618c-5d7c-b41c-cf05ec93fdd2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Saliva click'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'db63f18b-618c-5d7c-b41c-cf05ec93fdd2','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='db63f18b-618c-5d7c-b41c-cf05ec93fdd2' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b2dd4648-410f-509a-88c1-01fb2d319582','Scene checkerboarding','A dialogue-prep layout in which each scene''s dialogue is placed on its own block or group of tracks, kept separate from adjacent scenes, so every scene can carry its own room tone, equalization, and level settings. It applies the checkerboard principle at scene scale, so neighboring scenes never share a track.','This means giving each scene its own set of tracks. Scenes are kept apart so each can have its own background sound and tone. It is like sorting papers into a folder for each scene.','It keeps the sound of different scenes and rooms from colliding on one track, so the mixer can set matching room tone, EQ, and levels for each scene.','When prepping a reel, the editor lays each scene''s dialogue on a fresh track group, so scene changes never share a track and can be balanced independently.','Editorial Workflow',ARRAY['Setup checkerboarding','Microphone splitting','Room tone','Handle preservation','Mix-track guide','Crossfade']::text[],ARRAY['Letting the end of one scene and the start of the next sit on the same track, blocking separate room tone and EQ.','Not leaving handles at scene boundaries, so no crossfade material remains.','Forgetting to label scene blocks, causing confusion at the mix.']::text[],ARRAY['Prepping a reel that cuts between several locations.','Separating an interior and an exterior scene that need different tone.','Handing a scene-organized session to the re-recording mixer.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b2dd4648-410f-509a-88c1-01fb2d319582' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Scene checkerboarding'),'[^a-z0-9]','','g'));
