INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '73b2c63f-3060-53f3-ae28-424ab79ff271','Scratch DX','Temporary or guide dialogue, usually the raw production sound, used as a placeholder reference in an edit before final dialogue is edited or replaced. DX is the common abbreviation for dialogue; scratch DX holds sync, timing, and intent while the finished track is prepared.','The letters DX are short for dialogue. Scratch dialogue is a rough, temporary voice track. Editors use it as a placeholder to hold timing until the final version is ready.','It preserves sync, pacing, and story intent for temp screenings and picture cutting while the clean, final dialogue or replacement lines are still being built.','The editor keeps the production audio as a scratch DX guide under the picture, then replaces it with edited dialogue or ADR as those become available.','Editorial Workflow',ARRAY['Scene checkerboarding','Mix-track guide','Handle preservation','Room tone','Sound-roll metadata','Microphone splitting']::text[],ARRAY['Treating scratch dialogue as final and mixing it instead of the edited track.','Deleting the scratch guide before the replacement lines are confirmed in sync.','Judging performance or quality from a rough guide as if it were the finished track.']::text[],ARRAY['Holding timing in a temp mix for a test screening.','Guiding the picture editor''s cut before final dialogue is ready.','Providing a sync and timing reference while ADR is recorded and edited.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='73b2c63f-3060-53f3-ae28-424ab79ff271' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Scratch DX'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '73b2c63f-3060-53f3-ae28-424ab79ff271','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='73b2c63f-3060-53f3-ae28-424ab79ff271' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2b1aed1c-2d72-5850-b7ec-f6937e39e13f','Setup checkerboarding','A dialogue-prep layout that groups clips from the same camera setup, and thus the same microphone perspective and tone, onto shared tracks while alternating different setups across tracks. It lets each consistent-sounding angle be equalized, level-matched, and processed as a unit.','A camera setup is one angle and mic position. This means putting all clips from the same setup on the same track. Touching angles go on different tracks, like squares on a checkerboard. So no two clips side by side share a track. Matching sound stays together, so it is easy to balance.','Grouping by setup keeps each mic perspective consistent on its own track, so one EQ and level setting fits every clip from that angle instead of fighting shot-to-shot tone changes.','The editor sorts a scene''s clips by camera setup, placing each angle''s dialogue on its own track so the mixer can match tone per setup.','Editorial Workflow',ARRAY['Scene checkerboarding','Mic-angle change','Microphone splitting','Head-turn loss','Room tone','Mix-track guide']::text[],ARRAY['Mixing clips from different setups on one track, forcing constant EQ and level changes.','Ignoring mic-perspective differences and grouping by character alone.','Leaving no handles between setup changes for crossfades.']::text[],ARRAY['Prepping a dialogue scene shot from a wide, a single, and a reverse angle.','Grouping matching over-the-shoulder angles for consistent tone.','Organizing setups so the mixer can EQ each perspective once.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2b1aed1c-2d72-5850-b7ec-f6937e39e13f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Setup checkerboarding'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2b1aed1c-2d72-5850-b7ec-f6937e39e13f','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2b1aed1c-2d72-5850-b7ec-f6937e39e13f' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ef5b9eeb-49e7-586c-bd6a-710aef709991','Sibilant graft','A repair edit that splices a clean sibilant sound, such as an s, sh, or z, taken from another word or take onto a word whose own sibilant is distorted, clipped, or damaged. Only the sibilant is transplanted, matched in level and timing to the host word.','A sibilant is an s or sh sound. This means moving a clean s from one word onto another word with a bad s. It is like patching one letter of a word with a spare.','It rescues a single ruined s or sh without redoing the whole line, keeping the original performance while removing the damaged sound.','The editor copies a matching sibilant from a nearby word or alternate take, trims it to length, and crossfades it over the damaged one.','Dialogue Cleanup',ARRAY['Sibilant replacement','Syllable replacement','Micro-comping','Sibilant lisping','Handle preservation','Crossfade']::text[],ARRAY['Grafting a sibilant from a take with different tone or mic, so the join stands out.','Mismatching the length or level, making the s too long, short, loud, or soft.','Skipping a crossfade at the splice, leaving a click or abrupt edge.']::text[],ARRAY['Repairing a distorted s caused by a peak or overload on one word.','Fixing a clipped sibilant on an otherwise perfect take.','Replacing a whistling s with a smoother one from another word.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ef5b9eeb-49e7-586c-bd6a-710aef709991' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sibilant graft'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ef5b9eeb-49e7-586c-bd6a-710aef709991','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ef5b9eeb-49e7-586c-bd6a-710aef709991' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c6024c02-b432-5141-8f49-e8fdbf0b5c8f','Sibilant lisping','A dull, lisp-like quality of s and sh sounds in which the sibilant loses its high-frequency energy and sounds soft or slushy. In dialogue editing it most often results from overzealous de-essing or excessive high-frequency reduction, though it can also be a natural speech trait.','A lisp makes s sounds soft and slushy. This can happen when too much of the high, hissy part of the voice is removed. The words then sound dull.','Recognizing it warns the editor that de-essing or high-frequency cuts have gone too far, so speech clarity and natural s sounds can be restored.','The editor backs off the de-esser or high-cut, or treats only the harsh moments, so sibilants stay crisp without turning lispy.','Noise & Artifacts',ARRAY['Sibilant replacement','Sibilant graft','Saliva click','Spectral hole','Room tone','Micro-comping']::text[],ARRAY['Applying one heavy de-esser across a whole track, dulling every s into a lisp.','Chasing sibilance so hard that the voice sounds dark and slushy.','Mistaking a natural lisp for a fixable artifact and over-processing it.']::text[],ARRAY['Reviewing a de-essed voice-over that now sounds dull and lispy.','Comparing processed and raw sibilants to judge over-de-essing.','Deciding whether a lisp is the performer''s own or a processing artifact.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c6024c02-b432-5141-8f49-e8fdbf0b5c8f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sibilant lisping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c6024c02-b432-5141-8f49-e8fdbf0b5c8f','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c6024c02-b432-5141-8f49-e8fdbf0b5c8f' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c70fbc30-2cb0-5fd7-ac52-ca9e9868eb2d','Sibilant replacement','The wholesale substitution of a problematic sibilant sound with a cleaner one drawn from another word, take, or source, rather than merely reducing it with a de-esser. It targets s, sh, and z sounds that are distorted, harsh, whistling, or otherwise unusable.','A sibilant is an s or sh sound. This means swapping a bad s for a clean one from elsewhere. Instead of just turning it down, you replace the whole sound.','It fixes an s or sh that cannot be saved by level or EQ, restoring clear, natural sibilance while keeping the rest of the word intact.','The editor sources a matching sibilant from another take or word and edits it in, or has the line re-recorded when no clean source exists.','Dialogue Cleanup',ARRAY['Sibilant graft','Sibilant lisping','Syllable replacement','Micro-comping','Handle preservation','Crossfade']::text[],ARRAY['Replacing a sibilant from a mismatched take, so tone or level does not match the word.','Reaching for replacement when careful de-essing would have been enough.','Leaving no crossfade at the join, creating a click or seam.']::text[],ARRAY['Fixing a harsh, distorted s that de-essing cannot tame.','Replacing a whistling sibilant on a wireless-mic recording.','Swapping in a clean sh from an alternate take.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c70fbc30-2cb0-5fd7-ac52-ca9e9868eb2d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sibilant replacement'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c70fbc30-2cb0-5fd7-ac52-ca9e9868eb2d','47e2b509-c540-4a23-839c-c7190b673899',true
