INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e8be1df6-8a09-5eea-b1eb-ad2129a7af04','Sound-roll metadata','The identifying data attached to production sound files that names the sound roll, the audio equivalent of a camera roll or reel, along with scene, take, timecode, sample rate, and track names. It is embedded in the Broadcast Wave file''s bext and iXML chunks by the field recorder.','A sound roll is like a numbered reel of recorded sound. This data is stored inside each audio file. It lists the roll, scene, take, and time, so editors can find and sort clips.','It lets editors identify, sort, and sync clips automatically and trace each take back to its source roll, tying picture and sound together in post.','The editor reads the sound-roll, scene, and take fields from the file''s metadata to organize dailies and match audio to the sound report and picture.','Editorial Workflow',ARRAY['Mix-track guide','Scratch DX','Microphone splitting','Handle preservation','Scene checkerboarding','Room tone']::text[],ARRAY['Renaming or converting files in a way that strips the embedded metadata.','Trusting a filename over the embedded sound-roll and scene fields when they disagree.','Ignoring the sound report that should match the roll metadata.']::text[],ARRAY['Organizing dailies by sound roll, scene, and take.','Auto-syncing production audio to picture using embedded timecode.','Tracing a problem clip back to its original sound roll.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e8be1df6-8a09-5eea-b1eb-ad2129a7af04' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sound-roll metadata'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e8be1df6-8a09-5eea-b1eb-ad2129a7af04','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e8be1df6-8a09-5eea-b1eb-ad2129a7af04' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '232614a4-5c37-53d0-b342-50e20177e65b','Spectral attenuation pass','A pass of spectral editing that reduces the magnitude of a selected time-frequency region to match the surrounding spectrum, lowering an unwanted sound toward inaudibility without resynthesizing new audio. It corresponds to the attenuate approach in spectral-repair tools, used when surrounding content must be preserved.','A spectrogram shows sound by pitch over time. This pass turns down one marked patch to match its surroundings. The unwanted sound fades out while nearby audio stays.','It removes a noise that overlaps the voice by pulling just its frequencies down to the background level, rather than cutting out or rebuilding the whole moment.','The editor selects the noise on the spectrogram and applies attenuation, checking that the reduced patch blends with the surrounding tone.','Spectral Repair',ARRAY['Spectral patching','Spectral hole','Saliva click','Room tone','Tongue click artifact','Handle preservation']::text[],ARRAY['Attenuating too deeply and leaving a spectral hole where the voice''s own energy is gone.','Selecting too wide an area and dulling the surrounding speech.','Using attenuation on a large gap that really needs replacement or patching.']::text[],ARRAY['Reducing a chair squeak that overlaps a spoken word.','Lowering a short beep or tone sitting over dialogue.','Softening a door slam without cutting the underlying line.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='232614a4-5c37-53d0-b342-50e20177e65b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spectral attenuation pass'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '232614a4-5c37-53d0-b342-50e20177e65b','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='232614a4-5c37-53d0-b342-50e20177e65b' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e003f83b-5d0b-54e8-9600-3f423f2becdc','Spectral hole','An audible gap or notch left in a signal''s frequency content when noise reduction or spectral attenuation removes legitimate audio along with the noise. The missing energy makes the voice sound thin, hollow, or unnatural and can expose musical-noise artifacts around the gap.','This is a gap left in the sound after too much noise removal. Real parts of the voice get taken out with the noise. The result sounds thin or hollow, like a missing piece.','Naming the artifact warns the editor that processing was too aggressive, so settings can be eased to keep the voice full and natural.','The editor hears the thin or hollow result, reduces the amount of noise reduction or attenuation, and treats only the problem spots.','Noise & Artifacts',ARRAY['Spectral attenuation pass','Spectral patching','Sibilant lisping','Room tone','Saliva click','Handle preservation']::text[],ARRAY['Pushing noise reduction so hard that the voice''s own harmonics are gone.','Judging strength only in solo, then finding a hollow voice in the full mix.','Trying to fill a spectral hole with more processing instead of easing off.']::text[],ARRAY['Reviewing over-denoised dialogue that now sounds thin.','Hearing a hollow gap after heavy hum or noise removal.','Dialing back a de-noise setting that left the voice empty.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e003f83b-5d0b-54e8-9600-3f423f2becdc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spectral hole'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e003f83b-5d0b-54e8-9600-3f423f2becdc','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e003f83b-5d0b-54e8-9600-3f423f2becdc' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'af0f706c-9e14-5bf4-bca6-8bb0907a7a0d','Spectral patching','A spectral-editing repair that rebuilds a damaged time-frequency region by interpolating from surrounding audio or by copying clean content from a similar region elsewhere in the file. It corresponds to the replace and pattern approaches in spectral-repair tools, used to fill gaps or cover damage rather than merely reduce it.','A spectrogram shows sound by pitch over time. This repair fills a damaged patch with clean sound copied from nearby. It is like patching a hole in cloth with matching fabric.','It restores a ruined or missing moment by rebuilding or borrowing matching spectral content, so the repair blends in instead of leaving a gap.','The editor selects the damaged region on the spectrogram and applies replace or pattern-based repair, sampling clean audio to cover the fault.','Spectral Repair',ARRAY['Spectral attenuation pass','Spectral hole','Sibilant graft','Syllable replacement','Room tone','Handle preservation']::text[],ARRAY['Patching from a region with different tone or background, so the repair stands out.','Using replacement on a wide area, which can smear or blur the audio.','Choosing patching when simple attenuation would have preserved more of the original.']::text[],ARRAY['Filling a short dropout or gap in a tonal part of dialogue.','Covering a loud transient that sits directly over a vowel.','Rebuilding a moment damaged by distortion using clean surrounding audio.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='af0f706c-9e14-5bf4-bca6-8bb0907a7a0d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spectral patching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'af0f706c-9e14-5bf4-bca6-8bb0907a7a0d','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='af0f706c-9e14-5bf4-bca6-8bb0907a7a0d' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9d73d8df-71e2-5b07-aad5-7a2c23a4af11','Syllable replacement','A fine-scale dialogue edit that substitutes a single syllable with a matching one from another take, word, or source to fix a mispronunciation, noise, distortion, or sync problem without redoing the whole line. It is a smaller-scale form of comping than word or line replacement.','This means swapping just one syllable of a word. A clean version comes from another take. It fixes a small problem without redoing the whole line.','It repairs a localized fault — a noisy, muffled, or misspoken syllable — while keeping the surrounding performance and sync intact.','Using stacked takes or playlists, the editor cuts in a matching syllable, aligns its timing to picture, and crossfades the joins.','Editing Technique',ARRAY['Sibilant replacement','Sibilant graft','Micro-comping','Spectral patching','Handle preservation','Crossfade']::text[],ARRAY['Replacing a syllable from a take with different tone or background, so the join is obvious.','Losing lip sync because the swapped syllable has a different length or timing.','Skipping crossfades at the joins, leaving clicks or tonal jumps.']::text[],ARRAY['Fixing one mispronounced syllable in an otherwise perfect take.','Replacing a syllable ruined by a cough or bump.','Repairing a muffled syllable from a cleaner alternate take.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9d73d8df-71e2-5b07-aad5-7a2c23a4af11' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Syllable replacement'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9d73d8df-71e2-5b07-aad5-7a2c23a4af11','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9d73d8df-71e2-5b07-aad5-7a2c23a4af11' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '26016c35-94bb-5b88-9c20-48adade4d9a4','Tongue click artifact','A brief click produced when the tongue releases from the palate, teeth, or floor of the mouth during speech, captured as a discrete transient on close-miked dialogue. Like other mouth noises it reads as a sharp impulse and is treated as a click rather than steady background.','This is a small click made by the tongue inside the mouth. It happens as the tongue pulls away from the roof or teeth. A close mic records it as a sharp tick over the words.','Identifying it as a discrete mouth transient points the editor to mouth de-click repair rather than broadband noise reduction meant for steady hiss.','The editor locates each tongue click on the waveform or spectrogram and removes it with a mouth de-click pass or a short manual spot repair.','Noise & Artifacts',ARRAY['Saliva click','Lip-smack suppression','Sibilant lisping','Spectral patching','Room tone','Handle preservation']::text[],ARRAY['Treating a sharp tongue click with steady-state noise reduction, which leaves the transient.','Over-processing and dulling the consonants around the click.','Removing the click so hard that a gap appears instead of matching room tone.']::text[],ARRAY['Cleaning dry-mouth clicks in a quiet, close-miked scene.','Polishing narration or voice-over with audible tongue clicks.','Prepping intimate dialogue for a clean mix.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='26016c35-94bb-5b88-9c20-48adade4d9a4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tongue click artifact'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '26016c35-94bb-5b88-9c20-48adade4d9a4','47e2b509-c540-4a23-839c-c7190b673899',true
