INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3c6628ed-6357-5ae6-9388-5bd67a23c747','Track dressing','In dialogue editing, the process of preparing and smoothing edited dialogue tracks for the mix by filling gaps and edit seams with matching room tone, trimming extraneous noise, and organizing lines across tracks so each cut plays as continuous, unbroken sound. It removes the audible evidence of editing so the dialogue feels recorded in one take.','Track dressing means tidying up the edited voice tracks. You fill the gaps between edits with matching room sound so nothing pops or drops out. It is like smoothing over the seams so no one can tell where you cut.','It hides the joins between edits so dialogue sounds continuous and natural, giving the re-recording mixer clean, gap-free tracks to balance.','After cutting lines together, the editor lays matching room tone under and between clips, adds crossfades, and removes clicks so each track plays smoothly.','Editorial Workflow',ARRAY['Room tone','Handle preservation','Crossfade','Fill','Dialogue premix','ADR']::text[],ARRAY['Filling gaps with room tone that does not match the take''s background, so the fill is audible.','Leaving hard edit seams undressed, producing clicks or sudden drops in background level.','Dressing tracks so aggressively that natural pauses sound unnaturally dead or silent.']::text[],ARRAY['Smoothing a scene assembled from several takes with different room backgrounds.','Filling silent gaps between lines before handing tracks to the re-recording mixer.','Cleaning up edit points after conforming dialogue to a new picture cut.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3c6628ed-6357-5ae6-9388-5bd67a23c747' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Track dressing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
