INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ab24978a-f745-5776-b4ec-97039dde6196','Transfer track','A track created by copying (transferring) production or source audio from its original recording medium onto the working medium used for editing — historically sprocketed magnetic film, and later a digital edit track — so it can be synchronized to picture and cut. The transfer produces an edit-ready copy while the original recording is preserved.','A transfer track is a working copy of the recorded sound. The original recording is copied onto the format used for editing. It is like photocopying a page so you can mark up the copy and keep the original safe.','It provides an edit-ready, picture-synchronized copy of the sound so editors can cut freely without touching or wearing out the original recording.','In analog workflows a technician transferred quarter-inch tape or DAT to magnetic film; today the equivalent is importing and syncing production sound into the editing session.','Editorial Workflow',ARRAY['Sync','Magnetic film','Production sound','Conform','Room tone','Dailies']::text[],ARRAY['Confusing the transfer copy with the original recording and editing or discarding the protected original.','Transferring at the wrong sample rate or speed, causing pitch and sync errors down the line.','Overlooking that a poor transfer bakes in noise or level errors that are hard to remove later.']::text[],ARRAY['Preparing production sound for a flatbed or Pro Tools edit from the original recordings.','Restoring an archival film where the original magnetic track must be transferred to digital before repair.','Syncing transferred dailies to picture before dialogue editing begins.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ab24978a-f745-5776-b4ec-97039dde6196' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Transfer track'),'[^a-z0-9]','','g'));
