INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '76a52572-c5ab-5495-893a-2199c88aa851','Transient erosion','The progressive softening or loss of a sound''s sharp attack transients — the brief, high-energy onsets of consonants, clicks, and impacts — caused by processing such as noise reduction, de-clicking, heavy compression, time-stretching, or lossy coding. The result is duller, less articulate dialogue with reduced clarity of plosives and sibilants.','Transients are the sharp starts of sounds, like the t or k in a word. Transient erosion means those sharp edges get worn down by processing. The voice then sounds soft and mushy, like a blurred photo.','Naming the effect helps editors recognize when cleanup tools are damaging speech clarity, so they can back off settings and protect intelligibility.','An editor watching for transient erosion uses gentler noise-reduction amounts, checks consonant clarity after processing, and reverts overly aggressive de-click or de-noise passes.','Restoration Artifact',ARRAY['Noise reduction','De-click','Musical noise','Sibilance','Intelligibility','Time-stretching']::text[],ARRAY['Pushing noise reduction too hard, smearing consonant attacks and dulling the voice.','Judging cleanup only by the noise floor and not by whether transients and words stay crisp.','Stacking several processors so small losses of attack add up to noticeably mushy dialogue.']::text[],ARRAY['Cleaning noisy location dialogue with spectral de-noise.','Removing clicks and mouth noise from a voice-over.','Time-stretching a line to fit picture and losing consonant sharpness.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='76a52572-c5ab-5495-893a-2199c88aa851' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Transient erosion'),'[^a-z0-9]','','g'));
