INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cebd0b4e-e8a2-5aa6-afe9-08554aec0fae','Under-clothing resonance','The tonal coloration produced when a lavalier microphone is concealed beneath clothing: the fabric and the small trapped air cavity attenuate high frequencies while emphasizing a band of low-to-mid frequencies, giving a muffled, chesty, sometimes boxy timbre. The effect varies with fabric type, mounting, and the cavity formed around the capsule.','Hiding a mic under clothes changes how a voice sounds. The cloth blocks the crisp high tones and can boost lower, boomy tones. The voice sounds muffled and chesty, like talking with a blanket over the mic.','Understanding it lets editors and mixers match a hidden lav to a boom or exposed mic, and choose EQ or a presence-boost microphone to restore clarity.','The editor adds high-frequency lift and dips the resonant low-mid band to match the lav to the boom, or the recordist uses a presence-boost capsule and careful mounting.','Mic Perspective',ARRAY['Lavalier','Boom','Microphone splitting','Presence boost','Equalization','Clothing rustle']::text[],ARRAY['Boosting only overall level to fix a muffled lav, which does not restore the missing highs.','Mounting the lav in a tight fabric cavity that worsens the resonance and traps rustle.','Assuming the lav is faulty rather than recognizing normal under-clothing coloration.']::text[],ARRAY['Matching a hidden lavalier to the boom in the same scene.','EQ-ing a chesty, muffled wire on a costumed actor.','Choosing a presence-boost lav for a subject who must be miked under clothing.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cebd0b4e-e8a2-5aa6-afe9-08554aec0fae' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Under-clothing resonance'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
