WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cebd0b4e-e8a2-5aa6-afe9-08554aec0fae' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd7d429f2-e936-51e0-88a9-ebc873f5bfcd','Underwater dialogue','Dialogue treated to sound as if heard underwater or by a submerged listener, characterized by strong low-pass filtering that removes high frequencies, muffling, reduced intelligibility, and often added modulation, pitch shift, or reverberation to suggest the medium. It is used for point-of-view moments when a character''s head is beneath the surface.','Underwater dialogue makes a voice sound like it is heard below the water. Editors cut the high tones and muffle it so words go soft and dull. It is the blurry, boomy sound you hear with your ears under the bath.','It places the audience inside a submerged character''s point of view, using tone and muffling to sell that the sound travels through water.','The editor or mixer applies a steep low-pass filter, softens transients, and adds slow modulation or reverb to a line for an underwater point-of-view shot.','Dialogue Treatment',ARRAY['Low-pass filter','Futz','Point of view','Reverberation','Muffling','Sound design']::text[],ARRAY['Only lowering volume instead of removing highs, so the line still sounds crisp and dry.','Cutting so many highs that the words become unintelligible when the story needs them clear.','Failing to match the effect to picture, so the treatment starts before the head goes under.']::text[],ARRAY['A character dives underwater and we stay in their point of view.','A drowning or pool scene where dialogue must sound submerged.','A dream or disorientation sequence using an underwater-style voice treatment.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d7d429f2-e936-51e0-88a9-ebc873f5bfcd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Underwater dialogue'),'[^a-z0-9]','','g'));
