WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d7d429f2-e936-51e0-88a9-ebc873f5bfcd' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b34b0b11-7d67-50ee-be0f-03f86b5f28e2','Variable interchannel offset','A time offset between two or more channels recording the same source that changes over time, typically because the performer moves and the path-length difference to each microphone varies. When the channels are combined, the shifting delay causes moving comb-filter coloration and phase problems rather than a fixed, correctable delay.','When two mics record one voice, sound reaches them at slightly different times. If the actor moves, that time gap keeps changing. Mixing the mics then makes a hollow, shifting tone, because the delay will not hold still.','Recognizing it explains why summing a moving actor''s boom and lav sounds hollow, guiding editors to pick one mic rather than blend both.','Rather than phase-aligning a fixed delay, the editor usually chooses the cleaner single mic per moment, or dynamically realigns clips, to avoid moving comb filtering.','Mic Perspective',ARRAY['Comb filtering','Phase','Microphone splitting','Boom','Lavalier','Time alignment']::text[],ARRAY['Blending boom and lav on a moving actor and getting hollow, phasey coloration.','Applying one fixed delay to align mics whose offset actually changes moment to moment.','Assuming the two mics are out of polarity when the real problem is a shifting time offset.']::text[],ARRAY['An actor walks across a room recorded on both boom and lav.','Summing spaced microphones on a source that moves during the take.','Deciding whether to use boom or lav as the offset drifts through a line.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b34b0b11-7d67-50ee-be0f-03f86b5f28e2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Variable interchannel offset'),'[^a-z0-9]','','g'));
