SELECT 'b34b0b11-7d67-50ee-be0f-03f86b5f28e2','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b34b0b11-7d67-50ee-be0f-03f86b5f28e2' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0388f087-61a0-5801-8a88-3e03046d0d79','Vocal granulation','A grainy, particulate quality in a voice in which the continuous signal is perceived as a rapid series of short discrete grains rather than a smooth tone. It arises deliberately from granular processing that segments the voice into overlapping grains, or as an artifact of extreme time-stretching, low-bitrate coding, or heavy spectral processing.','Granulation makes a voice sound like it is made of tiny bits, not one smooth sound. It can be done on purpose for effect, or happen by accident from heavy processing. Think of a smooth line turned into a string of little beads.','As an effect it creates texture and unreal voices; as an artifact, spotting it warns the editor that stretching or coding has broken the voice into audible grains.','A sound designer uses granular tools to texture a voice, while a dialogue editor treats unwanted granulation by easing time-stretch amounts or replacing the coded source.','Signal Processing',ARRAY['Granular synthesis','Time-stretching','Transient erosion','Musical noise','Sound design','Bit-rate reduction']::text[],ARRAY['Pushing a time-stretch so far that the voice breaks into audible grains.','Confusing processing granulation with natural vocal roughness in the performance.','Trying to EQ away granulation, which is a structural artifact and not a tonal one.']::text[],ARRAY['Designing an inhuman or glitchy voice with granular tools.','Stretching a line to fit picture and hearing it break into grains.','Repairing dialogue from a heavily compressed, low-bitrate source file.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0388f087-61a0-5801-8a88-3e03046d0d79' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal granulation'),'[^a-z0-9]','','g'));
