INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b2b47009-7b86-57e6-a8fe-f5b704645901','Voice-extraction halo','A residual smear of processing artifacts surrounding a voice that has been isolated from a mixed recording by spectral source separation. As the algorithm removes background around the speech, imperfect masking leaves a faint, watery, reverberant fringe — a halo of leftover energy and musical noise — that follows the voice, especially on sibilants and word edges.','When software pulls a voice out of a noisy recording, it can leave a faint fuzzy shadow around the words. This halo is bits of leftover sound the tool could not fully remove. It is like cutting a shape from a photo and leaving a rough glowing edge.','Naming it helps editors judge how hard to push separation tools, trading noise removal against an audible artifact ring around the dialogue.','The editor dials back separation strength, blends in a little original signal, or masks the halo with room tone so the isolated voice sounds natural.','Restoration Artifact',ARRAY['Dialogue isolation','Spectral editing','Musical noise','Noise reduction','Transient erosion','Room tone']::text[],ARRAY['Pushing separation to fully remove noise, which leaves an obvious watery halo.','Delivering isolated dialogue without checking word edges where the halo is loudest.','Assuming the halo is reverb in the recording rather than a separation artifact.']::text[],ARRAY['Isolating a line from loud on-set background with a dialogue-separation tool.','Salvaging a phrase buried under music or traffic.','Cleaning a witness or interview recording for broadcast.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b2b47009-7b86-57e6-a8fe-f5b704645901' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Voice-extraction halo'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b2b47009-7b86-57e6-a8fe-f5b704645901','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b2b47009-7b86-57e6-a8fe-f5b704645901' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '541a03b4-3627-53a0-a292-c3b6ee95a566','Vowel graft','A within-word dialogue edit in which the sustained vowel portion of a word is replaced with, or extended by, the matching vowel from another take or syllable, splicing on the steady-state part of the sound where waveform and tone are most stable. Because vowels are periodic and slowly changing, they splice more cleanly than consonants.','A vowel is the steady, open part of a word, like the a in cat. A vowel graft swaps or stretches that steady part using a matching piece from another take. The stable sound hides the join, like patching cloth where the weave lines up.','It lets editors repair or reshape a word — fixing a wobble, length, or bad take — by cutting where the sound is steadiest and least likely to click.','To fix a cracked or mistimed word, the editor splices in the clean vowel from another take at a zero-crossing, matching pitch and level across the graft.','Editorial Technique',ARRAY['Zero-crossing','Crossfade','Micro-comping','Word-end repair','Handle preservation','Pitch matching']::text[],ARRAY['Grafting a vowel at a different pitch, so the splice is audible as a bump.','Cutting inside a consonant instead of the steady vowel, causing a click.','Ignoring room tone or level changes across the graft, so the patch stands out.']::text[],ARRAY['Repairing a single cracked word without re-recording the line.','Lengthening a vowel to better fit lip movement on screen.','Building a clean word from two takes when neither is perfect.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='541a03b4-3627-53a0-a292-c3b6ee95a566' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vowel graft'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '541a03b4-3627-53a0-a292-c3b6ee95a566','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='541a03b4-3627-53a0-a292-c3b6ee95a566' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7fb6ce55-fa86-5c27-88cf-87fa080089d7','Wireless compander artifact','An audible distortion introduced by the companding (compress-then-expand) noise-reduction process in analog FM wireless microphone systems. Imperfect tracking between the transmitter''s compressor and the receiver''s expander produces effects such as level pumping or breathing, modulation of the noise floor with the signal, and garbling or dulling of high-frequency transients.','Analog wireless mics squeeze the sound to send it, then unsqueeze it at the receiver. When the two do not match well, you hear pumping, breathing, or dulled sharp sounds. It is like a volume knob that moves on its own and never quite lines up.','Recognizing the artifact tells the editor the flaw is baked into the radio link, not the room or the edit, so it is treated as damage rather than performance.','The editor patches affected words from a boom or backup track, or uses de-noise and de-ess tools, since companding artifacts cannot be removed by EQ alone.','Restoration Artifact',ARRAY['Companding','Wireless microphone','Microphone splitting','Noise floor','Boom','Dropout']::text[],ARRAY['Blaming the room or mic when pumping and breathing come from the radio link.','Trying to fix companding pumping with EQ, which does not address the level modulation.','Ignoring a clean boom or backup that could replace the artifact-laden wireless take.']::text[],ARRAY['Editing dialogue recorded on an analog radio mic in a quiet scene.','Hearing the background breathe up and down under a soft line.','Choosing between an artifact-laden wireless take and a cleaner boom.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7fb6ce55-fa86-5c27-88cf-87fa080089d7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wireless compander artifact'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7fb6ce55-fa86-5c27-88cf-87fa080089d7','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7fb6ce55-fa86-5c27-88cf-87fa080089d7' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '79078e9d-b7fc-568f-9722-7fdc5e10707d','Word-end repair','A dialogue edit that restores a clipped, dropped, faded, or off-mic word ending — most often a final consonant, plosive, or sibilant — by extending, replacing, or reconstructing the tail of the word from another take or matched material so the word finishes cleanly and intelligibly.','Sometimes the end of a spoken word gets cut off or fades away. Word-end repair puts that missing ending back so the word sounds complete. It is like redrawing the last letter of a word that ran off the page.','It keeps speech intelligible and natural when the final sound of a word is lost to a mic move, edit, overlap, or noise.','The editor borrows the missing consonant or tail from another take of the same word, matching pitch, level, and room tone, and crossfades it onto the truncated word.','Editorial Technique',ARRAY['Vowel graft','Crossfade','Room tone','Micro-comping','Sibilance','Handle preservation']::text[],ARRAY['Grafting a word tail from a take with different tone or room, so the join is obvious.','Rebuilding an ending at the wrong level, making the consonant pop or vanish.','Fixing the ending but ignoring lip sync so the added sound drifts off picture.']::text[],ARRAY['Restoring a dropped final t or s cut off by a mic move.','Repairing a word swallowed under an overlapping line.','Completing a word clipped by the picture editor''s hard cut.']::text[],'47e2b509-c540-4a23-839c-c7190b673899'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='79078e9d-b7fc-568f-9722-7fdc5e10707d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Word-end repair'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '79078e9d-b7fc-568f-9722-7fdc5e10707d','47e2b509-c540-4a23-839c-c7190b673899',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='79078e9d-b7fc-568f-9722-7fdc5e10707d' AND gt.achievement_id='47e2b509-c540-4a23-839c-c7190b673899');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0fed6ff2-520d-517f-899c-9c766a67b6e8','Accent mapping','In dubbing and localization, the deliberate scheme deciding which target-language accents, dialects, or varieties will represent each source-language accent, dialect, or national origin across a production, so the social and geographic connotations of the original speech carry into the dubbed version consistently. It is a planning stage of dialect translation, distinct from the on-the-line technique of substitution.','Accent mapping is a plan for how accents change in a dub. The team picks which new accent stands for each original accent. They keep those choices the same across the show.','It gives the adaptation team a consistent, deliberate scheme for rendering linguistic variation, so a character''s regional or social identity is preserved rather than lost or randomly reassigned.','Before recording, the translator or dubbing director maps each source accent to a target variety, then applies that scheme consistently so the same character keeps the same accent throughout.','Accent & Dialect',ARRAY['Accent substitution','Accent neutralization','Character synchrony','Dialogue adaptation','Bilingual dubbing']::text[],ARRAY['Mapping a source accent to a target accent that carries the wrong stereotype, changing how a character is read.','Reassigning accents inconsistently, so the same character sounds regional in one scene and neutral in another.','Ignoring accent mapping entirely and flattening every voice to one standard, erasing meaningful contrasts.']::text[],ARRAY['Planning how the regional accents of an ensemble comedy will be represented in a dubbed language.','Deciding how a foreign-accented character in the original should sound in the target version.','Building a style guide so every episode of a series maps accents the same way.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0fed6ff2-520d-517f-899c-9c766a67b6e8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Accent mapping'),'[^a-z0-9]','','g'));
