INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fafec004-0853-5a28-be3b-cb5ea6b09bbd','Accent neutralization','The practice of removing or minimizing regional, social, or national accent markers in dubbed dialogue so the delivery uses a standard or ''neutral'' variety of the target language, intended to be understood and accepted across the widest possible audience. In Spanish-language dubbing this is exemplified by ''neutral Spanish'' (espanol neutro), an artificial pan-regional standard rather than any real regional accent.','This means removing a strong accent from the dubbed voice. Actors speak in a plain, standard form of the language. Then people from many regions can share one dubbed track.','It maximizes reach and reduces distraction by producing one dub that many regional markets can share, instead of making a separate version for each local accent.','A dubbing director casts and coaches actors to speak a standardized variety, such as neutral Spanish, avoiding local slang and pronunciation so a single track serves a whole region.','Accent & Dialect',ARRAY['Accent substitution','Accent mapping','Character synchrony','Dialogue adaptation','Bilingual dubbing']::text[],ARRAY['Assuming a truly accent-free ''neutral'' variety exists; a neutral standard is a constructed compromise, not a real accent.','Neutralizing a character whose accent is central to the story, erasing meaning the plot depends on.','Letting local slang or pronunciation slip into a supposedly neutral track, breaking its pan-regional consistency.']::text[],ARRAY['Producing one neutral-Spanish dub of a film for release across Latin America.','Coaching a voice actor to drop a strong regional accent for a standardized delivery.','Deciding whether a character''s accent should be neutralized or preserved.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fafec004-0853-5a28-be3b-cb5ea6b09bbd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Accent neutralization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fafec004-0853-5a28-be3b-cb5ea6b09bbd','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fafec004-0853-5a28-be3b-cb5ea6b09bbd' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2de058b8-0e2a-5a9b-905d-c2511621fa8e','Accent substitution','A dialect-translation technique in which a source-language accent or dialect is replaced with a target-language accent or dialect chosen to convey a comparable social, regional, or characterizing meaning, rather than being neutralized or rendered literally. For example a rural source dialect may be voiced with a broadly rural target variety that signals a similar background.','Accent substitution swaps one accent for a new one with a similar feel. A country accent in the first version becomes a country accent in the dub. This keeps what the accent told viewers.','It preserves the characterizing function of an accent, showing class, region, or origin, when a literal translation cannot carry that meaning.','The adapter and director pick a target accent that reads as, say, working-class or provincial, and cast a voice actor who can perform it convincingly for that character.','Accent & Dialect',ARRAY['Accent mapping','Accent neutralization','Character synchrony','Actor-voice pairing','Dialogue adaptation']::text[],ARRAY['Choosing a substitute accent that imports the wrong stereotype or an unintended cultural association.','Substituting an accent the target audience will not recognize, so the social cue is lost.','Applying a substitute accent inconsistently across a character''s scenes.']::text[],ARRAY['Rendering a source film''s rural dialect with a target-language rural accent.','Giving a foreign character a recognizable accent in the dubbed language.','Marking class differences between characters through contrasting target accents.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2de058b8-0e2a-5a9b-905d-c2511621fa8e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Accent substitution'),'[^a-z0-9]','','g'));
