WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2de058b8-0e2a-5a9b-905d-c2511621fa8e' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a3d6711a-ef73-587a-8873-d46fa653bed5','Acoustic localization match','The process of treating dubbed or replaced dialogue so its acoustic properties — reverberation, tonal color, apparent distance, and spatial position — match the on-screen environment and camera perspective, making the studio-recorded voice sound as if it were captured in the original location. It aligns the dry dub with the acoustics and staging of the picture.','Dubbed voices are recorded dry (with no echo) in a quiet booth. This match adds the room echo and distance of the real scene. Then the new voice sounds like it was recorded in that place.','It preserves realism and continuity, so a dubbed line sits inside the scene''s sound world instead of sounding flat, close, or detached from the picture.','The re-recording mixer applies reverb and equalization matched to the location, and follows the character''s on-screen distance and movement so the voice tracks the camera perspective.','Acoustic Matching',ARRAY['Reverberation','Dialogue perspective','Room tone','Character synchrony','Futz']::text[],ARRAY['Leaving the dub dry so the voice sits on top of the scene instead of inside it.','Adding a generic reverb that does not match the room''s real size or tone.','Ignoring perspective, so a distant character on screen sounds close and up front.']::text[],ARRAY['Matching a booth-recorded dub to a scene set in a large stone hall.','Following a character''s movement from near to far across a shot.','Blending dubbed lines into the original music-and-effects mix.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a3d6711a-ef73-587a-8873-d46fa653bed5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Acoustic localization match'),'[^a-z0-9]','','g'));
