WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a3d6711a-ef73-587a-8873-d46fa653bed5' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '15c95229-3843-56b7-8f05-0c96c51bc071','Actor-voice pairing','In dubbing casting, the matching of a target-language voice actor to a specific on-screen performer so the dubbing voice suits the original actor''s vocal qualities, age, physique, and screen persona. A given voice actor is often paired consistently with the same original performer across multiple productions.','Actor-voice pairing means picking a dub voice that fits the on-screen actor. The new voice should match the actor''s age, size, and manner. Often one voice actor is used for the same star every time.','It supports believability and audience familiarity, so the dubbed voice feels like it could belong to that performer and stays recognizable across their films.','A dubbing director auditions voice actors against the original performance and casts the closest fit, frequently keeping the same pairing for a star the audience already links with that dub voice.','Voice Casting',ARRAY['Character-voice assignment','Character synchrony','Accent substitution','Character drift','Dialogue adaptation']::text[],ARRAY['Pairing a voice whose age or timbre clashes with the on-screen actor, breaking believability.','Switching a star''s established dub voice without reason, confusing loyal audiences.','Casting for accent or looks alone while ignoring the acting range the role needs.']::text[],ARRAY['Casting the recurring dub voice for a well-known actor''s next film.','Auditioning voices to match a specific lead performer.','Deciding whether to keep or replace a star''s usual dubbing voice.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='15c95229-3843-56b7-8f05-0c96c51bc071' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Actor-voice pairing'),'[^a-z0-9]','','g'));
