WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='15c95229-3843-56b7-8f05-0c96c51bc071' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f94c3b3e-c220-55c3-b948-411f4fecc5db','Adaptation loss','The unintended loss of meaning, tone, humor, wordplay, or cultural nuance that occurs when source dialogue is translated and adapted to meet the synchrony, timing, and lip-movement constraints of dubbing. It is distinct from deliberate condensation, arising when the adapted line fails to carry something the original conveyed.','Dubbing must fit new words to the actor''s mouth and timing. Squeezing lines into that space can drop jokes or meaning. Adaptation loss is what slips away that the writer did not mean to lose.','Naming it helps adapters recognize and reduce avoidable loss, weighing meaning against the technical limits of lip sync and line length.','A dialogue writer reworks a line that lost a joke to timing, finding wording that fits the mouth and duration while restoring the intended meaning or tone.','Dialogue Adaptation',ARRAY['Dialogue adaptation','Isochrony','Bilabial matching','Character synchrony','Accent substitution']::text[],ARRAY['Prioritizing lip sync so hard that meaning and tone are needlessly sacrificed.','Confusing unavoidable, deliberate cuts with careless loss that a rewrite could fix.','Missing prosodic nuance in the original, so the adapted line lands with the wrong feeling.']::text[],ARRAY['Adapting a pun that has no direct equivalent under the mouth movements available.','Fitting a long source line into a short on-screen utterance.','Reviewing a dub script for meaning dropped to satisfy sync.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f94c3b3e-c220-55c3-b948-411f4fecc5db' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Adaptation loss'),'[^a-z0-9]','','g'));
