SELECT 'f94c3b3e-c220-55c3-b948-411f4fecc5db','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f94c3b3e-c220-55c3-b948-411f4fecc5db' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '730c92a2-01dd-504e-bc1d-f2c1cdfd7f7f','Back-to-camera liberty','The greater translational and timing freedom available when a character''s mouth is not clearly visible — for instance when the character is filmed from behind, off-screen, in the distance, or turned away — so phonetic lip synchrony is relaxed and only broad timing (isochrony) and meaning must be respected. Adapters exploit these moments for more accurate or natural wording.','Lip sync only matters when we can see the mouth. When a character faces away or is off screen, the words need not match the lips. This lets the writer choose better, more natural wording.','It lets adapters recover meaning and naturalness lost to strict lip sync, using shots where the audience cannot check the mouth.','The dialogue writer places the more faithful or difficult wording on lines delivered off-screen or back-to-camera, saving tightly lip-matched wording for close-ups.','Synchronization',ARRAY['Bilabial matching','Character synchrony','Isochrony','Adaptation loss','Dialogue adaptation']::text[],ARRAY['Forgetting that the shot may cut to the speaker''s face, exposing a mismatch.','Ignoring timing even when lips are hidden, so the line still runs long or short against the shot.','Treating every off-screen line as free when the mouth is briefly visible.']::text[],ARRAY['Writing dialogue for a character shown only from behind.','Adapting narration or off-screen lines with no lip constraint.','Choosing where to place hard-to-sync wording in a scene.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='730c92a2-01dd-504e-bc1d-f2c1cdfd7f7f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Back-to-camera liberty'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '730c92a2-01dd-504e-bc1d-f2c1cdfd7f7f','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='730c92a2-01dd-504e-bc1d-f2c1cdfd7f7f' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5659db1d-c784-5dca-849a-64e845b2f8a3','Bilabial matching','A lip-synchrony technique in which the target dialogue is written so bilabial consonants (/p/, /b/, /m/) — sounds made by closing both lips and the most visible articulations on screen — fall at or near the same points as in the original, especially in close-ups. Matching these closures is a priority of phonetic synchrony because mismatches are easy for viewers to detect.','The sounds p, b, and m close both lips, so we see them clearly. Bilabial matching lines these lip-closing sounds up with the original. When they match, the dub looks right in close-ups.','It makes dubbing believable at the most exposed moments, since visible lip closures are what audiences most readily notice when sync is off.','The dialogue writer chooses target words that place a /p/, /b/, or /m/ where the actor''s lips visibly close on screen, prioritizing this in close-up shots.','Lip Synchrony',ARRAY['Character synchrony','Isochrony','Back-to-camera liberty','Adaptation loss','Dialogue adaptation']::text[],ARRAY['Putting an open-mouth sound where the actor''s lips clearly close, producing a visible mismatch.','Chasing bilabial matches so hard that the line''s meaning suffers.','Matching bilabials in wide shots where the mouth is not really visible, wasting effort.']::text[],ARRAY['Writing a close-up line where the actor''s lips press together on a /b/.','Fixing a take that looks off because a p or m fell in the wrong place.','Deciding which lip movements to match in a tight facial shot.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5659db1d-c784-5dca-849a-64e845b2f8a3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bilabial matching'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
