WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5659db1d-c784-5dca-849a-64e845b2f8a3' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5330b687-9ca3-5902-92ee-97363e5ccb18','Bilingual dubbing','A dubbing approach in which the target version deliberately retains more than one language — keeping certain characters'' or passages'' original or third language rather than converting all speech into a single target language — to preserve the multilingual character and plot function of a source text where language contrast carries meaning.','Some films use more than one language on purpose. Bilingual dubbing keeps that mix instead of using just one language. A foreign line that matters to the story stays foreign in the dub.','It preserves narrative and characterization tied to language contrast — nationality, foreignness, or not understanding another character — that single-language dubbing would erase.','The adapter decides which passages stay in their original or third language and which are dubbed, so a scene built on a language barrier still works for the target audience.','Localization Strategy',ARRAY['Dialogue adaptation','Accent substitution','Accent mapping','Character synchrony','Accent neutralization']::text[],ARRAY['Dubbing every language into the target, so a plot point about not understanding someone collapses.','Dubbing a third language into the same language as the main track, making the contrast vanish.','Leaving foreign passages unsubtitled when the audience needs the gist.']::text[],ARRAY['Dubbing a war film in which characters speak several languages.','Keeping a character''s foreign lines untranslated for effect.','Handling a scene whose whole point is a language barrier.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5330b687-9ca3-5902-92ee-97363e5ccb18' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bilingual dubbing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
