WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5330b687-9ca3-5902-92ee-97363e5ccb18' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '143ec507-b8d5-51d3-9191-d6cd7a593ea2','Character drift','The gradual loss of consistency in a dubbed character''s voice or portrayal over a long production or series — for example when a voice actor is replaced, or when performance, tone, or characterization slowly changes across episodes — so the character no longer sounds or behaves as first established.','In a long series, a dubbed character should stay the same. Character drift is when that voice or manner slowly changes. It can happen when the voice actor changes over time.','Recognizing it helps a dubbing team guard continuity, keeping a character recognizable so audiences stay immersed across many episodes.','A dubbing director uses reference tracks and notes to keep a returning voice actor''s tone consistent, and matches any replacement voice to the established character.','Character Consistency',ARRAY['Character synchrony','Actor-voice pairing','Character-voice assignment','Accent neutralization','Dialogue adaptation']::text[],ARRAY['Recasting a character mid-series without matching the established voice.','Letting a voice actor''s performance slide in tone or energy across episodes.','Keeping no reference notes, so continuity depends on memory alone.']::text[],ARRAY['Keeping a lead''s dub voice consistent across several seasons.','Matching a replacement actor to a character''s established sound.','Reviewing later episodes for tone that has wandered from the pilot.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='143ec507-b8d5-51d3-9191-d6cd7a593ea2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Character drift'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
