WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='143ec507-b8d5-51d3-9191-d6cd7a593ea2' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ac25a6a6-79d7-5158-82a2-b03536eebf53','Character synchrony','One of Fodor''s categories of dubbing synchrony: the harmony between the dubbing voice and the on-screen character''s appearance, age, personality, and manner, so the voice believably belongs to that character. It concerns casting and vocal performance rather than lip movement or timing.','Character synchrony means the dubbed voice fits the character we see. The voice should match their age, look, and manner. A tough giant should not get a thin, timid voice.','It keeps the dubbed character believable, ensuring the chosen voice suits who the character is on screen, not just what their lips do.','During casting, the dubbing director selects a voice whose timbre, age, and energy match the visible character, then guides the performance to keep that fit.','Synchronization',ARRAY['Actor-voice pairing','Character-voice assignment','Bilabial matching','Isochrony','Character drift']::text[],ARRAY['Casting a voice whose age or timbre clashes with the character''s appearance.','Focusing only on lip sync and ignoring whether the voice suits the character.','Changing a character''s established voice so it no longer matches their persona.']::text[],ARRAY['Casting a voice to fit a large, imposing on-screen character.','Matching a child character with an age-appropriate voice.','Judging whether a dub voice believably belongs to the actor on screen.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ac25a6a6-79d7-5158-82a2-b03536eebf53' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Character synchrony'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
