INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '985b1c64-59ff-5de8-9bf3-5550030dcace','Character-voice assignment','The casting task of allocating each character in a production to a specific dubbing voice actor, ensuring every role is covered, that voices are distinct where needed, and that each voice suits its character. In some workflows one actor voices several minor characters, which must be assigned without audible overlap.','Character-voice assignment means giving each character a voice actor. Every role must be covered and sound right. If one actor plays several small parts, the voices must not clash.','It organizes casting so every character has a fitting, consistent voice and no two characters in a scene are voiced confusingly alike.','The dubbing director builds a cast list mapping characters to actors, doubling minor roles carefully so the same voice never appears twice in one scene.','Voice Casting',ARRAY['Actor-voice pairing','Character synchrony','Character drift','Dialogue adaptation','Accent substitution']::text[],ARRAY['Assigning the same actor to two characters who share a scene, making them sound identical.','Assigning a voice that does not suit the character''s age or personality.','Changing a character''s assigned voice partway through without matching it.']::text[],ARRAY['Building the cast list for a dubbed series with many characters.','Doubling a voice actor across several minor roles without overlap.','Reassigning a role when an actor becomes unavailable.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='985b1c64-59ff-5de8-9bf3-5550030dcace' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Character-voice assignment'),'[^a-z0-9]','','g'));
