INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f1142542-d7cc-5d56-8f6f-461312cb2fe2','Collective dubbing','A dubbing recording mode in which several or all of a scene''s voice actors perform together in the same session, rather than each recording their lines separately on isolated tracks. It preserves live interaction and overlapping delivery between performers, and is contrasted with solo, separate-track recording.','This is when several dub actors record their lines together at once. They can react to each other, like a real chat. The other way is to record each actor alone.','Recording performers together captures natural timing, energy, and overlap between characters, which can make grouped dialogue feel more spontaneous than lines cut in isolation.','A dubbing director may schedule key dialogue scenes as group sessions so actors play off each other, then use solo sessions for pickups and busy schedules.','Recording Workflow',ARRAY['Solo recording','Dubbing director','ADR','Loop group','Lip sync','Voice casting']::text[],ARRAY['Assuming all modern dubbing is recorded with the cast together, when isolated solo recording is now common.','Thinking group recording removes the need for careful lip-sync checking on each line.','Confusing collective dubbing with loop-group crowd recording, which handles background walla rather than principal dialogue.']::text[],ARRAY['Recording an emotional two-hander scene with both dub actors in the booth together.','Older studio dubbing where the whole cast performed around one microphone.','Choosing group versus solo sessions when planning a dub recording schedule.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f1142542-d7cc-5d56-8f6f-461312cb2fe2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Collective dubbing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f1142542-d7cc-5d56-8f6f-461312cb2fe2','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f1142542-d7cc-5d56-8f6f-461312cb2fe2' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5e5cd194-78cb-5d7f-83da-1bc1f74eb46d','Commentary replacement','A localization method in which an original spoken commentary or narration track, such as sports, documentary, or reality voice-over, is replaced with a newly recorded target-language commentary rather than lip-synced to on-screen mouth movements. The new commentary is timed to the picture and program events instead of to visible lip articulation.','This swaps a show''s spoken narration for a new one in another language. It suits sports or documentaries. The new voice matches the action on screen, not the lips.','It lets non-fiction and off-screen narration be localized quickly and clearly, because the voice follows on-screen events and does not need tight lip-sync.','For a localized documentary, a voice actor records replacement narration to picture while the original commentary is muted or ducked underneath.','Localization Deliverable',ARRAY['Voice-over','UN-style voice-over','Narration','Dubbing','Lip sync','M&E track']::text[],ARRAY['Trying to lip-sync a commentary track that is actually off-screen narration.','Forgetting to duck or remove the original commentary so both voices are heard.','Assuming commentary replacement needs the same casting rigor as character lip-sync dubbing.']::text[],ARRAY['Localizing a nature documentary''s narrator into several languages.','Replacing live sports commentary with a home-territory commentary team.','Producing a target-language voice-over for a reality show''s narrator.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5e5cd194-78cb-5d7f-83da-1bc1f74eb46d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Commentary replacement'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5e5cd194-78cb-5d7f-83da-1bc1f74eb46d','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
