INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '37ec4356-a781-5782-827e-d68ceed86891','Compliance localization','The adaptation of localized content so it meets a target territory''s legal, regulatory, and broadcast-standards requirements, including rules on profanity, violence, sensitive references, advertising, and age classification. It may require altered dialogue, edits, disclaimers, or alternate versions in addition to straightforward translation.','This makes a show follow the laws and broadcast rules of each country. Some words, scenes, or claims may be banned or need changes. The dub or edit is adjusted so it can air there.','It protects a release from legal, regulatory, and rating problems in each market, so content can be broadcast or streamed without breaching local standards.','A compliance pass flags dialogue or scenes that break a territory''s rules, and the team softens language or supplies an edited version for that market.','Compliance & Standards',ARRAY['Content rating','Broadcast standards','Compliance edit','Cultural adaptation','Creative QC','Subtitling']::text[],ARRAY['Treating compliance as pure translation and missing content that is illegal or unratable in the target market.','Assuming one compliant version fits every territory, when rules differ widely by country.','Adding profanity or references in the dub that the source did not have and that breach local standards.']::text[],ARRAY['Preparing a film dub for a market with strict rules on profanity or religion.','Adding legally required disclaimers to a localized program.','Creating an edited broadcast version to meet a country''s classification board.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='37ec4356-a781-5782-827e-d68ceed86891' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Compliance localization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '37ec4356-a781-5782-827e-d68ceed86891','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
