INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8b6f007a-9159-553c-ac56-87f8571ffe2a','Creative QC','A quality-control review that evaluates a localized dub for creative and performance fidelity, casting suitability, acting, adaptation accuracy, lip-sync, tone, and faithfulness to the original creative intent, as distinct from purely technical QC of levels, sync, and file conformance. It typically concludes with a creative sign-off before delivery.','This is a check of how good a dub sounds and feels, not just the tech. Reviewers judge the acting, the wording, and the mouth timing. It ends with someone approving the creative side.','It catches creative problems, such as weak performances, off adaptations, or poor sync, that technical checks miss, so the finished dub honors the original''s intent before it ships.','A supervisor watches key scenes against the original, notes performance or adaptation issues, and either requests retakes or gives creative approval.','Quality Control',ARRAY['Technical QC','Creative supervisor','Lip sync','Adaptation','Voice casting','Key moments']::text[],ARRAY['Confusing creative QC with technical QC, which only checks levels, sync, and file specs.','Signing off after checking only the opening minutes instead of the whole program.','Passing a dub with accurate words but flat performances that miss the original''s tone.']::text[],ARRAY['Reviewing the first act of a series dub for casting and performance before full delivery.','Comparing a dubbed scene against the original to judge adaptation and sync.','Giving final creative approval on a title before it goes live.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8b6f007a-9159-553c-ac56-87f8571ffe2a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Creative QC'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
