INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '34fd2e6c-6d26-5600-a925-14abdf3820bb','Creative supervisor','The person responsible for the overall creative quality and consistency of a dubbed or localized version, overseeing script adaptation, voice casting, performance direction, and creative QC so the result honors the original''s intent. On larger projects they may coordinate creative standards across several language versions rather than direct a single session.','This person guards the creative quality of a dub. They watch over the script, the casting, the acting, and the final check. Their job is to keep it true to the original.','The role gives one accountable owner for creative decisions, so casting, adaptation, and performance stay consistent and faithful across the localization.','A creative supervisor approves casting choices, reviews adapted scripts, and signs off on performances before a dub is delivered.','Dubbing Roles',ARRAY['Dubbing director','Creative QC','Voice casting','Adaptation','Cross-title casting','Localization producer']::text[],ARRAY['Confusing the creative supervisor with the technical mixer or engineer.','Assuming the role only picks voices, when it owns adaptation and performance too.','Bringing the supervisor in only at final QC instead of during casting and scripting.']::text[],ARRAY['Approving the voice cast for a flagship series before recording.','Keeping a character''s voice and tone consistent across seasons.','Signing off creative quality across several language dubs of one film.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='34fd2e6c-6d26-5600-a925-14abdf3820bb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Creative supervisor'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '34fd2e6c-6d26-5600-a925-14abdf3820bb','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
