INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '38ccb1ab-0152-534b-83db-afcfe71c8391','Cross-title casting','The management of voice-actor assignments across multiple titles so casting stays consistent and non-conflicting, most importantly keeping the same dub voice for a given on-screen actor or franchise character across the films and series in which they appear. It also avoids over-using one voice actor in a way that would cause recognizable overlap between unrelated titles.','This keeps voice choices steady across many shows. If a dub actor is a star''s regular voice, they should keep voicing that star. It also stops one voice from showing up on too many shows.','It preserves audience recognition of familiar voices for actors and franchises, and prevents distracting voice clashes across a catalog.','A casting team checks which dub actor has voiced a returning star before, and books that same voice unless there is a reason to change.','Casting',ARRAY['Voice casting','Established voice','Creative supervisor','Dubbing director','Franchise consistency','Recasting']::text[],ARRAY['Recasting a star''s established dub voice without checking prior titles.','Booking one popular voice actor across so many titles that voices start to overlap.','Assuming casting can be decided per title in isolation from the wider catalog.']::text[],ARRAY['Keeping the same dub voice for an actor across a film franchise.','Checking a catalog before casting a returning character in a sequel.','Balancing a busy voice actor''s bookings to avoid overlap between shows.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='38ccb1ab-0152-534b-83db-afcfe71c8391' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cross-title casting'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '38ccb1ab-0152-534b-83db-afcfe71c8391','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
