INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2c4d76b3-b883-5aa9-a355-ae111c0f4fc9','Cue extraction','The process of identifying and pulling the individual dialogue segments (cues, takes, or loops) that must be re-recorded or translated from a program''s audio and script, together with their timecodes and speaker information. The result is a structured cue list used to plan recording and track progress.','This means finding every line that must be dubbed and listing it. Each line gets its time code and speaker. The list is used to plan the recording sessions.','It turns a continuous program into an organized worklist of lines, so scheduling, casting, and recording can be tracked cue by cue.','An assistant or software scans the timed script and exports a cue list of every line, its in and out times, and character, ready for the booth.','Cue Preparation',ARRAY['Cue sheet','Take','Loop','Timecode','Cue subdivision','Rythmo band']::text[],ARRAY['Missing off-screen or overlapping lines when building the cue list.','Extracting text without accurate timecodes, which breaks scheduling and sync.','Assuming every cue is on-screen dialogue and skipping narration or crowd lines.']::text[],ARRAY['Building a recording worklist from a locked episode and its script.','Exporting a cue list from dubbing software before booking actors.','Counting a character''s lines to estimate studio time.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2c4d76b3-b883-5aa9-a355-ae111c0f4fc9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue extraction'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2c4d76b3-b883-5aa9-a355-ae111c0f4fc9','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
