INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '57400c84-a434-52ef-b33f-e96ab8ac9f56','Cue subdivision','The practice of breaking a long dialogue cue into shorter sub-cues (takes or loops) so each recorded unit is a manageable length for performance and lip-sync. Shorter cues are easier for actors to match to picture and for editors to place accurately.','This splits a long line into shorter chunks to record. Short chunks are easier to act and to match to the mouth. Editors can also place them more exactly.','Dividing long lines into short takes improves sync accuracy and performance, because actors can nail a brief unit far more reliably than a long unbroken passage.','When a speech is too long to sync cleanly, the editor splits it into several shorter cues that the actor records one at a time.','Cue Preparation',ARRAY['Cue extraction','Take','Loop','Lip sync','Cue sheet','Rythmo band']::text[],ARRAY['Splitting cues in the middle of a word or breath so the joins sound unnatural.','Making cues so short that the performance loses its flow and emotion.','Forgetting to keep consistent timecodes when subdividing, causing sync drift.']::text[],ARRAY['Breaking a long monologue into short takes for easier lip-sync.','Splitting fast overlapping dialogue into separate recordable units.','Preparing dense narration into short cues for the booth.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='57400c84-a434-52ef-b33f-e96ab8ac9f56' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cue subdivision'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '57400c84-a434-52ef-b33f-e96ab8ac9f56','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
