INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5e5a4d3f-0463-57ac-8e95-555e435e769c','Cultural compensation','A translation strategy in which a cultural or linguistic effect that cannot be reproduced at its original point, such as a pun, accent, or culture-bound reference, is offset by introducing a comparable effect elsewhere in the dialogue. The specific instance may be lost, but the overall cultural or comedic texture is preserved across the scene.','Sometimes a joke or culture reference cannot stay in the same spot. So the translator adds a similar effect nearby instead. The scene keeps its feel even if one line changes.','It preserves the tone, humor, or cultural color of a whole passage when a one-to-one match is impossible, rather than leaving a flat gap where the effect was lost.','If a pun cannot survive in one line, the adapter writes an equivalent joke a few lines later so the scene stays funny.','Cultural Adaptation',ARRAY['Cultural explicitation','Cultural retention','Cultural neutralization','Adaptation','Wordplay','Domestication']::text[],ARRAY['Thinking a lost pun must be recreated in the exact same line rather than nearby.','Over-compensating so the target version adds far more jokes than the original had.','Confusing compensation with omission, which simply drops the effect.']::text[],ARRAY['Rewriting a wordplay gag lower in a comedy scene to keep the laughs.','Reflecting a character''s regional accent through word choice elsewhere.','Balancing humor across a sitcom scene when one joke will not translate.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5e5a4d3f-0463-57ac-8e95-555e435e769c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cultural compensation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5e5a4d3f-0463-57ac-8e95-555e435e769c','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5e5a4d3f-0463-57ac-8e95-555e435e769c' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5589d5ec-d38b-5e33-ad29-253239ffb17e','Cultural explicitation','A translation strategy in which cultural information that is implicit in the source is made explicit for the target audience, for example by adding a short gloss or qualifier to an unfamiliar reference. It helps viewers who lack the source culture''s background understand a reference without a footnote.','This adds a few words to explain a reference the audience may not know. For example, a name might get a short label like the singer. It spells out what the original left unsaid.','It bridges a knowledge gap so a foreign reference lands with the target audience, trading some brevity for clearer understanding.','An adapter turns an unexplained local name into the comedian plus the name, so the target viewer gets the point in the moment.','Cultural Adaptation',ARRAY['Cultural retention','Cultural neutralization','Cultural compensation','Specification','Extralinguistic cultural reference','Adaptation']::text[],ARRAY['Adding so much explanation that the line no longer fits the on-screen timing.','Explaining a reference the audience already knows, which sounds patronizing.','Confusing explicitation with retention, which keeps the reference unchanged and unexplained.']::text[],ARRAY['Adding a short label to a foreign celebrity''s name in a dub.','Clarifying a local food or place so the target viewer follows the joke.','Glossing a historical reference briefly within the dialogue.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5589d5ec-d38b-5e33-ad29-253239ffb17e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cultural explicitation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5589d5ec-d38b-5e33-ad29-253239ffb17e','a1c98209-bbc4-4049-baa6-a2a7c9ee0c66',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5589d5ec-d38b-5e33-ad29-253239ffb17e' AND gt.achievement_id='a1c98209-bbc4-4049-baa6-a2a7c9ee0c66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8ea1703e-387f-5d8f-a982-116e1c20f2af','Cultural neutralization','A translation strategy in which a culture-specific reference is replaced with a more general, culturally neutral term that carries no strong source- or target-culture marking. The specific cultural color is lost, but the basic meaning is kept and the reference no longer puzzles the target audience.','This swaps a very local reference for a plain, neutral word. A specific brand might become just a soda. The meaning stays, but the local flavor is dropped.','It removes a reference that would confuse or distract the target audience while keeping the sentence''s basic sense, without importing a new target-culture reference.','When a niche local brand would mean nothing abroad, the adapter replaces it with a generic word so the line still reads clearly.','Cultural Adaptation',ARRAY['Generalization','Cultural retention','Cultural explicitation','Cultural compensation','Extralinguistic cultural reference','Domestication']::text[],ARRAY['Neutralizing a reference that is actually important to the plot or character.','Confusing neutralization with substitution, which swaps in a target-culture reference.','Flattening so many references that the dub loses the source''s identity.']::text[],ARRAY['Turning a little-known local snack into a candy for a global dub.','Replacing a regional TV show reference with a neutral phrase.','Smoothing an obscure place name into a generic location.']::text[],'a1c98209-bbc4-4049-baa6-a2a7c9ee0c66'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8ea1703e-387f-5d8f-a982-116e1c20f2af' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cultural neutralization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
